  FT["PH-H6697"] = {"id":"PH-H6697","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8219_1996.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 Radioworld 广播公司在菲律宾建设、安装、设立、运营和维护广播电视站的特许经营权法案","en":"An Act Granting Radioworld Broadcasing Corporation, a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the Philippines","orig":"An Act Granting Radioworld Broadcasing Corporation, a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8219","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-08-12","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8219_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6697-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Radioworld Broadcasting: Corporation, hereunder referred to as the grantee, its successor assigns, a franchise to construct, install establish, operate and maintain for commercial purposes and in the public interest radio and/or television broadcasting station in the Philippines, where frequency and/or channels are still available for radio and/or television broadcasting, with the corresponding technological auxiliaries facilities, special broadcast and other program and distribution services and relay station."}},{"id":"PH-H6697-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6697-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for the construct and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6697-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information on willful misrepresentation to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H6697-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said station or facilities during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the state and may be withdrawn anytime, after due process."}},{"id":"PH-H6697-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\n(a) Commence operations within one (1) year from the approval of its permit by the National Telecommunications Commission;\n(b) Operate continuously for two (2) years;\n(c) Commence operations within three (3) years from the effectivity of this Act."}},{"id":"PH-H6697-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given (60) days after the in writing within sixty effectivity of this Act. Upon giving such shall exercise the acceptance, the grantee privileges granted under this Act. Non acceptance shall render the franchise void."}},{"id":"PH-H6697-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bond. - The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6697-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons of corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of five percent (5%) per annum or at such percentage as may be prescribed by law on all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns, whichever is higher: Provided, that the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment, is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance the National Internal Revenue Code ant the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6697-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Self-Regulation by und Undertaking of Grantee. - The grantee Shall not require any previous censorship of speech, play, act or scene, or other matter to be broadcast from its stations: Provided that, the grantee, during any broadcast shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6697-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Warranty in Favor of Nat and Local Government. - The grantee hold the national, provincial and municipal governments of the Philippines ban from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, cause by the construction or operation of stations of the grantee."}},{"id":"PH-H6697-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer Usufruct etc. - The grantee shall not lease, transfer grant the usufruct of, sell nor assign this franchise or the rights and privileged acquired there under to any person, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transfer whether as a whole or in parts and whether simultaneously or contemporaneously to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6697-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Dispersal of Ownership. - In accordance with constitutional provisions to encourage public participation in public utilities, the grantee shall offer at least thirty percentum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) from the time it has achieved the status of a national broadcasting network. A \"national broadcasting network\" is hereby defined as one that operates three or more radio and/or television stations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6697-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6697-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6697-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repeatability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines, when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6697-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6697-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectively. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers general circulation in the of Philippines"}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Radioworld Broadcasing Corporation, a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6698"] = {"id":"PH-H6698","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8220_1996.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"在菲律宾武装部队士兵军衔中设立一级军士长与高级军士长职级、为此拨款并为其他目的法案","en":"An Act Creating the Ranks of Chief Master Sergeant/Master Chief Petty Officer and Senior Master Sergeant/Senior Chief Petty Officer in the Enlisted Ranks of the Armed Forces of the Philippines, Appriating Funds Therefor, and for Other Purposes","orig":"An Act Creating the Ranks of Chief Master Sergeant/Master Chief Petty Officer and Senior Master Sergeant/Senior Chief Petty Officer in the Enlisted Ranks of the Armed Forces of the Philippines, Appriating Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 8220","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-10-09","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8220_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6698-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. - It is the policy State to develop and professionalize the Armed Forces and to provide adequate remuneration and benefits to its members. Career development and promotion shall be established to insure a progression of all personnel of the Armed Forces of the Philippines and to provide them with appropriate career motivations."}},{"id":"PH-H6698-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Creation of Ranks. - The grades of Chief Master Sergeant/Master Chief Petty Officer (E-9) and Senior Master Sergeant/Senior Chief Petty Officer (E-8) shall be created and shall form a component part of the noncommissioned officers grades of the Armed Forces of the Philippines."}},{"id":"PH-H6698-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Distribution of Positions. - The total number of Senior Master Sergeants/ Senior Chief Petty Officer and Chief Master Sergeant/Master Chief Petty Officers shall be in accordance with the number of authorized positions in the approved Table of Organization, as provided for by Republic Act No. 7898, otherwise known as the AFP Modernization Act."}},{"id":"PH-H6698-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Qualifications. - Qualifications for promotion from Master Sergeant/Chief Petty Officer to Senior Master Sergeant/Senior Chief Petty Officer and from Senior Master Sergeant/Senior Chief Petty Officer to Chief Master Sergeant/Master Chief Petty Officer shall be based on merit, fitness and other qualifications to be determined by the Secretary of National Defense."}},{"id":"PH-H6698-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Compensation. - Qualified Master Sergeants/Chief Petty Officers shall be eligible for promotion to Senior Master Sergeant/Senior Chief Petty Officer: qualified Senior Master Sergeant/Senior Chief Petty Officer to Chief Master Sergeant/Master Chief Petty Officer. A Chief Master Sergeant/Master Chief Petty Officer shall receive a monthly base pay equivalent to the monthly base pay of a Master Sergeant/ Chief Petty Officer plus one-half (1/2) of the difference between the monthly base pay of a Second Lieutenant/Ensign and a Master Sergeant/Chief Petty Officer. A Senior Master Sergeant/Senior Chief Petty Officer shall receive a monthly base pay equivalent to the monthly base pay of a Master Sergeant/ Chief Petty Officer plus one-half (1/2) of the difference between the monthly base pay of a Chief Master Sergeant/Master Chief Petty Officer and a Master Sergeant/Chief Petty Officer. The computation of their quarters allowance shall also be based on the same scheme."}},{"id":"PH-H6698-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Retirement and Separation. - The enlisted personnel who attain the rank of Master Sergeant/Chief Petty Officer, Senior Master Sergeant/Senior Chief Petty Officer and of Chief Master Sergeant/Master Chief Petty Officer shall, upon retirement be entitled to the retirement pay and benefits of a Second Lieutenant/Ensign: Provided, That a Chief Master Sergeant/Master Chief Petty Officer retired from the AFP, shall receive a gratuity equivalent to that of a Second Lieutenant/ Ensign, plus one-half (1/2) of the difference between the gratuity of a Second Lieutenant /Ensign and a Master Sergeant/Chief Petty Officer, and a Senior Master Sergeant/Senior Chief Petty Officer shall receive a gratuity equivalent to that of a Second Lieutenant/ Ensign, plus one-half (1/2) of the difference between the gratuity of a Chief Master Sergeant/Master Chief Petty Officer and a Master Sergeant/Chief Petty Officer, payable in one lump sum: Provided, further , That the Chief Master Sergeant/Master Chief Petty Officer and Senior Master Sergeant/ Senior Chief Petty Officer may opt to receive a monthly retirement pay, in lieu of gratuity, the computation of which shall be based on the same scheme: Provided, further more, That upon his retirement, he shall be entitled, at his option, to receive in advance his lump sum annual retirement pay for the first three (3) years and thereafter receive his annual retirement pay payable in equal monthly installments as they accrue: Provided, finally, That if he dies within the three-year period following his retirement and is survived by beneficiaries as defined in Presidential Decree No. 1638, the latter shall only receive the derivative benefits there under starting the first month after the aforecited three-year period.\nNothing in this section shall be construed as authorizing adjustment of pay, or payment of any differential in retirement pay to officers and enlisted men who are already retired prior to the approval of this Act as a result of increases in salary of those in the active service: Provided, That retirees who are recalled to active duty may have their retirement pension adjusted based on the rank they hold and on the prevailing pay of military personnel in the active service, at the time of the termination of their recall to active duty."}},{"id":"PH-H6698-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Selection of AFP Command Sergeant Major. - The AFP Command Sergeant Major shall be selected from among the Chief Master Sergeants/Master Chief Petty Officers under such rules and regulations that the Chief of Staff, AFP, may prescribed: Provided that unless sooner terminated the Chief of Staff, AFP, the AFP Command Sergeant Major shall serve for a maximum term of three (3) years."}},{"id":"PH-H6698-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Maximum Tenure-in-Grade. - Secretary of National Defense shall determine the maximum tenure-in-grade of enlisted personnel in the ranks of Master Sergeant/Chief Petty Officer, Senior Master Sergeant/Senior Chief Petty Officer, and Chief Master Sergeant/Master Chief Officer."}},{"id":"PH-H6698-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Implementing Rules and Regulations. - The Secretary of National Defense shall, within ninety (90) days after the approval of this Act, promulgate the necessary rules and regulations and other guidelines for the effective implementation of this Act."}},{"id":"PH-H6698-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Appropriations. – The amount necessary for the effective implementation this Act shall be charged to the appropriations of the Department of National Defense under the current General Appropriations Act. Thereafter, such sum as may be necessary for its continued implementation shall be included in the annual General Appropriations Act."}},{"id":"PH-H6698-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability Clause. – Any portion or provision of this Act declared unconstitutional shall effect of nullifying other portion or provisions hereof."}},{"id":"PH-H6698-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations and other issuances or parts thereof which are inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6698-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of national circulation.\nApproved, October 9, 1996."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Ranks of Chief Master Sergeant/Master Chief Petty Officer and Senior Master Sergeant/Senior Chief Petty Officer in the Enlisted Ranks of the Armed Forces of the Philippines, Appriating Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6699"] = {"id":"PH-H6699","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8221_1996.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"开发Capas国家纪念园并为此拨款及为其他目的法案","en":"An Act to Develop the Capas National Shrine, Appropriating Funds Therefor, and for Other Purposes","orig":"An Act to Develop the Capas National Shrine, Appropriating Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8221","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-08-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8221_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6699-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Capas National Shrine, more particularly described as follows, is placed under the administration of the Military Shrine Service, Philippine Veterans Affairs Office.\nCapas National Shrine\nA parcel of land, being a portion of Zone “8” of the Clark Air Base Military Reservation, situated at Barangay Aranguren, Capas, Tarlac, bounded on the east along lines 1-2 by Lot No. 1902 Cad. No. 615-D (PSU-43293, Lot-3); on the south along lines 2-3 by portion of reservation (PSU-2427); on the north along lines 4-5-6-7-8-9-1 by the provincial road. Beginning at the point marked \"1\", being N. 82 deg. 55' W., 204.12 m. from BLLM No. 6, Cad. 615-D. Thence\nS. 03 deg. 49'E., 1,000.00 m. to point 2;\nS. 86 deg. 11W.,\n529.81 m. to point 3;\nN. 03 deg. 49'W.,\n839.00 m. to point 4;\nN. 59 deg. 38'E.,\n229.23 m. to point 5;\nN. 64 deg 19'E.,\n52.20 m. to point 6;\nN. 72 deg. 49'E.,\n59.25 m. to point 7;\nN. 77 deg. 14E.,\n28.23 m. to point 8;\nN. 82 deg. 56'E.,\n82.18 m. to point 9;\nN. 77 deg. 38'E.,\n109.95 m. to the point of beginning containing an area of five hundred thousand square meters ( 500,000 sq. m. ), more or less."}},{"id":"PH-H6699-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The shrine shall be developed as a memorial, with a monument and auxiliary Facilities dedicated to the memory of those who were incarcerated or died in the Capas Camp during the Second World War: Provided that said memorial shall consist of an area where a tree should be planted in memory of the twenty-five thousand (25,000) Filipino and six thousand (6,000) American soldiers who died in the camp: Provided, further , That the remaining areas in the shrine shall be converted into a mini-forest."}},{"id":"PH-H6699-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the initial implementation of this Act shall be included in the annual General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6699-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, October 9, 1996."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Develop the Capas National Shrine, Appropriating Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6700"] = {"id":"PH-H6700","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8222_1996.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Laoag 教区在 Laoag 市建设、安装、设立、运营和维护广播电视站的特许经营权法案","en":"An Act Granting the Diocese of Laoag a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the City of Laoag","orig":"An Act Granting the Diocese of Laoag a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the City of Laoag"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8222","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-10-24","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8222_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6700-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Diocese of Laoag, hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for religious, educational, as well as commercial purposes and in the public interest, radio and/or television broadcasting stations in the City of Laoag, where frequencies and/or channels are still available for radio and/or television broadcasting, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H6700-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, a most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof. In no way shall the radiated power of the grantee's station or facilities exceed that required to cover the area where it is allowed to operate."}},{"id":"PH-H6700-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6700-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H6700-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process."}},{"id":"PH-H6700-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within one (1) year from the approval of its permit by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within three (3) years from the effectivity of this Act."}},{"id":"PH-H6700-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non - acceptance shall render the franchise void."}},{"id":"PH-H6700-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bond. – The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6700-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of five percent (5%) per annum or at such percentage as may be prescribed by law on all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6700-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Self-regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast, from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6700-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6700-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired there under to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6700-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6700-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6700-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6700-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6700-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Diocese of Laoag a Franchise to Construct, Install, Establish, Operate and Maintain Radio and Television Broadcasting Stations in the City of Laoag","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6701"] = {"id":"PH-H6701","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8223_1996.html","fetchedAt":"2026-10-06","articleCount":55,"structureMode":"ARTICLE","title":{"zh":"将Marikina镇改制为市","en":"An Act Converting the Municipality of Marikina Into a Highly Urbanized City to Be Known as the City of Marikina","orig":"An Act Converting the Municipality of Marikina Into a Highly Urbanized City to Be Known as the City of Marikina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8223","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-06","completenessNote":"全文，共 55 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8223_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6701-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Title. – This Act shall be known as the Charter of the City of Marikina."},"text":{"en":"Section 1. Title. – This Act shall be known as the Charter of the City of Marikina."}},{"id":"PH-H6701-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"The City of Marikina. – The Municipality of Marikina is hereby converted into a highly urbanized city to be known as the"},"text":{"en":"Section 2. The City of Marikina. – The Municipality of Marikina is hereby converted into a highly urbanized city to be known as the City of Marikina, hereinafter referred to as the City, which shall comprise the present territory of the Municipality of Marikina in the Metropolitan Manila Area."}},{"id":"PH-H6701-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Corporate Powers of the City of Marikina. – The City constitutes a political body corporate and as such is endowed with"},"text":{"en":"Section 3. Corporate Powers of the City of Marikina. – The City constitutes a political body corporate and as such is endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this Charter. The City shall have the following corporate powers:\n1. To have a continuous succession in its corporate name;\n2. To sue and be sued;\n3. To have and use a corporate seal;\n4. To acquire and convey real or personal property;\n5. To enter into contracts; and\n6. To exercise such other powers as are granted to corporations, subject to the limitations provided in this Act and other laws."}},{"id":"PH-H6701-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"General Powers of the City. – The City shall have a common seal, and may alter the same at pleasure. It shall exercise t"},"text":{"en":"Section 4. General Powers of the City. – The City shall have a common seal, and may alter the same at pleasure. It shall exercise the powers to levy taxes and close roads, streets, alleys, parks or squares. It may take, purchase, receive, hold, lease, convey, and dispose of real and personal property for the general interest of the City; condemn private property for public use; contract and be contracted with; sue and be sued; prosecute and defend to final judgment and execution suits wherein said City is a party; and exercise all the powers as are granted to corporations and/or hereinafter conferred."}},{"id":"PH-H6701-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Liability for Damages. – The City and its officials shall not be exempt from liability for death or injury to person or"},"text":{"en":"Section 5. Liability for Damages. – The City and its officials shall not be exempt from liability for death or injury to person or damage to property."}},{"id":"PH-H6701-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Jurisdiction of the City. – The jurisdiction of the City of Marikina, for police purposes only, shall be coextensive wit"},"text":{"en":"Section 6. Jurisdiction of the City. – The jurisdiction of the City of Marikina, for police purposes only, shall be coextensive with its territorial jurisdiction, and for the purpose of protecting and ensuring the purity of the water supply of the City, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters (100 m.) of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The city court of the City shall have concurrent jurisdiction with the city or municipal court of the adjoining cities or municipalities, to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters (100 m.). The court first taking cognizance of such an offense shall have jurisdiction to try said cases to the exclusion of others. The police forces of the several cities and municipalities concerned shall have concurrent jurisdiction with the police force of the City for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued within said zone, area or spaces shall be granted by the proper authorities of the city or municipality concerned, and the fees arising there from shall accrue to the treasury of the said city or municipality concerned and not to the City."}},{"id":"PH-H6701-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II CITY OFFICIALS IN GENERAL"},"heading":{"en":"The Officials of the City of Marikina. –"},"text":{"en":"Section 7. The Officials of the City of Marikina. –\na. There shall be in the City of Marikina, a city mayor, a vice mayor, sangguniang panlungsod members, a secretary to the sangguniang panlungsod, a city prosecutor, a city treasurer and an assistant city treasurer, a city assessor and an assistant city assessor, a city accountant, a city budget officer, a city planning and development coordinator, a city engineer, a city health officer, a city civil registrar, a city administrator, a city legal officer, a city trade and industry officer, a city schools division superintendent, a city veterinarian, a city social welfare and development officer, and a city general services officer.\nb. In addition thereto, the city mayor may appoint a city architect, a city information officer, a city population officer, a city environment and natural resources officer, and a city cooperatives officer.\nc. The City of Marikina may:\n1. Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n2. Create such other offices as may be necessary to carry out the purposes of the City; or\n3. Consolidate the functions of any office with those of another in the interest of efficiency and economy; and\nd. Unless otherwise provided herein, all appointive city officials of the City shall be appointed by the city mayor with the concurrence of the majority of all the sangguniang panlungsod members subject to civil service law, rules and regulations."}},{"id":"PH-H6701-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III THE CITY MAYOR AND VICE MAYOR"},"heading":{"en":"The City Mayor. –"},"text":{"en":"Section 8. The City Mayor. –\na. The city mayor shall be the chief executive of the City. He shall be elected at large by the qualified voters of the City. No person shall be eligible for the position of the city mayor unless at the time of the election he is at least twenty-three (23) years of age, an actual resident of the City for at least one (1) year prior to his election and a qualified voter therein. He shall hold office for three (3) years, unless sooner removed, and shall receive a minimum monthly compensation corresponding to Salary Grade Thirty (30) as prescribed under Republic Act No. 6758 and the implementing guidelines issued pursuant thereto.\nb. The city mayor, as the chief executive of the city government, shall exercise such powers and perform such duties and functions as provided herein:\n1. Exercise those powers expressly granted to him by law, those necessarily implied therefrom, as well as powers necessary, appropriate, or incidental for the efficient and effective governance of the City, and those which are essential to the promotion of the general welfare:\n(aa) Determine the guidelines of city policies and be responsible to the sangguniang panlungsod for the program of government;\n(bb) Direct the formulation of the city development plan, with the assistance of the city development council and upon approval thereof by the sangguniang panlungsod, implement the same;\n(cc) Present the program of government and propose policies and projects for the consideration of the sangguniang panlungsod at the opening of the regular session of the sangguniang panlungsod every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the city government may require;\n(dd) Initiate and propose legislative measures to the sangguniang panlungsod and as often as may be deemed necessary, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(ee) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of city funds and whose appointments are not otherwise provided for in this Act, as well as those he may be authorized by law to appoint;\n(ff) Represent the City in all its business transactions and sign in its behalf all bonds, contracts, and obligations, and such other documents upon authority of the sangguniang panlungsod or pursuant to law or ordinance;\n(gg) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(hh) Determine the time, manner and place of payment of salaries and wages of the officials and employees of the City, in accordance with law or ordinance;\n(ii) Allocate and assign office space to city and other officials and employees who, by law or ordinance, are entitled to such space in the city hall and other buildings owned or leased by the city government;\n(jj) Ensure that all executive officials and employees of the City faithfully discharge their duties and functions as provided by law and this Act, and cause to be instituted administrative or judicial proceedings against any official or employee of the City who may have committed an offense in the performance of his official duties;\n(kk) Examine the books, records and other documents of all offices, officials, agents or employees of the City and, in aid of his executive power and authority, require all national officials and employees stationed in or assigned to the City to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(ll) Furnish copies of executive orders issued by him to the respective council chairmen within seventy-two (72) hours after their issuances;\n(mm) Visit component barangays of the City at least once every six (6) months to deepen his understanding of problems and conditions, listen and give appropriate counsel to local officials and inhabitants of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the City will improve the quality of life of the inhabitants;\n(nn) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of their leave credits in accordance with law;\n(oo) Authorize official trips of city officials and employees outside of the City for a period not exceeding thirty (30) days;\n(pp) Call upon any national official or employee stationed in or assigned to the City to advise him on matters affecting the City and to make recommendations thereon; coordinate with said official or employee in the formulation and implementation of plans, programs and projects; and, when appropriate, initiate any administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the City;\n(qq) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of city officials and employees who are injured while in the performance of their official duties and functions, subject to availability of funds;\n(rr) Solemnize marriages, any provision of law to the contrary notwithstanding;\n(ss) Conduct an annual palarong panlungsod, which shall feature traditional sports and disciplines included in national and international games in coordination with the Department of Education, Culture and Sports; and\n(tt) Submit to the respective metropolitan authority council chairmen and to the Office of the President the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the City and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the City;\n2. Enforce all laws and ordinances relative to the governance of the City and in the exercise of its appropriate corporate powers, as well as implement all approved policies, programs, projects, services and activities of the City:\n(aa) Ensure that the acts of the City's component barangays and of its officials and employees are within the scope of their prescribed powers, duties and functions;\n(bb) Call conventions, conferences, seminars, or meetings of elective and appointive officials of the City, including national officials and employees stationed in or assigned to the City, at such time and place and on such subject as he may deem important for the promotion of the general welfare of the local government unit and its inhabitants;\n(cc) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(dd) Be entitled to carry the necessary firearm within his territorial jurisdiction;\n(ee) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the City and upon its approval, implement the same; and as such, exercise general and operational control and supervision over the local police forces in the City, in accordance with Republic Act No. 6975; and\n(ff) Call upon the appropriate law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition, or to apprehend violators of the law when public interest so requires and the city police forces are inadequate to cope with the situation or the violators;\n3. Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities, particularly those resources and revenues programmed for agro-industrial development and growth and progress:\n(aa) Require each head of office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process in accordance with the provisions of the Local Government Code;\n(bb) Prepare and submit to the sanggunian for approval the executive and supplemental budgets of the City for the ensuing calendar year in the manner provided for under the Local Government Code;\n(cc) Ensure that all taxes and other revenues of the City are collected, and that city funds are applied to the payment of expenses and settlement of obligations of the City, in accordance with law or ordinance;\n(dd) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(ee) Issue permits, without need of approval therefor from any national agency, for the holding of activities for any charitable or welfare purposes, excluding prohibited games of chance or shows contrary to law, public policy and public morals;\n(ff) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permit, subject to such fines and penalties as may be imposed by law or ordinance or to make necessary changes in the construction of the same when said construction violates any law or ordinance, or to order the demolition or removal of said house, building or structure within the period prescribed by law or ordinance;\n(gg) Adopt adequate measures to safeguard and conserve land, mineral, and, marine and forest (should these resources be geographically present), and other resources of the City;\n(hh) Provide efficient and effective property and supply management in the City; and protect the funds, credits, rights and other properties of the City; and\n(ii) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property; and cause the City to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n4. Ensure the delivery of basic services and the provision of adequate facilities and, in addition thereto:\n(aa) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of roads and bridges of the City; and\n(bb) Coordinate the implementation of technical services, including public works and infrastructure programs, rendered by national offices;\n5. Perform such other duties and functions and exercise such other powers, as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III THE CITY MAYOR AND VICE MAYOR"},"heading":{"en":"The City Vice Mayor. –"},"text":{"en":"Section 9. The City Vice Mayor. –\na. There shall be a vice mayor who shall be elected in the same manner as the city mayor and shall, at the time of his election, possess the same qualifications as the city mayor. He shall hold office for three (3) years, unless sooner removed, and shall receive a monthly compensation corresponding to Salary Grade twenty-eight (28) as prescribed under Republic Act No. 6758 and the implementing guidelines issued pursuant thereto.\nb. The vice mayor shall:\n1. Act as presiding officer of the sangguniang panlungsod and sign all warrants drawn on the city treasury for all expenditures appropriated for the operation of the sangguniang panlungsod;\n2. Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang panlungsod, except those whose manner of appointment is specifically provided for under existing laws;\n3. Assume the office of the city mayor for the unexpired term of the latter in the event of permanent vacancy;\n4. Exercise the powers and perform the duties and functions of the city mayor in cases of temporary vacancy; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE IV THE SANGGUNIANG PANLUNGSOD"},"heading":{"en":"The Sangguniang Panlungsod. –"},"text":{"en":"Section 10. The Sangguniang Panlungsod. –\na. The sangguniang panlungsod, the legislative body of the City, shall be composed of the city vice mayor as presiding officer, the regular sanggunian members, the president of the city chapter of the liga ng mga barangay, the president of the panlungsod na pederasyon ng mga sangguniang kabataan, and the sectoral representatives, as members.\nb. In addition thereto, there shall be three (3) sectoral representatives: one (1) from the women; and as shall be determined by the sangguniang panlungsod within ninety (90) days prior to the holding of the local elections, one (1) from the agricultural or industrial workers; and one (1) from other sectors, including the urban poor, indigenous cultural communities, and disabled persons.\nc. The regular members of the sangguniang panlungsod and the sectoral representatives shall be elected in the manner as may be provided for by law. The elective members of the sangguniang panlungsod shall possess the same qualifications as those of the city mayor and vice mayor.\nd. They shall receive such compensation, emoluments and allowances as may be determined by law.\ne. The sangguniang panlungsod shall:\n1. Approve ordinances and pass resolutions necessary for an efficient and effective city government, and, in this connection, shall:\n(aa) Review all ordinances approved by the sangguniang barangay and executive orders issued by the punong barangay to determine whether these are within the scope of the prescribed powers of the sanggunian and of the punong barangay;\n(bb) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(cc) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000) or an imprisonment for a period not exceeding one (1) year, or both at the discretion of the court, for the violation of city ordinances;\n(dd) Adopt measures to protect the inhabitants of the City from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters or calamities and in their return to productive livelihood following said events;\n(ee) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publications, and such other activities inimical to the welfare and morals of the inhabitants of the City;\n(ff) Protect the environment and impose appropriate penalties for acts which endanger the environment and such other activities which result in pollution acceleration or eutrophication of creeks and streams or of ecological imbalance;\n(gg) Subject to the provisions of the Local Government Code and pertinent laws, determine the powers and duties of officials and employees of the City;\n(hh) Determine the positions and the salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from city funds and provide for expenditure necessary for the proper conduct of programs, projects, services, and activities of the city government;\n(ii) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy or grant honoraria to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity at the rate authorized by law;\n(jj) Provide a mechanism and the appropriate funds therefor, to ensure the safety and protection of all city government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the city government;\n(kk) When the finances of the city government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed in or assigned to the City;\n(ll) Provide legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(mm) Provide for group insurance or additional insurance coverage for all barangay officials, including members of barangay tanod brigades and other service units, with public or private insurance companies, when the finances of the city government may allow said coverage;\n2. Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the City, with particular attention to agro-industrial development and city-wide growth and progress:\n(aa) Approve the annual and supplemental budgets of the city government and appropriate funds for specific programs, projects, services and activities of the City, or other purposes not contrary to law, in order to promote the general welfare of the City and its inhabitants;\n(bb) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all the members of the sangguniang panlungsod, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or reliefs;\n(cc) Subject to the provisions of Book II of the Local Government Code and upon the majority vote of all the members of the sangguniang panlungsod, authorize the city mayor to negotiate and contract loans and other forms of indebtedness;\n(dd) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all the members of the sangguniang panlungsod, enact ordinances authorizing the flotation of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(ee) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the City; and, upon the majority vote of all the members of the sangguniang panlungsod, authorize the city mayor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(ff) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the City;\n(gg) Adopt a comprehensive land use plan for the City;\n(hh) Reclassify lands within the jurisdiction of the City, subject to the pertinent provisions of the Local Government Code;\n(ii) Enact integrated zoning ordinances in consonance with the approved comprehensive land use plan, subject to existing laws, rules and regulations; establish fire limits or zones, particularly in populous centers; and regulate the construction, repair or modification of buildings within said fire limits or zones in accordance with the provisions of the Fire Code;\n(jj) Subject to the provisions of any law to the contrary notwithstanding, process and approve subdivision plans for residential, commercial, or industrial purposes and other development purposes, and to collect processing fees and other charges, the proceeds of which shall accrue entirely to the City: Provided, however, That where approval of a national agency or office is required, said approval shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval thereof;\n(kk) With the concurrence of at least two-thirds (2/3) of all the members of the sangguniang panlungsod, grant tax exemptions, incentives or reliefs to entities engaged in community growth-inducing industries, in accordance with the provisions of the Local Government Code;\n(ll) Grant loans or provide grants to other local government units or national, provincial, and city charitable, benevolent or educational institutions: Provided, That said institutions are operated and maintained within the City;\n(mm) Regulate the numbering of residential, commercial and other buildings; and\n(nn) Regulate the inspection, weighing and measuring of articles of commerce;\n3. Subject to the provisions of the Local Government Code of 1991, enact ordinances granting franchises and authorizing the issuance of permits or licenses, upon such conditions and for such purpose intended to promote the general welfare of the inhabitants of the City and pursuant to this legislative authority, shall:\n(aa) Fix and impose reasonable fees and charges for all services rendered by the city government to private persons or entities;\n(bb) Regulate or fix license fees for any business or practice of profession within the City and the condition under which the license for said business or practice of profession may be revoked and enact ordinances levying taxes thereon;\n(cc) Provide for and set the terms and conditions under which public utilities owned by the City shall be operated by the city government, and prescribe the conditions under which the same may be leased to persons or entities, preferably cooperatives;\n(dd) Regulate the display of and fix the license fees for signs, signboards, or billboards at the place or places where the profession or business advertised thereby is, in whole or in part, conducted;\n(ee) Any laws to the contrary notwithstanding, authorize and license the establishment, operation and maintenance of cockpits, and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights shall not be impaired;\n(ff) Subject to the guidelines prescribed by the Department of Transportation and Communications, regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the City; and\n(gg) Upon approval by a majority vote of all the members of the sangguniang panlungsod: grant a franchise to any person, partnership, corporation, or cooperative to do business within the City; establish, construct, operate and maintain ferries, wharves, markets or slaughterhouses; or undertake such other activities within the City as may be allowed by existing laws: Provided, That cooperatives shall be given preference in the grant of such franchise;\n4. Regulate activities relative to the use of land, buildings and structure within the City in order to promote the general welfare and for the said purpose, shall:\n(aa) Declare, prevent or abate any nuisance;\n(bb) Require that buildings and the premises thereof and any land within the City be kept and maintained in a sanitary condition; impose penalties for any violation thereof; or, upon failure to comply with said requirement, have the work done at the expense of the owner, administrator or tenant concerned; or require the filling up of any land or premises to a grade necessary for proper sanitation;\n(cc) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(dd) Regulate the establishment, operation and maintenance of cafes, restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses, and other similar establishments, including tourist guides and transports;\n(ee) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(ff) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the City;\n(gg) Regulate the establishment, operation and maintenance of entertainment or amusement facilities, including theatrical performance, circuses, billiard pools, public dancing schools, public dance halls, sauna baths, massage parlors, and others for entertainment or amusement; regulate such other events or activities for amusement or entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community;\n(hh) Provide for the impounding of stray animals; regulate the keeping of animals in homes or as part of a business, and the slaughter, sale or disposition of the same, and adopt measures to prevent and penalize cruelty to animals; and\n(ii) Regulate the establishment, operation and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations;\n5. Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided for under the Local Government Code, and, in addition to said services and facilities, shall:\n(aa) Provide for the establishment, maintenance, protection, and conservation of tree parks, green belts, and other similar development projects;\n(bb) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof by the city government; and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(cc) Authorize the establishment, maintenance and operation by the city government of ferries, wharves, and other structure intended to accelerate productivity related to riverine activities;\n(dd) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products, and other foodstuffs for public consumption;\n(ee) Regulate the use of streets, avenues, alley, sidewalks, bridges, parks and other public places and approve the construction, improvement, repair and maintenance of the same; establish bus and vehicle stops and terminals or regulate the use of the same by privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; and provide for the lighting, cleaning and sprinkling of streets and public places;\n(ff) Regulate traffic on all streets and bridges; prohibit encroachments or obstacles thereon and, when necessary in the interest of public welfare, authorize the removal of encroachments and illegal constructions in public places;\n(gg) Subject to existing laws, establish and provide for the maintenance, repair and operation of an efficient waterworks system to supply water to the inhabitants and to purify the source of water supply; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and quantity of the water supply of the City and, for this purpose, extend the coverage of appropriate ordinances over all territory within the drainage area of said water supply and within one hundred meters (100 m.) of the reservoir, conduit, canal, aqueduct, or pumping station, used in connection with the water service; and regulate the consumption, use or wastage of water and fix and collect charges therefore;\n(hh) Regulate the drilling and excavation of the ground for the laying of water, gas, sewer, and other pipes and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalk, curbs, and gutters; adopt measures to ensure public safety against open canals, manholes, live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(ii) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric, telegraph and telephone wires, conduits, meters and other apparatus; and provide for the correction, condemnation or removal of the same when found to be dangerous, defective or otherwise hazardous to the welfare of the inhabitants;\n(jj) Subject to the availability of funds, and, to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the Department of Education, Culture and Sports and subject to existing law on tuition fees, fix and collect reasonable tuition fees and other school charges in educational institutions supported by the city government;\n(kk) Establish a scholarship fund for poor but deserving students in schools located within its jurisdiction or for students residing within the City;\n(ll) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases;\n(mm) Provide for an efficient and effective system of solid waste disposal and garbage collection, and prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(nn) Provide for the care of disabled persons, paupers, the aged, the sick, persons of unsound mind, abandoned minors, juvenile delinquents, drug dependents, abused children and other needy and disadvantaged persons, particularly children and youth below eighteen (18) years of age; and, subject to availability of funds, establish and provide for the operation of centers and facilities for said needy and disadvantaged persons;\n(oo) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program, and appropriate funds for the subsistence of detainees and convicted prisoners in the City;\n(pp) Establish a city council whose purpose is to promote culture and the arts, coordinate with government agencies and nongovernmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(qq) Establish a city council for the elderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the community, provide incentives for nongovernmental organizations and entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly; and\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991 and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Internal Rules of Procedure. –"},"text":{"en":"Section 11. Internal Rules of Procedure. –\na. On the first regular session following the election of its members and within ninety (90) days thereafter, the sangguniang panlungsod shall adopt or update its existing rules of procedure.\nb. The rules of procedure shall provide for the following:\n1. The organization of the sanggunian and the election of its officers as well as the creation of standing committees which shall include, but not be limited to, the committees on appropriations, women and family, human rights, youth and sports development, environmental protection, and cooperatives; the general jurisdiction of each committees; and the election of the chairmen and members of each committee;\n2. The order and calendar of business for each session;\n3. The legislative process;\n4. The parliamentary procedures which shall include the conduct of members during sessions;\n5. The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions for which they may be censured, reprimanded, or excluded from the session, or suspended for not more than sixty (60) days, or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) vote of all the sanggunian members: Provided, further, That a member convicted by final judgment to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the sanggunian; and\n6. Such other rules as the sanggunian may adopt."}},{"id":"PH-H6701-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Full Disclosure of Financial and Business Interest of Sangguniang Panlungsod Members. –"},"text":{"en":"Section 12. Full Disclosure of Financial and Business Interest of Sangguniang Panlungsod Members. –\na. Every sangguniang panlungsod member shall, upon assumption to office, make a full disclosure of his business and financial interest. He shall also disclose his business, financial, or professional relationship or any relation by affinity or consanguinity within the fourth civil degree, which he may have with any person, firm or entity affected by any ordinance or resolution under consideration by the sanggunian of which he is a member, which relationship may result in conflict of interest. Such relationship shall include:\n1. Ownership of stock or capital, or investment in the entity or firm to which an ordinance or resolution may apply; and\n2. Contracts or agreements with any person or entity which an ordinance or resolution under consideration may affect. In the absence of a specific constitutional or statutory provision applicable to these situations, \"conflict of interest\" refers in general to one where it may be reasonably deduced that a member of a sanggunian may not act in the public interest due to some private, pecuniary, or other personal considerations that may tend to affect his judgment to the prejudice of the service or the public.\nb. The disclosure required under this Act shall be made in writing and submitted to the secretary of the sanggunian or the secretary of the committee of which he is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n1. Disclosure shall be made before the member participates in the deliberations on the ordinance or resolution under consideration: Provided, That, if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n2. Disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection, or professional relationship described herein."}},{"id":"PH-H6701-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Sessions. –"},"text":{"en":"Section 13. Sessions. –\na. On the first day of the session immediately following the election of its members, the sangguniang panlungsod shall, by resolution, fix the day, time, and place of its regular sessions. The minimum number of regular sessions shall be once a week for the sangguniang panlungsod, and twice a month for the sangguniang barangay.\nb. When public interest so demands, special sessions may be called by the city mayor or by a majority of the members of the sanggunian.\nc. All sanggunian sessions shall be open to the public unless a closed-door session is ordered by an affirmative vote of a majority of the members present, there being a quorum, in the public interest or for reasons of security, decency, or morality. No two (2) sessions, regular or special, may be held in a single day.\nd. In the case of special sessions of the sanggunian, a written notice to the members shall be served personally at the member's place of residence at least twenty-four (24) hours before the special session is held.\nUnless otherwise concurred in by two-thirds (2/3) vote of the sanggunian members present, there being a quorum, no other matter may be considered at a special session except those stated in the notice.\ne. The sanggunian shall keep a journal and record of its proceedings which may be published upon resolution of the sangguniang panlungsod."}},{"id":"PH-H6701-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Quorum. –"},"text":{"en":"Section 14. Quorum. –\na. A majority of all the members of the sanggunian who have been elected and qualified shall constitute a quorum to transact official business. Should a question of quorum be raised during a session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the results.\nb. Where there is no quorum, the presiding officer may declare a recess until such time a quorum is constituted, or a majority of the members present may adjourn from day-to-day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the sanggunian, to be assisted by a member or members of the police force assigned in the territorial jurisdiction of the City, to arrest the absent member and present him at session.\nc. If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H6701-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Approval of Ordinances. –"},"text":{"en":"Section 15. Approval of Ordinances. –\na. Every ordinance enacted by the sangguniang panlungsod shall be presented to the city mayor. If the city mayor approves the same, he shall affix his signature on each and every page thereof; otherwise, he shall veto it and return the same with his objections to the sanggunian, which may proceed to reconsider the same. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\nb. The veto shall be communicated by the city mayor to the sanggunian within ten (10) days; otherwise, the ordinance shall be deemed approved as if he had signed it."}},{"id":"PH-H6701-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Veto Power of the City Mayor. –"},"text":{"en":"Section 16. Veto Power of the City Mayor. –\na. The city mayor may veto any ordinance of the sangguniang panlungsod on the ground that it is ultra vires or prejudicial to the public welfare, stating his reason therefore in writing.\nb. The city mayor shall have the power to veto any particular item or items of an appropriations ordinance, an ordinance or resolution adopting a local development plan and public investment program, or an ordinance directing the payment of money or creating liability. In such a case, the veto shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the sangguniang panlungsod overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\nc. The city mayor may veto an ordinance or resolution only once. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the city mayor."}},{"id":"PH-H6701-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Review of Barangay Ordinances by the Sangguniang Panlungsod. –"},"text":{"en":"Section 17. Review of Barangay Ordinances by the Sangguniang Panlungsod. –\na. Within ten (10) days after its enactment, the sangguniang barangay shall furnish copies of all barangay ordinances to the sangguniang panlungsod for review as to whether the ordinance is consistent with law and city ordinances.\nb. If the sangguniang panlungsod fails to take action on barangay ordinances within thirty (30) days from receipt thereof, the same shall be deemed approved.\nc. If the sangguniang panlungsod finds the barangay ordinances inconsistent with law or city ordinances, the sangguniang panlungsod shall, within thirty (30) days from receipt thereof, return the same with its comments and recommendations to the sangguniang barangay concerned for adjustment, amendment, or modification; in which case, the effectivity of the barangay ordinance is suspended until such time the revision called for is effected."}},{"id":"PH-H6701-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Enforcement of Disapproved Ordinances or Resolutions. – Any attempt to enforce any ordinance or any resolution approving"},"text":{"en":"Section 18. Enforcement of Disapproved Ordinances or Resolutions. – Any attempt to enforce any ordinance or any resolution approving the local development plan and public investment program, after the disapproval thereof, shall be sufficient ground for the suspension or dismissal of the official or employee concerned."}},{"id":"PH-H6701-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Effectivity of Ordinances or Resolutions. –"},"text":{"en":"Section 19. Effectivity of Ordinances or Resolutions. –\na. Unless otherwise stated in the ordinance or the resolution approving the local development plan and public investment program, the same shall take effect after ten (10) days from the date a copy thereof is posted in a bulletin board at the entrance of the City Hall, and in at least two (2) other conspicuous places in the City.\nb. The secretary of the sangguniang panlungsod shall cause the posting of an ordinance or resolution in the bulletin board at the entrance of the city hall of Marikina and in at least two (2) conspicuous places in the City of Marikina not later than five (5) days after approval thereof. The text of the ordinance or resolution shall be disseminated and posted in Filipino or English and in the language or dialect understood by the majority of the people in the City, and the secretary of the sangguniang panlungsod shall record such fact in the book kept for the purpose, stating the dates of approval and posting.\nc. The main features of the ordinance or resolution duly enacted or adopted shall, in addition to being posted, be published once in a local newspaper of general circulation within the City: Provided, That, in the absence thereof, the ordinance or resolution shall be published in any newspaper of general circulation: Provided, further, That the gist of all ordinances with penal sanctions shall also be published in a newspaper of general circulation."}},{"id":"PH-H6701-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Disqualifications for Elective City Officials. – The following persons are disqualified from running for any elective po"},"text":{"en":"Section 20. Disqualifications for Elective City Officials. – The following persons are disqualified from running for any elective position in the City:\na. Those sentenced by final judgment for an offense involving moral turpitude or for an offense punishable by one (1) year or more of imprisonment, within two (2) years after serving sentence;\nb. Those removed from office as a result of an administrative case;\nc. Those convicted by final judgment for violating the oath of allegiance to the Republic of the Philippines;\nd. Those with dual citizenship;\ne. Fugitives from justice in criminal or nonpolitical cases here and abroad;\nf. Permanent residents in a foreign country or those who have acquired the right to reside abroad and continue to avail of the same right after the effectivity of the Local Government Code; and\ng. The insane or feeble-minded"}},{"id":"PH-H6701-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Permanent Vacancy in the Office of the City Mayor and City Vice Mayor. –"},"text":{"en":"Section 21. Permanent Vacancy in the Office of the City Mayor and City Vice Mayor. –\na. If a permanent vacancy occurs in the office of the city mayor, the city vice mayor shall become the city mayor. If a permanent vacancy occurs in the office of the vice mayor, the highest ranking sangguniang panlungsod member or, in case of his permanent incapacity, the second highest ranking sangguniang panlungsod member, shall become the city mayor or city vice mayor, as the case may be. Subsequent vacancies in the said offices shall be filled automatically by the other sanggunian members according to their ranking as defined herein.\nb. A tie between or among the highest ranking sangguniang panlungsod members shall be resolved by the drawing of lots.\nc. The successors as defined herein shall serve only the unexpired terms of their predecessors. For purposes of this Act, a permanent vacancy arises when an elective local official fills a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions of his office. For purposes of succession as provided in this Act, ranking in the sanggunian shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in the City in the immediately preceding local election."}},{"id":"PH-H6701-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Permanent Vacancies in the Sanggunian. – Permanent vacancies in the sangguniang panlungsod where automatic succession as"},"text":{"en":"Section 22. Permanent Vacancies in the Sanggunian. – Permanent vacancies in the sangguniang panlungsod where automatic succession as provided above does not apply shall be filled by appointment in the following manner:\na. The President, through the Executive Secretary, shall make the aforesaid appointment;\nb. Only the nominee of the political party under which the sanggunian member concerned had been elected shall be appointed in the manner herein provided. The appointee shall come from the same political party as that of the sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office. In the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be a ground for administrative action against the official responsible therefore;\nc. In case the permanent vacancy is caused by a sanggunian member who does not belong to any political party, the city mayor shall, upon recommendation of the sangguniang panlungsod, appoint a qualified person to fill the vacancy; and\nd. In case of vacancy in the representation of the youth and the barangay in the sangguniang panlungsod, said vacancy shall be filled automatically by the official next-in-rank of the organization concerned."}},{"id":"PH-H6701-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Temporary Vacancy in the Office of the City Mayor. –"},"text":{"en":"Section 23. Temporary Vacancy in the Office of the City Mayor. –\na. When the city mayor is temporarily incapacitated to perform his duties for physical or legal reasons such as, but not limited to, leave of absence, travel abroad, and suspension from office, the city vice mayor, or the highest ranking sangguniang panlungsod member shall automatically exercise the powers and perform the duties and functions of the city mayor, except the power to appoint, suspend, or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\nb. Said temporary incapacity shall terminate upon submission to the sangguniang panlungsod of a written declaration by the city mayor that he has reported back to office. In cases where the temporary incapacity is due to legal causes, the city mayor shall also submit necessary documents showing that said legal causes no longer exist.\nc. When the city mayor is traveling within the country but outside his territorial jurisdiction for a period not exceeding three (3) consecutive days, he may designate in writing the officer-in-charge of his office. Such authority shall specify the powers and functions that the local official concerned shall exercise in the absence of the city mayor except the power to appoint, suspend, or dismiss employees.\nd. In the event, however, that the city mayor fails or refuses to issue such authorization, the city vice mayor, or the highest ranking sangguniang panlungsod member, as the case may be, shall have the right to assume the powers, duties and functions of the said office on the fourth day of absence of the city mayor, subject to the limitations provided in subsection (c) hereof.\ne. Except as provided above, the city mayor shall in no case authorize any local official to assume the powers, duties and functions of the office, other than the city vice mayor, or the highest ranking member of the sangguniang panlungsod, as the case may be."}},{"id":"PH-H6701-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Secretary to the Sangguniang Panlungsod. –"},"text":{"en":"Section 24. The Secretary to the Sangguniang Panlungsod. –\na. There shall be a secretary to the sangguniang panlungsod with the rank and salary equal to a head of department or office.\nb. No person shall be appointed secretary to the sangguniang panlungsod unless he is a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in law, commerce or public administration from a recognized college or university, and a first grade civil service eligible or its equivalent.\nc. The secretary to the sangguniang panlungsod shall take charge of the office of the sangguniang panlungsod and shall:\n1. Attend meetings of the sangguniang panlungsod and keep a journal of its proceedings;\n2. Keep the seal of the City and affix the same with his signature to all ordinances, resolutions, and other official acts of the sangguniang panlungsod and present the same to the presiding officer for his signature;\n3. Forward to the city mayor, for approval, copies of ordinances enacted by the sangguniang panlungsod duly certified by the presiding officer;\n4. Furnish, upon request of any interested party, certified copies of records of public character in his custody, upon payment to the city treasurer of such fees as may be prescribed by ordinance;\n5. Record in a book kept for the purpose, all ordinances and resolutions enacted or adopted by the sangguniang panlungsod, with the dates of passage and publication thereof;\n6. Keep his office and all non-confidential records therein open to the public during the usual business hours;\n7. Translate into the dialect used by the majority of inhabitants all ordinances and resolutions immediately after their approval, and cause the publication of the same together with the original version in the manner provided under the Local Government Code;\n8. Take custody of the local archives and, where applicable, the local library and annually account for the same; and\n9. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Treasurer. –"},"text":{"en":"Section 25. The City Treasurer. –\na. The city treasurer shall be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the city mayor, subject to civil service law, rules and regulations.\nb. The city treasurer shall be under the administrative supervision of the city mayor, to whom he shall report regularly on the tax collection efforts of the City.\nc. No person shall be appointed treasurer unless he is a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in treasury or accounting service for at least five (5) years.\nd. The city treasurer shall receive such compensation, emoluments and allowances as may be determined by law.\ne. The city treasurer shall take charge of the treasury office and shall:\n1. Advise the city mayor, the sangguniang panlungsod, and other local government and national officials concerned regarding disposition of local government funds and on such other matter relative to public finance;\n2. Take custody and exercise proper management of the funds of the City;\n3. Take charge of the disbursement of all funds of the City and such other funds the custody of which may be entrusted to him by law or competent authority;\n4. Inspect private commercial and industrial establishments within the jurisdiction of the City in relation to the implementation of tax ordinances, pursuant to the provisions of the Local Government Code;\n5. Maintain and update the tax information system of the City; and\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Assistant City Treasurer. –"},"text":{"en":"Section 26. The Assistant City Treasurer. –\na. The assistant city treasurer shall be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the city mayor, subject to civil service law, rules and regulations.\nb. No person shall be appointed assistant city treasurer unless he is a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired at least five (5) years of experience in treasury or accounting.\nc. The assistant city treasurer shall receive such compensation, emoluments, and allowances as may be determined by law.\nd. The assistant city treasurer shall assist the city treasurer and perform such other duties as the latter may assign him. He shall have authority to administer oaths concerning notices and notifications to those delinquent in the payment of the real property tax and concerning official matters relating to the accounts of the city treasurer or otherwise arising from the offices of the city treasurer and the city assessor."}},{"id":"PH-H6701-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Assessor. –"},"text":{"en":"Section 27. The City Assessor. –\na. The city assessor must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in real property assessment work or in any related field for at least five (5) years immediately preceding the day of his appointment.\nb. The city assessor shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city assessor shall take charge of the City Assessor's Office, and shall:\n1. Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purposes are properly executed;\n2. Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purpose;\n3. Establish a systematic method of real property assessment;\n4. Install and maintain a real property identification and accounting system;\n5. Prepare, install and maintain a system of tax mapping, showing graphically all properties subject to assessment and gather all data concerning the same;\n6. Conduct frequent physical surveys to verify and determine whether all real properties within the City are properly listed in the assessment rolls;\n7. Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the City;\n8. Prepare a schedule of the fair market values of the different classes of real properties in accordance with the provisions of the Local Government Code;\n9. Issue, upon request of any interested party, certified copies of assessment records of real property and all other records relative to its assessment, upon payment of a service charge or fee to the city treasurer;\n10. Submit every semester a report of all assessments, as well as cancellations and modifications of assessments, to the city mayor and the sangguniang panlungsod; and\n11. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Assistant City Assessor. –"},"text":{"en":"Section 28. The Assistant City Assessor. –\na. The assistant city assessor must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in assessment or in any related field for at least three (3) years immediately preceding the day of his appointment.\nb. The assistant city assessor shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The assistant city assessor shall assist the city assessor and perform such other duties as the latter may assign to him. He shall have the authority to administer oaths on all declarations of real property for the purpose of assessment."}},{"id":"PH-H6701-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Accountant. –"},"text":{"en":"Section 29. The City Accountant. –\na. The city accountant must be a citizen of the Philippines, a resident of the City, of good moral character, and a certified public accountant. He must have acquired experience in the treasury or accounting service for at least five (5) years immediately preceding the day of his appointment.\nb. The city accountant shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city accountant shall take charge of both the Office on Accounting and Internal Audit Services, and shall:\n1. Install and maintain an internal audit system in the City;\n2. Prepare and submit financial statements to the city mayor and to the sangguniang panlungsod;\n3. Apprise the sangguniang panlungsod and other officials on the financial condition and operations of the City;\n4. Certify to the availability of budgetary allotment to which expenditures and obligations may be properly charged;\n5. Review supporting documents before preparation of vouchers to determine completeness of requirements;\n6. Prepare statements of cash advances, liquidation, salaries, allowances, reimbursements, and remittances pertaining to the City;\n7. Prepare statements of journal vouchers and liquidation of the same, and other adjustments related thereto;\n8. Post individual disbursements to the subsidiary ledger and index cards;\n9. Maintain individual ledgers for officials and employees of the City pertaining to payrolls and deductions;\n10. Record and post in index cards details of purchased furniture, fixtures, and equipment, including disposal thereof, if any;\n11. Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n12. Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n13. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Budget Officer. –"},"text":{"en":"Section 30. The City Budget Officer. –\na. The city budget officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in accounting, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in government budgeting or in any related field for at least five (5) years immediately preceding the date of his appointment.\nb. The city budget officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city budget officer shall take charge of the City Budget Office, and shall:\n1. Prepare forms, orders, and circulars embodying instruction on budgetary and appropriation matters for the signature of the city mayor;\n2. Review and consolidate the budget proposals of different departments and offices of the City;\n3. Assist the city mayor in the preparation of the budget and during budget hearings;\n4. Study and evaluate budgetary implications of proposed legislation and submit comments and recommendations thereon;\n5. Submit periodic budgetary reports to the Department of Budget and Management;\n6. Coordinate with the city treasurer, the city accountant, and the city planning and development coordinator for the purpose of budgeting;\n7. Assist the sangguniang panlungsod in reviewing the approved budgets of component barangays of the City;\n8. Coordinate with the city planning and development coordinator in the formulation of the development plan of the City; and\n9. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Planning and Development Coordinator. –"},"text":{"en":"Section 31. The City Planning and Development Coordinator. –\na. The city planning and development coordinator must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in urban planning, development studies, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in development planning or in any related field for at least five (5) years immediately preceding the date of his appointment.\nb. The city planning and development coordinator shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city planning and development coordinator shall take charge of the City Planning and Development Office, and shall:\n1. Formulate integrated economic, social, physical, and other development plans and policies for consideration of the city development council;\n2. Conduct continuing studies, researches, and training programs necessary to evolve plans and programs for implementation;\n3. Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or agencies;\n4. Monitor and evaluate the implementation of the different development programs, projects, and activities in the City in accordance with the approved development plan;\n5. Prepare comprehensive plans and other development planning documents for the consideration of the city development council;\n6. Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for consideration of the finance committee of the sangguniang panlungsod;\n7. Promote people participation in development planning within the City; and\n8. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Engineer. –"},"text":{"en":"Section 32. The City Engineer. –\na. The city engineer be citizen Philippines, a resident of the city, of good moral character, and a licensed engineer. He must have acquired experience in practice profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city engineer shall take charge of the City Engineering Office, and shall:\n1. Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices of the City in infrastructure development and public works in general;\n2. Advise the city mayor on infrastructure, public works, and other engineering matters;\n3. Administer, coordinate, supervise, and control the construction, maintenance, improvement, and repair of roads, bridges, and other engineering and public works projects of the City;\n4. Provide engineering services to the City, including investigation and survey, engineering designs, feasibility studies, and project management; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Health Officer. –"},"text":{"en":"Section 33. The City Health Officer. –\na. The city health officer must be a citizen of the Philippines, a resident of the City, of good moral character, and a licensed medical practitioner. He must have acquired experience in the practice of his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city health officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city health officer shall take charge of the Office of the City Health Services, and shall:\n1. Supervise the personnel and staff of said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the city mayor, in order to assist him in the efficient, effective and economical implementation of a health services program geared to implementation of health-related projects and activities;\n2. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor, in carrying out activities to ensure the delivery of basic services and provision of adequate facilities relative to health services;\n3. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning health programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n4. Be in the frontline of the delivery of health services, particularly during and in the aftermath of man-made and natural disasters and calamities; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Civil Registrar. –"},"text":{"en":"Section 34. The City Civil Registrar. –\na. The city civil registrar must be a citizen of the Philippines, a resident of the City of Marikina, of good moral character, a holder of a college degree from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in civil registry work for at least five (5) years immediately preceding the date of his appointment.\nb. The city civil registrar shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city civil registrar shall be responsible for the civil registration program of the City, pursuant to the Civil Registry Law, the Civil Code, and other pertinent laws, rules and regulations issued to implement them.\nd. The city civil registrar shall take charge of the Office of the City Civil Registry, and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning civil registry programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide; and\n2. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Administrator. –"},"text":{"en":"Section 35. The City Administrator. –\na. The city administrator must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in public administration, law, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in management and administration work for at least five (5) years immediately preceding the date of his appointment.\nb. The city administrator shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city administrator shall take charge of the Office of the City Administrator, and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the management and administration-related programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n2. Be in the frontline of the delivery of administrative support services, particularly those related to the situations during and in the aftermath of man-made and natural disasters and calamities;\n3. Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to the management and administration of the City; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Legal Officer. –"},"text":{"en":"Section 36. The City Legal Officer. –\na. The city legal officer must be a citizen of the Philippines, a resident of the City, of good moral character, and a member of the Philippine Bar. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city legal officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city legal officer, being the chief legal counsel of the City, shall take charge of the Office for Legal Services, and shall:\nd. Formulate measures for the consideration of the sangguniang panlungsod and provide legal assistance and support to the city mayor in carrying out the delivery of basic services and provision of adequate facilities;\ne. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning programs and projects related to legal services which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\nf. Recommend measures to the sangguniang panlungsod and advise the city mayor on all matters related to upholding the rule of law;\ng. Be in the frontline of protecting human rights and prosecuting any violation thereof, particularly those which occur during and in the aftermath of man-made or natural disasters and calamities; and\nh. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Trade and Industry Officer. –"},"text":{"en":"Section 37. The City Trade and Industry Officer. –\na. The city trade and industry officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in economics or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the work of economics or any related field for at least five (5) years from a reputed private or government institution.\nb. The city trade and industry officer shall receive such compensation, emoluments, and allowances as may be determined by law;\nc. The city trade and industry officer shall take charge of the City Trade and Industry Office, and shall:\n1. Develop a comprehensive system of investor assistance as one way of attracting investments in the City;\n2. Establish a data base of local manpower and other resources needed in trade and industry in the City;\n3. Undertake publicity programs for the locally manufactured products;\n4. Set up and administer a research, training and productivity center for product development and for the acquisition and improvement of technology and skills of local manpower;\n5. Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to the protection of consumers in the City;\n6. Set up and supervise livelihood projects in the City; and\n7. Perform such other duties and functions and exercise such other powers that may be prescribed by law or ordinance."}},{"id":"PH-H6701-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Schools Division Superintendent. – There shall be in the City of Marikina a city schools division superintenden"},"text":{"en":"Section 38. The City Schools Division Superintendent. – There shall be in the City of Marikina a city schools division superintendent. The city schools division superintendent must be a citizen of the Philippines, preferably a resident of the City of Marikina, of good moral character, a holder of a college degree in education or any other related course from a recognized college or university and a first grade civil service eligible or its equivalent. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment. The city schools division superintendent shall receive such compensation, emoluments, and allowances as may be determined by law."}},{"id":"PH-H6701-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"Powers and Functions of the City Schools Division Superintendent. –"},"text":{"en":"Section 39. Powers and Functions of the City Schools Division Superintendent. –\na. The city schools division superintendent shall take charge of all the public schools existing at the time of the approval of this Act and such other public schools that shall be created thereafter and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to education;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with education;\n3. Liaison with teachers and principals assigned in the City as well as sit as vice-chairman of the local school board of the City;\n4. Study, evaluate and recommend the allocation of the Special Education Fund (SEF); and\n5. Perform such other duties and functions and exercise such other powers as may be prescribed by law or ordinance."}},{"id":"PH-H6701-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Social Welfare and Development Officer. –"},"text":{"en":"Section 40. The City Social Welfare and Development Officer. –\na. The city social welfare and development officer must be a citizen of the Philippines, a resident of the City, of good moral character, a duly licensed social worker or a holder of a college degree preferably in sociology or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the practice of social work for at least five (5) years immediately preceding the date of his appointment.\nb. The city social welfare and development officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city social welfare and development officer shall take charge of the Office on Social Welfare and Development, and shall:\n1. Formulate measures for the approval of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of the basic services and provision of adequate facilities relative to social welfare and development services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning social welfare programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Be in the frontline of service delivery, particularly those concerning immediate relief and assistance during and in the aftermath of man-made and natural disasters and natural calamities;\n4. Recommend to the sangguniang panlungsod and advise the city mayor on all other matters related to social welfare and development services which will improve the livelihood and living conditions of the inhabitants; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Environment and Natural Resources Officer. –"},"text":{"en":"Section 41. The City Environment and Natural Resources Officer. –\na. The city environment and natural resources officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in environmental and natural resources management, conservation, and utilization work for at least five (5) years immediately preceding the date of his appointment.\nb. The city environment and natural resources officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city environment and natural resources officer shall take charge of the Office on Environment and Natural Resources, and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to environment and natural resources services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning environment and natural resources programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Be in the frontline of the delivery of services concerning the environment and natural resources, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made and natural disasters and calamities;\n4. Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to the protection, conservation, maximum utilization, application of appropriate technology, and other matters related to the environment and natural resources; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Architect. –"},"text":{"en":"Section 42. The City Architect. –\na. The city architect must be a citizen of the Philippines, a resident of the City, of good moral character, and a duly licensed architect. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city architect shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city architect shall take charge of the Office on Architectural Planning Design, and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to architectural planning and design;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning architectural planning and design of programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Be in the frontline of the delivery of services involving architectural planning and design, particularly those related to the design and redesign of spatial distribution of basic facilities and physical structures during and in the aftermath of manmade and natural disasters and calamities;\n4. Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to this architectural planning and design as it relates to the total geophysical and socioeconomic development of the City; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Information Officer. –"},"text":{"en":"Section 43. The City Information Officer. –\na. The city information officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in journalism, mass communication or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in writing articles and research papers, or in writing for print, television or broadcast media for at least five (5) years immediately preceding the date of his appointment.\nb. The city information officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city information officer shall take charge of the Office on Public Information, and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in providing the information and research data required for the delivery of basic services and provision of adequate facilities so that the public is made aware of said services and may fully avail of the same;\n2. Develop plans and strategies and, upon approval thereof by the city mayor, implement the same particularly those concerning public information and research data to support programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Be in the frontline in providing information during and in the aftermath of man-made and natural disasters and calamities, with special attention to the victims thereof to help minimize injuries and casualties during and after the emergency, and to accelerate relief and rehabilitation;\n4. Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to public information and research data as it relates to the total socioeconomic development of the City; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Cooperatives Officer. –"},"text":{"en":"Section 44. The City Cooperatives Officer. –\na. The city cooperatives officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree preferably in business administration with special training in cooperatives or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in cooperatives organization and management for at least five (5) years immediately preceding the date of his appointment.\nb. The city cooperatives officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city cooperatives officer shall take charge of the Office for the Development of Cooperatives, and shall:\nd. Formulate measures for the consideration of the sangguniang panlungsod and to provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of facilities through the development of cooperatives, and in providing access to such services and facilities;\ne. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning the integration of cooperative principles and methods in programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\nf. Be in the frontline of cooperatives organization, rehabilitation or variability-enhancement, particularly during and in the aftermath of man-made and natural calamities and disasters, to aid in their survival and subsequent rehabilitation;\ng. Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to cooperatives development and variability-enhancement which will improve the livelihood and quality of life of the inhabitants; and\nh. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Population Officer. –"},"text":{"en":"Section 45. The City Population Officer. –\na. The city population officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree with specialized training in population development from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in the implementation of programs on population development and responsible parenthood for at least three (3) years immediately preceding the date of his appointment.\nb. The city population officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city population officer shall take charge of the Office on Population Development, and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to the integration of population development principles and in providing access to said services and facilities;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning the integration of population development principles and methods in programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Veterinarian. –"},"text":{"en":"Section 46. The City Veterinarian. –\na. The city veterinarian must be a citizen of the Philippines, a resident of the City, of good moral character, and a licensed doctor of veterinary medicine. He must have practiced his profession for at least three (3) years immediately preceding the date of his appointment.\nb. The city veterinarian shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city veterinarian shall take charge of the Office of Veterinary Services, and shall:\n1. Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same particularly those concerning veterinary-related activities which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Be in the frontline of veterinary-related activities, such as the outbreak of highly-contagious and deadly diseases and in situations resulting in the depletion of animals for work and human consumption, particularly those arising from and in the aftermath of man-made and natural disasters and calamities;\n4. Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to veterinary services which will increase the number and improve the quality of livestock, poultry, and other domestic animals used for work or human consumption; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance.1aшphi1"}},{"id":"PH-H6701-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY; THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City General Services Officer. –"},"text":{"en":"Section 47. The City General Services Officer. –\na. The city general services officer must be a citizen of the Philippines, a resident of the City, of good moral character, a holder of a college degree in public administration, business administration or management from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in general services, including management of supply, property, solid waste disposal, and general sanitation for at least five (5) years immediately preceding the date of his appointment.\nb. The city general services officer shall receive such compensation, emoluments, and allowances as may be determined by law.\nc. The city general services officer shall take charge of the Office on General Services, and shall:\n1. Formulate measures for the considerations of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services expertise and technical support services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning general services supportive of the welfare of the inhabitants of the City which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n3. Take custody of and be accountable for all properties, real or personal, owned by the City, and those granted to it in the form of donation, reparation, assistance, and counterpart of joint projects;\n4. Be in the frontline of general services-related activities, such as the possible or imminent destruction or damage to records, supplies, properties, and structure materials or debris, particularly during and in the aftermath of man-made and natural disasters and calamities;\n5. Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to general services; and\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6701-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Municipal Ordinances Existing at the Time of the Approval of this Act. – All municipal ordinances of the Municipality of"},"text":{"en":"Section 48. Municipal Ordinances Existing at the Time of the Approval of this Act. – All municipal ordinances of the Municipality of Marikina existing at the time of the approval of this Act shall continue to be in force within the City of Marikina until the sangguniang panlungsod shall, by ordinance, provide otherwise."}},{"id":"PH-H6701-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Suspension of Increase in Rates of Local Taxes. – No increase in the rates of local taxes shall be imposed by the City w"},"text":{"en":"Section 49. Suspension of Increase in Rates of Local Taxes. – No increase in the rates of local taxes shall be imposed by the City within a period of five (5) years from its acquisition of corporate existence."}},{"id":"PH-H6701-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Plebiscite. – The City of Marikina shall acquire corporate existence upon the ratification of its creation by a majority"},"text":{"en":"Section 50. Plebiscite. – The City of Marikina shall acquire corporate existence upon the ratification of its creation by a majority of the votes cast by the qualified voters in a plebiscite to be conducted in the present Municipality of Marikina within sixty (60) days from the approval of this Act. The expenses for such plebiscite shall be borne by the Municipality of Marikina. The Commission on Elections shall conduct and supervise such plebiscite."}},{"id":"PH-H6701-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Officials of the City of Marikina. – The present elective officials of the municipality shall continue to exercise their"},"text":{"en":"Section 51. Officials of the City of Marikina. – The present elective officials of the municipality shall continue to exercise their powers and functions until such time that a new election is held and the duly-elected city officials shall have qualified and assumed their offices. The appointive officials and employees of the municipality shall likewise continue to exercise their functions and duties and they shall be automatically absorbed by the government of the City of Marikina."}},{"id":"PH-H6701-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Jurisdiction of Metropolitan Manila. – The City of Marikina shall, unless otherwise provided by law, continue to be unde"},"text":{"en":"Section 52. Jurisdiction of Metropolitan Manila. – The City of Marikina shall, unless otherwise provided by law, continue to be under the jurisdiction of Metropolitan Manila."}},{"id":"PH-H6701-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Legislative District. – Being highly-urbanized, the City of Marikina shall have its own legislative district with the fi"},"text":{"en":"Section 53. Legislative District. – Being highly-urbanized, the City of Marikina shall have its own legislative district with the first representative to be elected in the next national elections after the passage of this Act. Until such time, the City of Marikina shall continue to be represented by the incumbent representative in the House of Representatives of the Congress of the Philippines."}},{"id":"PH-H6701-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Applicability of Laws. – The provisions of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1"},"text":{"en":"Section 54. Applicability of Laws. – The provisions of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1991, Presidential Decree Numbered Eight hundred and twenty-four, and other laws pertaining to Metropolitan Manila and such laws as are applicable to highly-urbanized cities shall govern the City of Marikina insofar as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H6701-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Effectivity Clause. – This Act shall take effect upon its approval."},"text":{"en":"Section 55. Effectivity Clause. – This Act shall take effect upon its approval.\nApproved, November 6, 1996."}}],"pack":"ph-p95","recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra1996/ra_8223_1996.html 重抓，55 → 55 条"};
  FT["PH-H6702"] = {"id":"PH-H6702","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8224_1996.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将马尼拉大都会第5号环状道路（C-5）更名为Garcia总统大道并为其他目的法案","en":"An Act Renaming the Circumferential Route No. 5 or C-5 in Metro Manila, as the President Garcia Avenue, and for Other Purposes","orig":"An Act Renaming the Circumferential Route No. 5 or C-5 in Metro Manila, as the President Garcia Avenue, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8224","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-06","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8224_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6702-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"President Carlos P. Garcia served with distinction as congressman, senator, vice–president, and president of the Republic of the Philippines. He was also the first president of the 1971 Constitutional Convention."}},{"id":"PH-H6702-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To perpetuate his memory, the Circumferential Route No. 5 or C-5 in Metro Manila, is hereby renamed as the President Garcia Avenue."}},{"id":"PH-H6702-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, November 6, 1996."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renaming the Circumferential Route No. 5 or C-5 in Metro Manila, as the President Garcia Avenue, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6703"] = {"id":"PH-H6703","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8225_1996.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将南达沃省何塞阿巴德桑托斯市镇布图兰中学的名称变更为Edna Guillermo纪念中学的法案","en":"An Act Changing the Name of Butulan High School to Edna Guillermo Memorial High School in the Municipality of Jose Abad Santos, Province of Davao Del Sur","orig":"An Act Changing the Name of Butulan High School to Edna Guillermo Memorial High School in the Municipality of Jose Abad Santos, Province of Davao Del Sur"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8225","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8225_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6703-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Butulan High School in the Municipality of Jose Abad Santos, Province of Davao del Su, is hereby changed to Edna Guillermo Memorial high school."}},{"id":"PH-H6703-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Butulan High School to Edna Guillermo Memorial High School in the Municipality of Jose Abad Santos, Province of Davao Del Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6704"] = {"id":"PH-H6704","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8226_1996.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Tagum市","en":"An Act Establishing a National High School in Barangay La Filipina, Municipality of Tagum, Province of Davao, to Be Known as the Barangay La Filipina National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay La Filipina, Municipality of Tagum, Province of Davao, to Be Known as the Barangay La Filipina National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8226","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8226_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6704-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay La Filipina, Municipality of Tagum, Province of Davao, to be known as the Barangay La Filipina National High School,"}},{"id":"PH-H6704-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be in­cluded in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6704-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
