  FT["PH-H6712"] = {"id":"PH-H6712","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8234_1996.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Romblon市","en":"An Act Converting the Macario Molina Memorial High School At Barangay Tambac, Municipality of Romblon, Province of Romblon, Into a National Government-funded Secondary School, to Be Known as the Macario Molina National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Macario Molina Memorial High School At Barangay Tambac, Municipality of Romblon, Province of Romblon, Into a National Government-funded Secondary School, to Be Known as the Macario Molina National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8234","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8234_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6712-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Macario Molina Memorial High School at Barangay Tambac, Municipality of Romblon, Province of Romblon, is hereby converted into a regular secondary school under the control and supervision of the national government through the Department of Education, Culture and Sports, to be known as the Macario Molina National High School."}},{"id":"PH-H6712-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6712-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6712-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6713"] = {"id":"PH-H6713","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8235_1996.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Bongabon市","en":"An Act Establishing a High School in Barangay Macabaclay, Municipality of Bongabon, Province of Nueva Ecija, to Be Known as the Macabaclay High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in Barangay Macabaclay, Municipality of Bongabon, Province of Nueva Ecija, to Be Known as the Macabaclay High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8235","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8235_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6713-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay Macabaclay, Municipality of Bongabon, Province of Nueva Ecija, to be known as the Macabaclay High School."}},{"id":"PH-H6713-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6713-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6713-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6714"] = {"id":"PH-H6714","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8236_1996.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Narra市","en":"An Act Converting the Palawan National Schoolnarra Branch-sandoval Annex in Barangay Sandoval, Municipality of Narra, Province of Palawan, Into a National High School to Be Known as the Sandoval National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Palawan National Schoolnarra Branch-sandoval Annex in Barangay Sandoval, Municipality of Narra, Province of Palawan, Into a National High School to Be Known as the Sandoval National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8236","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8236_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6714-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Palawan National School-Narra Branch-Sandoval Annex in Barangay Sandoval, Municipality of Narra, Province of Palawan, is hereby converted into a national high school to be known as the Sandoval National High School."}},{"id":"PH-H6714-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the necessary rules, orders and circulars to implement the provisions of this Act."}},{"id":"PH-H6714-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and properties, including buildings, sites, and the improvements thereof, obligations, funds and appropriations of the Palawan National School-Narra Branch-Sandoval Annex are hereby transferred to the Sandoval National High School."}},{"id":"PH-H6714-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6714-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6715"] = {"id":"PH-H6715","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8237_1996.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Murcia市","en":"An Act Creating a Barangay National High School in Barangay Alegria, Municipality of Murcia, Province of Negros Occidental, to Be Known as the Barangay Alegria National High School, and Appropriating Funds Therefor","orig":"An Act Creating a Barangay National High School in Barangay Alegria, Municipality of Murcia, Province of Negros Occidental, to Be Known as the Barangay Alegria National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8237","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8237_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6715-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a barangay national high school in Barangay Alegria, Municipality of Murcia, Province of Negros Occidental, to be known as the Barangay Alegria National High School."}},{"id":"PH-H6715-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6715-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6715-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6716"] = {"id":"PH-H6716","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8238_1996.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Maragusan市","en":"An Act Converting the Mapawa Barangay High School in Barangay Mapawa, Municipality of Maragusan, Province of Davao, Into the Mapawa National High School, Providing Funds Therefor, and for Other Purposes","orig":"An Act Converting the Mapawa Barangay High School in Barangay Mapawa, Municipality of Maragusan, Province of Davao, Into the Mapawa National High School, Providing Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8238","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8238_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6716-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mapawa Barangay High School in Barangay Mapawa, Municipality of Maragusan, Province of Davao, is hereby nationalized, to be known as the Mapawa National High School."}},{"id":"PH-H6716-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6716-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, equipment, buildings, facilities, and other properties of the Mapawa Barangay High School are hereby transferred to the Mapawa National High School."}},{"id":"PH-H6716-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6716-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6717"] = {"id":"PH-H6717","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8239_1996.html","fetchedAt":"2026-10-06","articleCount":24,"structureMode":"ARTICLE","title":{"zh":"1996 年菲律宾护照法","en":"Philippine Passport Act of 1996","orig":"Philippine Passport Act of 1996"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8239","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-12","completenessNote":"全文，共 24 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8239_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6717-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act will be called as the \"Philippine Passport Act of 1996.\""}},{"id":"PH-H6717-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy. – The people's constitutional right to travel is inviolable. Accordingly, the government has the duty to issue passport or any travel document to any citizen of the Philippines or individual who complies with the requirement of this Act. The right to travel may be impaired only when national security, public safety, or public health requires. To enhance and protect the unimpaired exercise of this right, only minimum requirements for the application and issuance of passports and other travel documents shall be prescribed. Action on such application and the issuance shall be expedited."}},{"id":"PH-H6717-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. – As used in this Act:\na. Department means the Department of Foreign Affairs;\nb. Secretary means the Secretary of Foreign Affairs;\nc. Post means a Philippine diplomatic and consular post such as an Embassy or Consulate;\nd. Passport means a document issued by the Philippine government to its citizens and requesting other governments to allow its citizens to pass safely and freely, and in case of need to give him/her all lawful aid and protection;\ne. Travel Document means a certification or identifying document containing the description and other personal circumstances of its bearer, issued for direct travel to and from the Philippines valid for short periods or a particular trip. It is issued only to persons whose claim to Philippine citizenship is doubtful or who fall under the category enumerated in Section 13 of this Act;\nf. Supporting Documents mean any paper or document which is required to be submitted with the passport application supporting claims to Filipino citizenship to complete the application for a passport without which such application would be deemed incomplete or otherwise become subject to denial by the issuing authority;\ng. Ambassadors mean those who have been appointed as chiefs of mission and have served as Ambassador Extraordinary and Plenipotentiary."}},{"id":"PH-H6717-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Authority to Issue, Deny, Restrict or Cancel. – Upon the application of any qualified Filipino citizen, the Secretary of Foreign Affairs or any of his authorized consular officer may issue passports in accordance with this Act.\nPhilippine consular officers in a foreign country shall be authorized by the Secretary to issue, verify, restrict, cancel or refuse a passport in the area of jurisdiction of the Post in accordance with the provisions of this Act.\nIn the interest of national security, public safety and public health, the Secretary or any of the authorized consular officers may, after due hearing and in their proper discretion, refuse to issue a passport, or restrict its use or withdraw or cancel a passport: Provided, however, That such act shall not mean a loss or doubt on the person's citizenship: Provided, further, That the issuance of a passport may not be denied if the safety and interest of the Filipino citizen is at stake: Provided, finally, That refusal or cancellation of a passport would not prevent the issuance of a Travel Document to allow for a safe return journey by a Filipino to the Philippines."}},{"id":"PH-H6717-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Requirements for the Issuance of Passport. – No passport shall be issued to an applicant unless the Secretary or his duly authorized representative is satisfied that the applicant is a Filipino citizen who has complied with the following requirements:\na. A duly accomplished application form and photographs of such number, size and style as may be prescribed by the Department;\nb. The birth certificate duly issued or authenticated by the Office of the Civil Registrar General: Provided, however, That if the birth of the applicant has not been registered yet, or if his birth certificate is destroyed, damaged, or not available due to other causes, he shall apply for delayed registration of his birth with the Office of the Civil Registrar General which shall issue to said applicant a certification of pending application for delayed registration of birth attaching thereto a copy of an accomplished certificate of live birth. Such certification and the accomplished certificate of live birth shall be sufficient to support an application for passport in addition to other papers which the Department may require from the applicant;\nc. In the absence of a birth certificate, a baptismal certificate for those who are members of a Christian religious organization, or similar or equivalent certificate issued by a non-Christian religious group, attesting to the applicant's having been admitted to such religious group or sect at an early age and where it is indicated that the applicant is a Filipino citizen, which should be accompanied by a joint affidavit by two (2) persons who have personal knowledge of the applicant and of such age as to credibly state the applicant's date and place of birth, citizenship, and names of parents: Provided, That Filipinos who do not believe in any religion and whose parents for any reason failed to have the said applicant baptized shall be exempted from the baptismal certificate requirement: Provided, further, That in lieu thereof, the applicant shall execute an affidavit to that effect duly corroborated by affidavit of at least two (2) persons of good reputation who personally know such fact;\nd. In case of a woman who is married, separated, divorced or widowed or whose marriage has been annulled or declared by court as void, a copy of the certificate of marriage, court decree of separation, divorce or annulment or certificate of death of the deceased spouse duly issued and authenticated by the Office of the Civil Registrar General: Provided, That in case of a divorce decree, annulment or declaration of marriage as void, the woman applicant may revert to the use of her maiden name: Provided, further, That such divorce is recognized under existing laws of the Philippines;\ne. In the case of naturalized citizens, a certified copy of the naturalization certificate; or a certified naturalization certificate of husband or parent duly issued and authenticated by the Office of the Civil Registrar General if citizenship is claimed through naturalization of spouse or parent;\nf. For an applicant who has not reached the age of majority, an affidavit of consent from a parent as indicated in the passport application if the minor is traveling with either parent, and a clearance from the Department of Social Welfare and Development, if the minor is traveling with a legal guardian or a person other than a parent;\ng. If the applicant is an adopted person, the duly certified copy of court order of adoption, together with the original and amended birth certificates duly issued and authenticated by the Office of the Civil Registrar General shall be presented: Provided, That in case the adopted person is an infant or a minor or the applicant is for adoption by foreign parents, an authority from the Department of Social Welfare and Development shall be required: Provided, further, That the adopting foreign parents shall also submit a certificate from their embassy or consulate that they are qualified to adopt such infant or minor child;\nh. In case of discrepancy between the applicant's name in the birth certificate and in any other private documents, the former shall prevail over the latter unless by operation of law or through court order, the applicant is permitted to use a name other than what is officially recorded in the Civil Register; and\ni. If the applicant is a government employee, the travel authority issued by the head of department, agency or office may be required only if said applicant is applying for an official passport."}},{"id":"PH-H6717-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Application. – The application may be filed by:\na. The applicant himself or herself; or\nb. The parent or legal guardian on behalf of an applicant who is below the age of majority.\nIn case of first time applicants, the applicant must present himself/herself in person to prove that he or she is the same person and of the age claimed in the application form. In case of renewal the application may be filed by any licensed travel agency duly accredited by the Department of Foreign Affairs: Provided, That the agent shall be responsible for the authenticity or bona fide of the supporting documents being presented to meet the requirements for the application of passports."}},{"id":"PH-H6717-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Types of Passports. – The Secretary or the authorized representative or consular officer may issue the following types of passports:\na. Diplomatic passport for persons imbued with diplomatic status or are on diplomatic mission such as:\n1. The President and former Presidents of the Republic of the Philippines;\n2. The Vice-President and former Vice-Presidents of the Republic of the Philippines;\n3. The Senate President and the Speaker of the House of Representatives;\n4. The Chief Justice of the Supreme Court;\n5. The Cabinet Secretaries, and the Undersecretaries and Assistant Secretaries of the Department of Foreign Affairs;\n6. Ambassadors, Foreign Service Officers of all ranks in the career diplomatic service; Attaches, and members of their families;\n7. Members of the Congress when on official mission abroad or as delegates to international conferences;\n8. The Governor of the Bangko Sentral ng Pilipinas and delegates to international or regional conferences when on official mission or accorded full powers by the President; and\n9. Spouses and unmarried minor children of the abovementioned officials when accompanying or following to join them in an official mission abroad.\nThe President of the Philippines and the Secretary of the Department of Foreign Affairs may grant diplomatic passports to officials and persons other than those enumerated herein who are on official mission abroad.\nb. Official Passport to be issued to all government officials and employees on official trip abroad but who are not on a diplomatic mission or delegates to international or regional conferences or have not been accorded diplomatic status such as:\n1. Undersecretaries and Assistant Secretaries of the Cabinet other than the Department of Foreign Affairs, the Associate Justices and other members of the Judiciary, members of the Congress and all other government officials and employees traveling on official business and official time;\n2. Staff officers and employees of the Department of Foreign Affairs assigned to diplomatic and consular posts and officers and representatives of other government departments and agencies assigned abroad;\n3. Persons in the domestic service and household members of officials assigned to diplomatic or consular posts;\n4. Spouses and unmarried minor children of the officials mentioned above when accompanying or following to join them.\nc. Regular Passport issued to Filipino citizens who are not eligible or entitled to diplomatic or official passports, including government officials or employees going abroad for pleasure or other personal reasons. Government officials and employees and members of their families may, during their incumbency in office, hold two passports simultaneously: (1) a regular passport for private travel; (2) a diplomatic or official passport when traveling abroad on diplomatic or official business. The wife and minor children of persons entitled to a diplomatic or official passport shall be issued regular passports, if they are not accompanying or following to join them."}},{"id":"PH-H6717-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Grounds for Denial, Cancellation or Restrictions. – The application for passport may be denied, cancelled or restricted only on the following grounds:\na. Denial of Passport\n1. On orders of the court, after due notice and hearing, to hold the departure of an applicant because of a pending criminal case;\n2. When so requested by the natural or legal guardian, if the applicant is a minor;\n3. When the applicant has been found to have violated any of the provisions of this Act;\n4. Such other disqualification under existing laws.\nb. Cancellation\n1. When the holder is a fugitive from justice;\n2. When the holder has been convicted of a criminal offense: Provided, That the passport may be restored after service of sentence; or\n3. When a passport was acquired fraudulently or tampered with.\nc. Restricted\n1. When the country of destination is in a state of political instability which could pose a danger to the Filipino traveler;\n2. When diplomatic ties have been fractured or severed with the Philippines;\n3. When the country of destination is subject to travel restriction by government policy, enforcement of action by the United Nations or in a state of war."}},{"id":"PH-H6717-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Appeal. – Any person who feels aggrieved as a result of the application of this Act or of the implementing rules and regulations issued by the Secretary shall have the right to appeal to the Secretary of Foreign Affairs from whose decision judicial review may be had to the Courts in due course."}},{"id":"PH-H6717-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Validity. – Regular passports issued under this Act shall be valid for a period of five (5) years: Provided, however, That the issuing authority may limit the period of validity to less than five (5) years; whenever in the national economic interest or political stability of the country such restriction is necessary: Provided, finally, That a new passport may be issued to replace one which validity has expired, the old passport being returned to the holder after cancellation."}},{"id":"PH-H6717-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Ownership of Passports. – A Philippine passport remains at all times the property of the Government, the holder being a mere possessor thereof as long as it is valid and the same may not be surrendered to any person or entity other than the government or its representative: Provided, That a Filipino citizen may voluntarily surrender his/her passport to a Philippine Service Post for storage and safekeeping for which a proper receipt shall be issued for use when reclaiming the passport at a later date."}},{"id":"PH-H6717-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Names and Titles. – The passport shall contain the full name of the applicant, but shall not include his title or titles or profession or job description. If an applicant's name is changed by order of the court, a certified copy of the court order or decree shall be submitted together with the birth certificate or old passport on application."}},{"id":"PH-H6717-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Travel Documents. – A travel document, in lieu of a passport, may be issued to:\na. A Filipino citizen returning to the Philippines who for one reason or another has lost his/her passport or cannot be issued a regular passport;\nb. A Filipino citizen being sent back to the Philippines;\nc. An alien spouse of a Filipino and their dependents who have not yet been naturalized as a Filipino and who are traveling to the Philippines or is a permanent resident of the Philippines;\nd. Aliens permanently residing in the Philippines who are not able to obtain foreign passport and other travel documents;\ne. A stateless person who is likewise a permanent resident, or a refugee granted such status or asylum in the Philippines."}},{"id":"PH-H6717-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Amendments. – A passport may be amended at the request of the holder for any lawful purpose, but such amendment should be approved by the Secretary or his duly authorized diplomatic or consular officers.\nDiplomatic and official passports shall be submitted for revalidation before each departure of the holder."}},{"id":"PH-H6717-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Loss or Destruction. – The loss or destruction of a passport should be immediately reported to the Department or the Post. The holder of such passport shall submit to the Department or Post an affidavit stating in detail the circumstances of such loss or destruction. The holder of such a passport who is in the Philippines, should also furnish the National Bureau of Investigation and the Bureau of Immigration copies of the affidavit. For those who are abroad, copies of the affidavit will be forwarded by the Post to the Department's Office of Consular Services, and in coordination with the Office of Legal and Intelligence Services, shall transmit a copy of the affidavit to the National Bureau of Investigation and Bureau of Immigration. The transmittal of the affidavit shall be accompanied by a request for the confiscation of the said passport if found, and to investigate or detain if necessary, the person attempting to use or has used the passport. All Posts will be informed of the lost passport, including pertinent information on the passport and the circumstances of loss.\nNo new passport shall be issued until satisfactory proof is shown that the passport was actually lost and after the lapse of fifteen (15) days following the date of submission of the affidavit of loss as herein required: Provided, however, That in the case of a passport reported lost by a Filipino traveling abroad, the Consulate may waive the fifteen (15) days requirement if the loss has been proven to the Consular Official's satisfaction: Provided, further, That in case the Filipino who reported a loss of passport is returning to the Philippines, the holder may be issued a Travel Document: Provided, finally, That in the event the lost passport is found, it should be destroyed if a replacement has been issued, or mailed to the holder who was issued a Travel Document.\nIn all cases, the head of Office of Consular Services or the head of the Consular Section of an Embassy or the Consul General of a consulate may, upon his discretion, waive the fifteen (15)-day waiting period."}},{"id":"PH-H6717-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Fees. – Reasonable fees shall be collected for the processing, issuance, extension, amendment or replacement of a lost passport and the issuance of a Travel Document as may be determined by the Department: Provided, however, That any fee shall not be increased more than once every three (3) years."}},{"id":"PH-H6717-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Passport Revolving Fund. – The Department may charge a service fee of not more than Two hundred fifty pesos (P250) for such service rendered to applicants relating to the processing and issuance of passports requiring special consideration, waiver or issuance beyond regular office hours. The service fees received by the Department under this section shall constitute a revolving fund to be called the \"Passport Revolving Fund\" which may be utilized by the Department for the improvement of its passporting and consular services and other Department services except travel and transportation allowances and expenses.\nThe setting up, use and disbursement of funds shall be subject to review, accounting and auditing rules and regulations of the Commission on Audit and will be subject to an annual review by Congress, but the Secretary will submit a report on the disbursement of the fund every six (6) months to both the Senate and the House Committees on Foreign Relations."}},{"id":"PH-H6717-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Waiver. – The Secretary of Foreign Affairs is solely authorized to waive any requirements set forth in Section 5 of this Act."}},{"id":"PH-H6717-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Offenses and Penalties. – A passport being a proclamation of the citizenship of a Filipino, is a document that is superior to all other official documents. As such, it should be accorded the highest respect by its holder that to do damage to its integrity and validity is a serious crime that should be penalized accordingly:\na. Offenses Relating to Issuances : Penalties – Any person who:\n1. Acting or claiming to act in any capacity or office under the Republic of the Philippines, without lawful authority, grants, issues or verifies any passport or travel document to any or for any person whomsoever shall be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than eighteen (18) months nor more than six (6) years; or\n2. Being a diplomatic or consular official authorized to grant, issue, amend or verify passports, knowingly and willfully grants, issues, amends or verifies any such passport to any or for any person not owing allegiance to the Republic of the Philippines, whether citizen or not, shall be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than eighteen (18) months but not more than six (6) years, and upon conviction, be disqualified from holding appointive public office;\n3. Being a diplomatic or consular officer knowingly and willfully grants and issues to, amends or certifies to the authenticity of any passport or travel document for any person not entitled thereto, or knowingly and willfully issues more than one passport to any person except as provided for in this Act, shall be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than eighteen (18) months nor more than six (6) years and upon conviction, be disqualified from holding appointive public office.\nb. Offenses Relating to False Statements : Penalties – Any person who willfully and knowingly:\n1. Makes any false statement in any application for passport with the intent to induce or secure the issuance of a passport under the authority of the Philippine Government, either for his own use or the use of another, contrary to this Act or rules and regulations prescribed pursuant hereto shall be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than three (3) years nor more than ten (10) years; or\n2. Uses or attempts to use any passport which was secured in any way by reason of any false statements, shall be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than three (3) years, but not more than ten (10) years; or\n3. Travel and recruitment agencies whose agents, liaison officers or representatives are convicted of offenses relating to false statements shall in addition to the fines and penalties abovementioned have their license revoked with all deposits, escrow accounts or guarantee funds deposited or made as a requirement of their business forfeited in favor of the government without prejudice to the officials of the branch office or of the agency being charged as accessories to the offense and upon conviction barred from engaging in the travel or recruitment agency business.\nc. Offenses Relating to Forgery : Penalties – Any person who:\n1. Falsely makes, forges, counterfeits, mutilates or alters any passport or travel document or any supporting document for a passport application, with the intent of using the same shall be punished by a fine of not less than Sixty thousand pesos (P60,000) nor more than One hundred fifty thousand pesos (P150,000) and imprisonment of not less than six (6) years nor more than fifteen 15) years; or\n2. Willfully or knowingly uses or attempts to use, or furnishes to another for use of any such false, forged, counterfeited, mutilated or altered passport or travel document or any passport validly issued which has become void by the occurrence of any condition therein prescribed shall be punished by a fine of not less than Sixty thousand pesos (P60,000) nor more than One hundred fifty thousand pesos (P150,000) and imprisonment of not less than six (6) years nor more than fifteen (15) years: Provided, however, That officers of corporations, agencies or entities licensed in the travel and recruitment industry would be held similarly liable as their agents, liaison officers or representatives: Provided, finally, That forgeries of five or more passports or travel documents, would be considered as massive forgery tantamount to national sabotage and shall be punished by a fine of not less than Two hundred fifty thousand pesos (P250,000) nor more than One million pesos (P1,000,000) and imprisonment of not less than seven (7) years nor more than seventeen (17) years.\nd. Offenses Relating to Improper Use : Penalties – Any person who willfully and knowingly:\n1. Uses or attempts to use, any passport issued or designed for the use of another or any supporting documents for a passport application which belongs to another; or\n2. Uses or attempts to use any passport or supporting document in violation of the conditions or restrictions therein contained, or of the rules prescribed pursuant thereto; or\n3. Furnishes, disposes or delivers a passport to any person, for use by another or other than the person for whose use it was originally issued or designed; or\n4. Defaces or destroys a Philippine passport, shall be punished by a fine of not less than Sixty thousand pesos (P60,000) nor more than One hundred fifty thousand pesos (P150,000) and imprisonment of not less than six (6) years nor more than fifteen (15) years.\ne. Offenses Relating to Multiple Possession : Penalties – No person or individual may hold more than one valid passport, except as provided for in Section 7 hereof, and any individual who possesses more than one unexpired passport shall, for every unexpired passport found in his possession, be punished by a fine of not less than Fifteen thousand pesos (P15,000) nor more than Sixty thousand pesos (P60,000) and imprisonment of not less than eighteen (18) months but not more than six (6) years: Provided, That the maximum fine and imprisonment shall be imposed by the court if he attempts to use or actually uses an unexpired passport which is not in his name.\nIn case any of the offenses prohibited in this Act constitutes a violation of the Revised Penal Code and the penalty imposed in said Code is heavier than that provided in this Act, the latter penalty shall be imposed."}},{"id":"PH-H6717-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Suspension of Accreditation. – Any duly accredited travel or recruitment agent or agency which violates the prescription on application for passport under Section 6 hereof shall have such accreditation suspended without prejudice to civil, criminal or administrative sanctions including revocation of its license to operate.\nThe mere submission of spurious, forged or falsified documents supporting a passport application by any duly accredited travel or recruitment agent or agency shall be prima facie evidence that the said travel or recruitment agent or agency is the author of such forgery or falsification."}},{"id":"PH-H6717-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Rules and Regulations. – The Secretary shall issue such rules and regulations as may be necessary to implement the provisions herein within sixty (60) days from date of effectivity of this Act without extension or delays."}},{"id":"PH-H6717-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Separability Clause. – Should any provision of this Act or the applicability thereof to any person or circumstance is held invalid, the remainder thereof shall not be affected thereby."}},{"id":"PH-H6717-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Repealing Clause. – All laws, decrees, orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6717-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least five (5) newspapers of general circulation or in the Official Gazette.\nApproved, November 22, 1996."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Philippine Passport Act of 1996","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6718"] = {"id":"PH-H6718","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8240_1996.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"对第 138、139、140、142 条的修改","en":"An Act Amending Sections 138, 139, 140 and 142 of the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act Amending Sections 138, 139, 140 and 142 of the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 8240","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-11-22","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8240_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6718-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 138 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 138. Distilled Spirits. – On distilled spirits, there shall be collected, subject to the provisions of Section 130 of this Code, specific taxes as follows:\n\"(a) If produced from the sap of nipa, coconut, cassava, camote, or buri palm or from the juice, syrup, or sugar of the cane, provided such materials are produced commercially in the country where they are processed into distilled spirits, per proof liter, Eight pesos (P8): Provided, That if produced in a pot still or other similar primary distilling apparatus by a distiller producing not more than 100 liters a day, containing not more than fifty percent (50%) of alcohol by volume, per proof liter, Four pesos (P4);\n\"(b) If produced from raw materials other than those enumerated in the preceding paragraph, the tax shall be in accordance with the net retail price per bottle of seven hundred fifty milliliter (750 ml.) volume capacity (excluding the excise tax and the value-added tax) as follows:\n\"(1) Less than Two hundred and fifty pesos (P250) – Seventy-five pesos (P75), per proof liter;\n\"(2) Two hundred and fifty pesos (P250) up to Six hundred and seventy-five pesos (P675) – One hundred and fifty pesos (P150), per proof liter; and \"(3) More than Six hundred and seventy-five pesos (P675) – Three hundred pesos (P300), per proof liter.\n\"(c) Medicinal preparations, flavoring extracts, and all other preparations, except toilet preparations, of which, excluding water, distilled spirits form the chief ingredient, shall be subject to the same tax as such chief ingredient.\n\"This tax shall be proportionally increased for any strength of the spirits taxed over proof spirits, and the tax shall attach to this substance as soon as it is in existence as such, whether it be subsequently separated as pure or impure spirits, or transformed into any other substance either in the process of original production or by any subsequent process.\n\"'Spirits or distilled spirits,' is the substance known as ethyl alcohol, ethanol or spirits of wine, including all dilutions, purifications and mixtures thereof, from whatever source by whatever process produced and shall include whisky, brandy, rum, gin and vodka, and other similar products or mixtures.\n\"'Proof spirits' is liquor containing 1/2 of its volume of alcohol of a specific gravity of seven thousand nine hundred and thirtynine ten thousandths (0.7939) at fifteen degrees centigrade. A proof liter means a liter of proof spirits.\n\"The rates of tax imposed under this section shall be increased by twelve percent (12%) on January 1, 2000.\n\"New brands shall be classified according to their current net retail price.\n\"For the above purpose, net retail price shall mean the price at which the distilled spirit is sold on retail in 10 major supermarkets in Metro Manila, excluding the amount intended to cover the applicable excise tax and the value-added tax as of October 1, 1996.\n\"The classification of each brand of distilled spirits based on the average net retail price as of October 1, 1996, as set forth in Annex 'A', shall remain in force until revised by Congress.\""}},{"id":"PH-H6718-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 139 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 139. Wines. – On wines, there shall be collected per liter of volume capacity, the following taxes:\n\"(a) Sparkling wines/champagnes regardless of proof, if the net retail price per bottle (excluding the excise tax and the value-added tax) is:\n\"(1) Five hundred pesos (P500) or less – One hundred pesos (P100); and \"(2) More than Five hundred pesos (P500) – Three hundred pesos (P300);\n\"(b) Still wines containing fourteen percent (14%) of alcohol by volume or less, Twelve pesos (P12); and \"(c) Still wines containing more than fourteen percent (14%) but not more than twenty-five percent (25%) of alcohol by volume, Twenty-four pesos (P24).\n\"Fortified wines containing more than twenty-five percent (25%) of alcohol by volume shall be taxed as distilled spirits. Fortified wines shall mean natural wines to which distilled spirits are added to increase their alcoholic strength.\n\"The rates of tax imposed under this section shall be increased by twelve percent (12%) on January 1, 2000.\n\"New brands shall be classified according to their current net retail price.\n\"For the above purpose, net retail price shall mean the price at which wine is sold on retail in 10 major supermarkets in Metro Manila, excluding the amount intended to cover the applicable excise tax and the value-added tax as of October 1, 1996.\n\"The classification of each brand of wines based on its average net retail price as of October 1, 1996, as set forth in Annex 'B', shall remain in force until revised by Congress.\""}},{"id":"PH-H6718-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 140 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 140. Fermented Liquor. – There shall be levied, assessed and collected a specific tax on beer, lager beer, ale, porter, and other fermented liquors except tuba, basi, tapuy and similar domestic fermented liquors in accordance with the following schedule:\n\"(a) If the net retail price (excluding the specific tax and value-added tax) per liter of volume capacity is less than Fourteen pesos and fifty centavos (P14.50), the tax shall be Six pesos and fifteen centavos (P6.15) per liter;\n\"(b) If the net retail price (excluding the specific tax and the value-added tax) per liter of volume capacity is Fourteen pesos and fifty centavos (P14.50) up to Twenty-two pesos (P22), the tax shall be Nine pesos and fifteen centavos (P9.15) per liter;\n\"(c) If the net retail price (excluding the specific tax and the value-added tax) per liter of volume capacity is more than Twenty- two pesos (P22), the tax shall be Twelve pesos and fifteen centavos (P12.15) per liter.\n\"Variants of existing brands which are introduced in the domestic market after the effectivity of this Act shall be taxed under the highest classification of any variant of that brand.\n\"Fermented liquor which are brewed and sold at microbreweries or small establishments such as pubs and restaurants shall be subject to the rate in paragraph (c) hereof.\n\"The specific tax from any brand of fermented liquor within the next three (3) years from the effectivity of this Act shall not be lower than the tax which was due from each brand on October 1, 1996.\n\"The rates of specific tax on fermented liquor under paragraphs (a), (b) and (c) hereof shall be increased by twelve percent (12%) on January 1, 2000.\n\"New brands shall be classified according to their current net retail price.\n\"For the above purpose, net retail price shall mean the price at which the fermented liquor is sold on retail in 20 major supermarkets in Metro Manila (for brands of fermented liquor marketed nationally), excluding the amount intended to cover the applicable excise tax and the value-added tax. For brands which are marketed only outside Metro Manila, the net retail price shall mean the price at which the fermented liquor is sold in five major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"The classification of each brand of fermented liquor based on its average net retail price as of October 1, 1996, as set forth in Annex 'C,' shall remain in force until revised by Congress.\n\"A variant of a brand shall refer to a brand on which a modifier is prefixed and/or suffixed to the root name of the brand and/or a different brand which carries the same logo or design of the existing brand.\n\"Every brewer or importer of fermented liquor shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every month thereafter, submit to the Commissioner of Internal Revenue a sworn statement of the volume of sales for each particular brand of fermented liquor sold at his establishment for the three-month period immediately preceding.\n\"Any brewer or importer who, in violation of this section, knowingly misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as brewer or importer of fermented liquor.\n\"Any corporation, association, or partnership liable for any of the acts or omissions in violation of this section shall be fined treble the amount of deficiency taxes, surcharges, and interest which may be assessed pursuant to this section.\n\"Any person liable for any of the acts or omissions prohibited under this section shall be criminally liable and penalized under Section 253 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence without further proceedings for deportation.\""}},{"id":"PH-H6718-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 142 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 142. Cigars and cigarettes. – (a) Cigars. – There shall be levied, assessed and collected on cigars a tax of One peso (P1) per cigar.\n\"(b) Cigarettes packed by hand. – There shall be levied, assessed and collected on cigarettes packed by hand a tax of Forty centavos (P0.40) per pack.\n\"(c) Cigarettes packed by machine. – There shall be levied, assessed and collected on cigarettes packed by machine a tax at the rates prescribed below:\n\"(1) If the net retail price (excluding the excise tax and the value-added tax) is above Ten pesos (P10) per pack, the tax shall be Twelve pesos (P12) per pack;\n\"(2) If the net retail price (excluding the excise tax and the value-added tax) exceeds Six pesos and fifty centavos (P6.50) but does not exceed Ten pesos (P10) per pack, the tax shall be Eight pesos (P8) per pack;\n\"(3) If the net retail price (excluding the excise tax and the value-added tax) is Five pesos (P5) but does not exceed Six pesos and fifty centavos (P6.50) per pack, the tax shall be Five pesos (P5) per pack;\n\"(4) If the net retail price (excluding the excise tax and the value-added tax) is below Five pesos (P5) per pack, the tax shall be One peso (P1) per pack.\n\"Variants of existing brands of cigarettes which are introduced in the domestic market after the effectivity of this Act shall be taxed under the highest classification of any variant of that brand.\n\"The specific tax from any brand of cigarettes within the next three (3) years of effectivity of this Act shall not be lower than the tax which is due from each brand on October 1, 1996: Provided, however , That in cases where the specific tax rates imposed in paragraphs (1), (2), (3) and (4) hereinabove will result in an increase in excise tax of more than seventy percent (70%), for a brand of cigarette, the increase shall take effect in two tranches: fifty percent (50%) of the increase shall be effective in 1997 and one hundred percent (100%) of the increase shall be effective in 1998.\n\"Duly registered or existing brands of cigarettes or new brands thereof packed by machine shall only be packed in twenties.\n\"The rates of specific tax on cigars and cigarettes under paragraphs (1), (2), (3) and (4) hereof, shall be increased by twelve percent (12%) on January 1, 2000.\n\"New brands shall be classified according to their current net retail price.\n\"For the above purpose, net retail price shall mean the price at which the cigarette is sold on retail in 20 major supermarkets in Metro Manila (for brands of cigarettes marketed nationally), excluding the amount intended to cover the applicable excise tax and the value-added tax. For brands which are marketed only outside Metro Manila, the net retail price shall mean the price at which the cigarette is sold in five major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"The classification of each brand of cigarettes based on its average net retail price as of October 1, 1996, as set forth in Annex 'D' of this Act, shall remain in force until revised by Congress.\n\"Variant of a brand shall refer to a brand on which a modifier is prefixed and/or suffixed to the root name of the brand and/or a different brand which carries the same logo or design of the existing brand.\n\"Manufacturers and importers of cigars and cigarettes shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every month thereafter submit to the Commissioner of Internal Revenue a sworn statement of the volume of sales for each particular brand of cigars and/or cigarettes sold at his establishment for the three-month period immediately preceding.\n\"Any manufacturer or importer who, in violation of this section, knowingly misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall, upon discovery, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of cigars or cigarettes.\n\"Any corporation, association, or partnership liable for any of the acts or omissions in violation of this section shall be fined treble the amount of deficiency taxes, surcharges, and interest which may be assessed pursuant to this section.\n\"Any person liable for any of the acts or omissions prohibited under this section shall be criminally liable and penalized under Section 253 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence without further proceedings for deportation.\""}},{"id":"PH-H6718-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The tax rates prescribed under this Act shall take effect on January 1, 1997."}},{"id":"PH-H6718-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Internal revenue stamps, whether of a bar code or fuson design, shall be firmly and conspicuously affixed on each pack of cigars and cigarettes subject to specific tax in the manner and form as prescribed by the Commissioner of Internal Revenue upon approval of the Secretary of Finance.\nExcisable articles such as distilled spirits, fermented liquor, cigars and cigarettes which are sold tax and duty free in all authorized establishments shall be marked tax and duty free in a manner and form prescribed by the Secretary of Finance."}},{"id":"PH-H6718-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The classifications set forth in Annex \"A\" for distilled spirits, Annex \"B\" for wines, Annex \"C\" for fermented liquor and Annex \"D\" for cigarettes are hereby adopted and made an integral part of this Act."}},{"id":"PH-H6718-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Fifteen percent (15%) of the incremental revenue collected from the excise tax on tobacco products under this Act shall be allocated and divided among the provinces producing burley and native tobacco in accordance with the volume of tobacco leaf production. The fund shall be exclusively utilized for programs in pursuit of the following objectives:\na. Cooperative projects that will enhance better quality of agricultural products and increase income and productivity of farmers;\nb. Livelihood projects particularly the development of alternative farming system to enhance farmer's income;\nc. Agro-industrial projects that will enable tobacco farmers to be involved in the management and subsequent ownership of projects such as post-harvest and secondary processing like cigarette manufacturing and by-product utilization.\nThe Department of Budget and Management in consultation with the Oversight Committee created hereunder shall issue the corresponding rules and regulations governing the allocation and disbursement of this fund."}},{"id":"PH-H6718-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"An Oversight Committee is hereby created which shall be composed of the Chairmen of the Committees on Ways and Means of the Senate and the House of Representatives and four (4) additional members from each House to be designated by the Senate President and the Speaker of the House of Representatives, respectively. The Oversight Committee shall monitor and ensure the proper implementation of this Act."}},{"id":"PH-H6718-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6718-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"If any of the provisions of this Act is declared invalid by competent court, the remainder of this Act or any provision not affected by such declaration of invalidity shall remain in force and effect."}},{"id":"PH-H6718-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All laws, decrees, ordinances, rules and regulations, executive or administrative orders, and such other presidential issuances as are inconsistent with any of the provisions of this Act are hereby repealed, amended or otherwise modified accordingly."}},{"id":"PH-H6718-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect on January 1, 1997.\nApproved, November 22, 1996."}}],"pack":"ph-p95"};
  FT["PH-H6719"] = {"id":"PH-H6719","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8241_1996.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"对第 7716 号共和国法的修改","en":"An Act Amending Republic Act No. 7716, Otherwise Known as the Expanded Value-added Tax Law and Other Pertinent Provisions of the National Internal Revenue Code, as Amended","orig":"An Act Amending Republic Act No. 7716, Otherwise Known as the Expanded Value-added Tax Law and Other Pertinent Provisions of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 8241","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-20","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8241_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 17 条，缺 16）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。 源文存在同号重出的条款（第 3、4、7、9、10、11、12 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6719-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 3 of Republic Act No. 7716 is hereby amended to read as follows:\n\""}},{"id":"PH-H6719-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 102 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 102. Value-added tax on sale of services and use or lease of properties. – (a) Rate and base of tax. – There shall be levied, assessed and collected, a value-added tax equivalent to ten percent (10%) of gross receipts derived from the sale or exchange of services, including the use or lease of properties.\n\"The phrase sale or exchange of services means the performance of all kinds of services in the Philippines for others for a fee, remuneration or consideration, including those performed or rendered by construction and service contractors; stock, real estate, commercial, customs and immigration brokers; lessors of property, whether personal or real; warehousing services; lessors or distributors of cinematographic films; persons engaged in milling, processing, manufacturing or repacking goods for others; proprietors, operators or keepers of hotels, motels, rest houses, pension houses, inns, resorts; proprietors or operators of restaurants, refreshment parlors, cafes and other eating places, including clubs and caterers; dealers in securities; lending investors; transportation contractors on their transport of goods or cargoes, including persons who transport goods or cargoes for hire and other domestic common carriers by land, air, and water relative to their transport of goods or cargoes; services of franchise grantees of telephone and telegraph, radio and television broadcasting and all other franchise grantees except those under Section 117 of this Code; services of banks, non-bank financial intermediaries and finance companies; and non-life insurance companies (except their crop insurances) including surety, fidelity, indemnity and bonding companies; and similar services regardless of whether or not the performance thereof calls for the exercise or use of the physical or mental faculties. The phrase sale or exchange of services shall likewise include:\n\"(1) The lease or the use of or the right or privilege to use any copyright, patent, design or model, plan, secret formula or process, goodwill, trademark, trade brand or other like property or right;\n\"(2) The lease or the use of, or the right to use of any industrial, commercial or scientific equipment;\n\"(3) The supply of scientific, technical, industrial or commercial knowledge or information;\n\"(4) The supply of any assistance that is ancillary and subsidiary to and is furnished as a means of enabling the application or enjoyment of any such property, or right as is mentioned in subparagraph (2) or any such knowledge or information as is mentioned in subparagraph (3);\n\"(5) The supply of services by a nonresident person or his employee in connection with the use of property or rights belonging to, or the installation or operation of any brand, machinery, or other apparatus purchased from such nonresident person;\n\"(6) The supply of technical advice, assistance or services rendered in connection with technical management or administration of any scientific, industrial or commercial undertaking, venture, project or scheme;\n\"(7) The lease of motion picture films, films, tapes and discs; and \"(8) The lease or the use of or the right to use radio, television, satellite transmission and cable television time.\n\"Lease of properties shall be subject to the tax herein imposed irrespective of the place where the contract of ease or licensing agreement was executed if the property is leased or used in the Philippines.\n\"The term 'gross receipts' means the total amount of money or its equivalent representing the contract price, compensation, service fee, rental or royalty, including the amount charged for materials supplied with the services and deposits and advanced payments actually or constructively received during the taxable quarter for the services performed or to be performed for another person, excluding value-added tax.\n\"(b) Transactions subject to zero percent (0%) rate. – The following services performed in the Philippines by VAT-registered persons shall be subject to zero percent (0%) rate:\n\"(1) Processing, manufacturing or repacking goods for other persons doing business outside the Philippines which goods are subsequently exported, where the services are paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP);\n\"(2) Services other than those mentioned in the preceding subparagraph, the consideration for which is paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP);\n\"(3) Services rendered to persons or entities whose exemption under special laws or international agreements to which the Philippines is a signatory effectively subjects the supply of such services to zero percent (0%) rate;\n\"(4) Services rendered to vessels engaged exclusively in international shipping; and \"(5) Services performed by subcontractors and/or contractors in processing, converting, or manufacturing goods for an enterprise whose export sales exceed seventy percent (70%) of total annual production.\n\"(c) Det ermination of the tax. – The tax shall be computed by multiplying the total amount indicated in the official receipt by 1/11.\""}},{"id":"PH-H6719-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 4 of Republic Act No. 7716 is hereby amended to read as follows:\n\""}},{"id":"PH-H6719-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 103 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 103. Exempt Transactions. – The following shall be exempt from the value-added tax:\n\"(a) Sale of nonfood agricultural products; marine and forest products in their original state by the primary producer or the owner of the land where the same are produced;\n\"(b) Sale of cotton and cotton seeds in their original state; and copra;\n\"(c) Sale or importation of agricultural and marine food products in their original state, livestock and poultry of a kind generally used as, or yielding or producing foods for human consumption; and breeding stock and genetic materials therefore.\n\"Products classified under this paragraph and paragraph (a) shall be considered in their original state even if they have undergone the simple processes of preparation or preservation for the market, such as freezing, drying, salting, broiling, roasting, smoking or stripping. Polished and/or husked rice, corn grits, raw cane sugar and molasses, and ordinary salt shall be considered in their original state;\n\"(d) Sale or importation of fertilizers; seeds, seedlings and fingerlings; fish, prawn, livestock and poultry feeds, including ingredients, whether locally produced or imported, used in the manufacture of finished feeds (except specialty feeds for race horses, fighting cocks, aquarium fish, zoo animals and other animals generally considered as pets);\n\"(e) Sale or importation of coal and natural gas, in whatever form or state, and petroleum products (except lubricating oil, processed gas, grease, wax, and petrolatum) subject to excise tax imposed under Title VI;\n\"(f) Sale or importation of raw materials to be used by the buyer or importer himself in the manufacture of petroleum products subject to excise tax, except lubricating oil, processed gas, grease, wax, and petrolatum;\n\"(g) Importation of passenger and/or cargo vessel of more than five thousand tons, whether coastwise or ocean-going, including engine and spare parts of said vessel to be used by the importer himself as operator thereof;\n\"(h) Importation of personal and household effects belonging to the residents of the Philippines returning from abroad and nonresident citizens coming to resettle in the Philippines: Provided, That such goods are exempt from customs duties under the Tariff and Customs Code of the Philippines;\n\"(i) Importation of professional instruments and implements, wearing apparel, domestic animals, and personal household effects (except any vehicle, vessel, aircraft, machinery, other goods for use in the manufacture and merchandise of any kind in commercial quantity) belonging to persons coming to settle in the Philippines, for their own use and not for sale, barter or exchange, accompanying such persons, or arriving within ninety (90) days before or after their arrival, upon the production of evidence satisfactory to the Commissioner of Internal Revenue, that such persons are actually coming to settle in the Philippines and that the change of residence is bona fide;\n\"(j) Services subject to percentage tax under Title V;\n\"(k) Services by agricultural contract growers and milling for others of palay into rice, corn into grits and sugar cane into raw sugar;\n\"(l) Medical, dental, hospital and veterinary services subject to the provisions of Section 17 of Republic Act No. 7716, as amended;\n\"(m) Educational services rendered by private educational institutions, duly accredited by the Department of Education, Culture and Sports (DECS) and the Commission on Higher Education (CHED), and those rendered by government educational institutions;\n\"(n) Sale by the artist himself of his works of art, literary works, musical compositions and similar creations, or his services performed for the production of such works;\n\"(o) Services rendered by individuals pursuant to an employer-employee relationship;\n\"(p) Services rendered by regional or area headquarters established in the Philippines by multinational corporations which act as supervisory, communications and coordinating centers for their affiliates, subsidiaries or branches in the Asia-Pacific Region and do not earn or derive income from the Philippines;\n\"(q) Transactions which are exempt under international agreements to which the Philippines is a signatory or under special laws, except those under Presidential Decree Nos. 66, 529, and 1590;\n\"(r) Sales by agricultural cooperatives duly registered with the Cooperative Development Authority to their members as well as sale of their produce, whether in its original state or processed form, to non-members; their importation of direct farm inputs, machineries and equipment, including spare parts thereof, to be used directly and exclusively in the production and/or processing of their produce;\n\"(s) Sales by electric cooperatives duly registered with the Cooperative Development Authority or National Electrification Administration, relative to the generation and distribution of electricity as well as their importation of machineries and equipment, including spare parts, which shall be directly used in the generation and distribution of electricity;\n\"(t) Gross receipts from lending activities by credit or multi-purpose cooperatives duly registered with the Cooperative Development Authority whose lending operation is limited to their members;\n\"(u) Sales by non-agricultural, non-electric and non-credit cooperatives duly registered with the Cooperative Development Authority: Provided, That the share capital contribution of each member does not exceed Fifteen thousand pesos (P15,000.00) and regardless of the aggregate capital and net surplus ratably distributed among the members;\n\"(v) Export sales by persons who are not VAT-registered;\n\"(w) Sale of real properties not primarily held for sale to customers or held for lease in the ordinary course of trade or business or real property utilized for low-cost and socialized housing as defined by Republic Act No. 7279, otherwise known as the Urban Development and Housing Act of 1992, and other related laws, house and lot and other residential dwellings valued at One million pesos (P1,000,000.00) and below: Provided, That not later than January 31st of the calendar year subsequent to the effectivity of this Act and each calendar year thereafter, the amount of One million pesos (P1,000,000.00) shall be adjusted to its present value using the consumer price index, as published by the National Statistics Office (NSO);\n\"(x) Lease of a residential unit with a monthly rental not exceeding Eight thousand pesos (P8,000.00): Provided, That not later than January 31st of the calendar year subsequent to the effectivity of this Act and each calendar year thereafter, the amount of Eight thousand pesos (P8,000.00) shall be adjusted to its present value using the consumer price index, as published by the National Statistics Office (NSO);\n\"(y) Sale, importation, printing or publication of books and any newspaper, magazine, review, or bulletin which appears at regular intervals with fixed prices for subscription and sale and which is not devoted principally to the publication of paid advertisements;\n\"(z) Sale or lease of goods or properties or the performance of services other than the transactions mentioned in the preceding paragraphs, the gross annual sales and/or receipts do not exceed the amount of Five hundred fifty thousand pesos (P550,000.00): Provided, That not later than January 31st of the calendar year subsequent to the effectivity of this Act and each calendar year thereafter, the amount of Five hundred fifty thousand pesos (P550,000.00) shall be adjusted to its present value using the consumer price index, as published by the National Statistics Office (NSO);\n\"The foregoing exemptions to the contrary notwithstanding, any person whose sale of goods or properties or services which are otherwise not subject to VAT, but who issues a VAT invoice or receipt therefore shall, in addition to his liability to other applicable percentage tax, if any, be liable to the tax imposed in Section 100 or 102 without the benefit of input tax credit, and such tax shall not also be recognized as input tax credit to the purchaser under Section 104, all of this Code.\""}},{"id":"PH-H6719-A3-d2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 105 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 105. Transitional/Presumptive Input Tax Credits. – (a) Transitional Input Tax Credits. – A person who becomes liable to value-added tax or any person who elects to be a VAT registered person shall, subject to the filing of an inventory as prescribed by regulations, be allowed input tax on his beginning inventory of goods, materials and supplies equivalent to eight percent (8%) of the value of such inventory or the actual value added tax paid on such goods, materials and supplies, whichever is higher, which shall be creditable against the output tax.\n\"(b) Presumptive input tax credits. – (1) Persons or firms engaged in the processing of sardines, mackerel, and milk, and in manufacturing refined sugar and cooking oil, shall be allowed a presumptive input tax, creditable against the output tax, equivalent to one and one-half percent (1.5%) of the gross value in money of their purchases of primary agricultural products which are used as inputs to their production.\n\"As used in this paragraph (b), the term 'processing' shall mean pasteurization, canning and activities which through physical or chemical process alter the exterior texture or form or inner substance of a product in such manner as to prepare it for special use to which it could not have been put in its original form or condition.\n\"(2) Public works contractors shall be allowed a presumptive input tax equivalent to one and one-half percent (1.5%) of the contract price with respect to government contracts only in lieu of actual input taxes there from.\""},"dupIndex":2},{"id":"PH-H6719-A4-d2","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 7 of Republic Act No. 7716 is hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H6719-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 107 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 107. Registration of value-added taxpayers. – (a) In General. – Any person subject to a value-added tax under Sections 100 and 102 of this Code shall register with the appropriate Revenue District Officer and pay an annual registration fee in the amount of One thousand pesos (P1,000) for every separate or distinct establishment or place of business and every year thereafter on or before the last day of January. Any person just commencing a business subject to the value-added tax must pay the fee before engaging therein.\n\"A person who maintains a head or main office and branches in different places shall register with the Revenue District Office which has jurisdiction over the place wherein the main or head office is located. However, the fee shall be paid to the Revenue District Officer, collection agent, authorized treasurer of the municipality where each place of business or branch is situated.\n\"(b) Persons commencing business. – Any person who expects to realize gross sales or receipts subject to value-added tax in excess of the amount prescribed under Section 103(z) of this Code for the next 12-month period from the commencement of the business shall, within thirty (30) days before the start of the said business register with the Revenue District Officer who has jurisdiction over his principal place of business and shall pay the annual registration fee prescribed in the preceding paragraph.\n\"(c) Persons becoming liable to the value-added tax. – Any person whose gross sales or receipts in any 12-month period exceeds the amount prescribed under Section 103(z) of this Code for exemption from the value-added tax shall register and pay the annual registration fee prescribed in paragraph (a) of this section within thirty (30) days after the end of the last month of that period, and shall be liable to the value-added tax commencing from the first day of the month following his registration.\n\"(d) Optional registration of exempt person. – Any person whose transactions are exempt from value-added tax under Section 103(z) of this Code, Section 103(a), (b), (c), and (d) of this Code with respect to export sales only, and Section 103(j) with respect to services of franchise grantees of radio and/or television broadcasting as defined under Section 117 of this Code, may apply for registration as a VAT-registered person not later than ten (10) days before the beginning of the taxable quarter and shall pay the annual registration fee prescribed in subparagraph (a) of this section.\n\"In any case, the Commissioner may, for administrative reason, deny any application for registration.\n\"For purposes of this Title, any person registered in accordance with the provisions of this section shall be referred to as a 'VAT-registered person.' Each VAT-registered person shall be assigned only one taxpayer's identification number.\n\"(e) Cancellation of registration. – The registration of any person who ceases to be liable to the value-added tax shall be cancelled by the Commissioner upon filing of an application for cancellation of registration. Any person who opted to be registered under paragraph (d) of this section may, under regulation of the Secretary of Finance, apply for cancellation of such registration.\""}},{"id":"PH-H6719-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 9 of Republic Act No. 7716 is hereby amended to read as follows:\n\""}},{"id":"PH-H6719-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 110(c) of the National Internal Revenue Code, is hereby further amended to read as follows:\n\"(c) Withholding of Creditable Value-Added Tax. – The government or any of its political subdivisions, instrumentalities or agencies, including government-owned or controlled corporations (GOCCs) shall, before making payment on account of each purchase of goods from sellers and services rendered by contractors which are subject to the value-added tax imposed in Sections 100 and 102 of this Code, deduct and withhold the value added tax due at the rate of three percent (3%) of the gross payment for the purchase of goods and six percent (6%) on gross receipts for services rendered by contractors on every sale or installment payment which shall be creditable against the value-added tax liability of the seller or contractor: Provided, however , That in the case of government public works contractors, the withholding rate shall be eight and one-half percent (8.5%): Provided, further , That the payment for lease or use of properties or property rights to nonresident owners shall be subject to ten percent (10%) withholding tax at the time of payment. For this purpose, the payor or person in control of the payment shall be considered as the withholding agent.\n\"The value-added tax withheld under this section shall be remitted within ten (10) days following the end of the month the withholding was made.\""}},{"id":"PH-H6719-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 10 of Republic Act No. 7716 is hereby amended to read as follows:\n\""}},{"id":"PH-H6719-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 112 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 112. Tax on persons exempt from value-added tax (VAT). – Any person whose sales or receipts are exempt under Section 103(z) of this Code from the payment of value-added tax and who is not a VAT-registered person shall pay a tax equivalent to three percent (3%) of his gross quarterly sales or receipts: Provided, That cooperatives shall be exempt from the three percent (3%) gross receipts tax herein imposed.\""}},{"id":"PH-H6719-A7-d2","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 11 of Republic Act No. 7716 is hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H6719-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 115 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 115. Percentage tax on domestic carriers and keepers of garages. – Cars for rent or hire driven by the lessee, transportation contractors, including persons who transport passenger for hire, and other domestic carriers by land, air or water, for the transport of passengers, except owners of bancas, and owners of animal-drawn two-wheeled vehicle, and keepers of garages shall pay a tax equivalent to three per centum (3%) of their quarterly gross receipts.\n\"The gross receipts of common carriers derived from their incoming and outgoing freight shall not be subjected to the local taxes imposed under Republic Act No. 7160, otherwise known as the Local Government Code of 1991.\n\"In computing the percentage tax provided in this section, the following shall be considered the minimum quarterly gross receipts in each particular case:\n\"Jeepney for hire – \"1. Manila and other cities P2,400.00 \"2. Provincial 1,200.00 \"Public utility bus – \"Not exceeding 30 passengers P3,600.00 \"Exceeding 30 but not exceeding 50 passengers 6,000.00 \"Exceeding 50 passengers 7,200.00 \"Taxis – \"1. Manila and other cities P3,600.00 \"2. Provincial 2,400.00 \"Car for hire (w/ chauffeur) 3,000.00 \"Car for hire (w/o chauffeur) 1,800.00\""}},{"id":"PH-H6719-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"A new section is hereby added after Section 115 of the National Internal Revenue Code, as amended, to read as follows:\n\"Section 115-A. Percentage tax on international carriers.\n\"(a) International air carriers doing business in the Philippines shall pay a tax of three per centum (3%) of their quarterly gross receipts.\n\"(b) International shipping carriers doing business in the Philippines shall pay a tax equivalent to three per centum (3%) of their quarterly gross receipts.\""}},{"id":"PH-H6719-A9-d2","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 12 of Republic Act No. 7716 is hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H6719-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 117 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 117. Tax on franchises. – Any provision of general or special law to the contrary, notwithstanding, there shall be levied, assessed and collected in respect to all franchises on radio and/or television broadcasting companies whose annual gross receipts of the preceding year does not exceed Ten million pesos (P10,000,000.00), subject to Section 107(d) of this Code, a tax of three percent (3%) and on electric, gas and water utilities, a tax of two percent (2%) on the gross receipts derived from the business covered by the law granting the franchise: Provided, however , That radio and television broadcasting companies referred to in this section, shall have an option to be registered as a value added tax payer and pay the tax due thereon: Provided, further , That once the option is exercised, it shall not be revoked.\n\"The grantee shall file the return with, and pay the tax due thereon to, the Commissioner of Internal Revenue or his duly authorized representative in accordance with the provisions of Section 125 of this Code and the return shall be subject to audit by the Bureau of Internal Revenue, any provision of any existing law to the contrary notwithstanding.\""}},{"id":"PH-H6719-A10-d2","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 15 of Republic Act No. 7716 is hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H6719-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 237 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 237. Registration of Name or Style with the Revenue District Officer or Collection Agent. – Every person, other than persons required to be registered under the provisions of Section 107 engaged in any business shall, on or before the commencement of his business, or whenever he transfers to another revenue district, register with the Revenue District Officer concerned within 10 days from the commencement of business or transfer and shall pay the annual registration fee in the amount of Five hundred pesos (P500.00) for every separate or distinct establishment or place of business and every year thereafter on or before the last day of January. The fee shall be paid to the Revenue District Officer, collection agent, authorized treasurer of the municipality where each place of business or branch is situated. In cities or municipalities where no Revenue District Officer is stationed, such person shall register and pay the fee prescribed herein with the collection agent. The registration shall contain his name or style, place of residence, business, the place where such business is carried on, and such other information as may be required by the Commissioner in the form prescribed therefore. In the case of a firm, the names and residences of the various persons constituting the same shall also be registered. The Commissioner, after taking into consideration the volume of sales, financial condition and other relevant factors, may require the registrant to guarantee the payment of his taxes by way of advance payment, or the posting or filing of a security, guarantee or collateral acceptable to the Commissioner: Provided, however , That cooperatives shall not pay the registration fee imposed herein.\""}},{"id":"PH-H6719-A11-d2","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 17 of Republic Act No. 7716 is hereby amended to read as follows:\n\""},"dupIndex":2},{"id":"PH-H6719-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity of the Imposition of VAT on Certain Goods, Properties and Services. – The value-added tax shall be levied, assessed and collected on the following transactions, starting January 1, 1998:\n\"(a) Services performed in the exercise of profession or calling subject to the professional tax under the Local Government Code or Republic Act No. 7160, and professional services performed by registered general professional partnerships; actors, actresses, talents, singers and emcees; radio and television broadcasters, choreographers; musical, radio, movie, television and stage directors; and professional athletes;\n\"(b) Services rendered by banks, non-bank financial intermediaries, finance companies and other financial intermediaries not performing quasi-banking functions; and \"(c) The lease or use of sports facilities and equipment by amateur players, as provided under Republic Act No. 6847, except sports facilities and equipment which are exclusively or mainly for the private use of shareholders or members of the club or organization which owns or operates such sports facilities and equipment.\n\"Prior to their inclusion in the coverage of the value-added tax, the above services shall continue to pay the applicable tax prescribed under the present provisions of the National Internal Revenue Code, as amended.\n\"However, when public interest so requires, the Congress of the Republic of the Philippines, taking into account the impact on prices of goods and services, may, exclude any of the above services from the coverage of the value-added tax: Provided, however , That in the event of the exclusion of any of the above services the existing applicable tax under the provisions of the National Internal Revenue Code, as amended, shall continue to be paid on the service so excluded.\""}},{"id":"PH-H6719-A12-d2","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Rules and Regulations. – For the effective implementation of this Act, the Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations, within sixty (60) days from effectivity hereof: Provided, That other agencies, such as, but not limited to, the Philippine Information Agency (PIA), Office of the Press Secretary (OPS), the Bureau of Internal Revenue (BIR) and the Department of Trade and Industry (DTI), shall develop and implement an Information, Education and Communication (IEC) campaign program with the end in view of effectively informing the public on the details of the expanded value-added tax implementation."},"dupIndex":2},{"id":"PH-H6719-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing Clause. – The provisions of Republic Act No. 6938, otherwise known as the Cooperative Code of the Philippines, authorizing the exemption of cooperatives from the sales or value-added tax are hereby repealed. All other laws, orders, issuances, rules and regulations or parts thereof which are not consistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6719-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity. – This Act shall take effect on January 1, 1997.\nApproved, December 20, 1996."}}],"pack":"ph-p95"};
  FT["PH-H6720"] = {"id":"PH-H6720","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8242_1996.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将南伊罗戈省西奈特市镇普格-奥斯描笼涯的名称变更为院长Leopoldo Yabes描笼涯的法案","en":"An Act Changing the Name of Barangay Pug-os in the Municipality of Sinait, Province of Ilocos Sur, to Barangay Dean Leopoldo Yabes","orig":"An Act Changing the Name of Barangay Pug-os in the Municipality of Sinait, Province of Ilocos Sur, to Barangay Dean Leopoldo Yabes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 8242","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8242_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6720-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barangay Pug-os in the Municipality of Sinait, Province of Ilocos Sur, is hereby changed to Barangay Dean Leopoldo Yabes."}},{"id":"PH-H6720-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, December 20, 1996."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barangay Pug-os in the Municipality of Sinait, Province of Ilocos Sur, to Barangay Dean Leopoldo Yabes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6721"] = {"id":"PH-H6721","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8243_1996.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将南伊罗戈省班泰市镇萨拉孔描笼涯的名称变更为圣马里亚诺描笼涯的法案","en":"An Act Changing the Name of Barangay Sallacong in the Municipality of Bantay, Province of Ilocos Sur, to Barangay San Mariano","orig":"An Act Changing the Name of Barangay Sallacong in the Municipality of Bantay, Province of Ilocos Sur, to Barangay San Mariano"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 8243","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8243_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6721-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barangay Sallacong in the Municipality of Bantay, Province of Ilocos Sur, is hereby changed to Barangay San Mariano."}},{"id":"PH-H6721-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barangay Sallacong in the Municipality of Bantay, Province of Ilocos Sur, to Barangay San Mariano","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6722"] = {"id":"PH-H6722","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8244_1996.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Twenty–Seven Billion Pesos (27,000,000,000.00) to Fund the Fourth–Year Implementation of the Salary Increases Authorized By Joint Resolution No. 1, Series of 1994, and for Other Purposes","orig":"An Act Appropriating the Sum of Twenty–Seven Billion Pesos (27,000,000,000.00) to Fund the Fourth–Year Implementation of the Salary Increases Authorized By Joint Resolution No. 1, Series of 1994, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8244","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-30","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8244_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6722-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation for National Government Agencies. – The amount of Twenty–seven Billion Pesos (27,000,000,000.00), or so much thereof as may be necessary, is hereby appropriated to cover the funding requirements for the fourth and final year of implementation of the salary increases authorized by Joint Resolution No. 1, Series of 1994, for all national government personnel, including the uniformed personnel of the Department of National Defense and the Department of the Interior and Local Government, according to the following schedule:\n(1) Effectivity January 1, 1997 – Payment of fifty percent (50%) of the unimplemented balance as of December 31, 1996 of the basic pay corresponding to the Salary Grade concerned;\n(2) Effective November 1, 1997 – Payment of the remaining fifty percent (50%) of said unimplemented balance to effect full salary adjustment."}},{"id":"PH-H6722-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Funding for Other Personnel. – For government–owned and controlled corporations, the amount needed to implement the aforesaid salary adjustment for their personnel shall come from their respective corporate funds. For local government units, the amount needed for the purpose shall be charged to their respective local funds."}},{"id":"PH-H6722-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Basis of Retirement Benefits. – Government personnel who will compulsorily retire prior to November 1, 1997 shall be entitled to retirement benefits based on the full rate of implementation under Section 1(2) hereof."}},{"id":"PH-H6722-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Prohibition. – The salary adjustment funded herein shall not benefit the President, the Vice–President and the Members of Congress."}},{"id":"PH-H6722-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Implementing Guidelines. – The Department of Budget and Management shall issue the necessary guidelines for the implementation of the salary adjustment herein authorized."}},{"id":"PH-H6722-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity. – This Act shall take effect on January 1, 1997."}}],"pack":"ph-p95"};
  FT["PH-H6723"] = {"id":"PH-H6723","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8245_1996.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"1997年总拨款法","en":"General Appropriation Act of 1997.","orig":"General Appropriation Act of 1997. An Act Appropriating the Sum of Fourteen Billion Four Hundred Fifty-five Million Pesos (P14,455,000,000) for the Increased Share in 1997 of Local Government Units in the National Internal Revenue Taxes and for Other Purposes"},"level":"law","status":"active","topics":["tax","administrative"],"docNumber":"Republic Act No. 8245","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8245_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6723-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation, Allotment and Release of Funds. – The amount of Fourteen billion four hundred fifty-five million pesos (14,455,000,000) is hereby appropriated for the increased share in 1997 of local government units in the internal revenue taxes pursuant to Section 284 of Republic Act No. 7160, the Local Government Code of 1991, and shall be apportioned among the local government units in accordance with the formula prescribed in Section 285 thereof, after deducting the actual cost of devolution and the cost of city-funded hospitals as of December 31, 1992. Said internal revenue allotment shall be released directly by the Department of Budget and Management to the local government units concerned."}},{"id":"PH-H6723-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Use of Funds. – The use of funds herein appropriated shall be in accordance with the provisions of the Local Government Code of 1991, Republic Act No. 7160."}},{"id":"PH-H6723-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effectivity. – This Act shall take effect on January 1, 1997."}}],"pack":"ph-p95"};
  FT["PH-H6724"] = {"id":"PH-H6724","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8246_1996.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"在上诉法院增设审判庭、将上诉法院大法官由五十一（51）名增至六十九（69）名，为此修订第 129 号 Batas Pambansa（1980 年司法重组法）并为其拨款的法案","en":"An Act Creating Additional Divisions in the Court of Appeals, Increasing the Number of Court of Appeals Justices From Fifty-one (51) to Sixty-nine (69), Amending for the Purpose Batas Pambansa Bilang 129, as Amended, Otherwise Known as the Judiciary Reorganization Act of 1980, Appropriating Funds Therefor, and for Other Purposes","orig":"An Act Creating Additional Divisions in the Court of Appeals, Increasing the Number of Court of Appeals Justices From Fifty-one (51) to Sixty-nine (69), Amending for the Purpose Batas Pambansa Bilang 129, as Amended, Otherwise Known as the Judiciary Reorganization Act of 1980, Appropriating Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 8246","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-30","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8246_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6724-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 3, Chapter 1 of Batas Pambansa Blg. 129, as amended, is hereby further amended to read as follows:\n\"Sec 3. Organization. – There is hereby created a Court of Appeals which shall consist of a Presiding Justice and sixty-eight (68) Associate Justices who shall be appointed by the President of the Philippines. The Presiding Justice shall be so designated in his appointment, and the Associate Justices shall have precedence according to the dates of their respective appointments, or when the appointments of two or more of them shall bear the same date, according to the order in which their appointments were issued by the President. Any member who is reappointed to the Court after rendering service in another position in the government shall retain the precedence to which he was entitled under his original appointment. and his service in the Court shall, for all intents and purposes, be considered as continuous and uninterrupted."}},{"id":"PH-H6724-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 4 of Batas Pambansa Blg. 129, as amended, is hereby further amended to read as follows:\n\"Sec. 4. Exercise of Powers and Functions. – The Court of Appeals shall exercise its powers, functions, and duties through twenty-three (23) divisions. each composed of three (3) members. The Court may sit en banc for the purpose of exercising administrative, ceremonial or other nonadjudicatory functions."}},{"id":"PH-H6724-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 10 of Batas Pambansa Blg. 129, as amended, is hereby further amended to read as follows:\n\"Sec. 10. Place of Holding Sessions. – The Court of Appeals shall have its permanent stations as follows: The first seventeen (17) divisions shall be stationed in the City of Manila for cases coming from the First to the Fifth Judicial Regions; the Eighteenth, Nineteenth, and Twentieth Divisions shall be in Cebu City for cases coming from the Sixth, Seventh and Eighth Judicial Regions; the Twenty-first, Twenty-second and Twenty-third Divisions shall be in Cagayan de Oro City for cases coming from the Ninth, Tenth, Eleventh, and Twelfth Judicial Regions. Whenever demanded by public interest, or whenever justified by an increase in case load, the Supreme Court, upon its own initiative or upon recommendation of the Presiding Justice of the Court of Appeals, may authorize any division of the Court to hold sessions periodically, or for such periods and at such places ;as the Supreme Court may determine. for the purpose of hearing and deciding. cases. Trials or hearings in the Court of Appeals must be continuous and must be completed within three (3) months unless extended by the Chief Justice of the Supreme Court.\""}},{"id":"PH-H6724-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6724-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Upon the effectivity of this Act, all pending cases, except those which have been submitted for resolution, shall be referred to the proper division of the Court of Appeals."}},{"id":"PH-H6724-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Nothing in this Act shall be construed to allow the transfer, except in cases of temporary assignment, of any member of the Court of Appeals to any place or station without his or her written consent, or to undermine the security of tenure of its members as provided in the Constitution, or alter the seniority in said Court in accordance with existing laws."}},{"id":"PH-H6724-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Supreme Court, is hereby authorized and empowered to constitute a Study Committee composed of a member of the Judiciary, the prosecution, the Integrated Bar of the Philippines (IBP), a representative of the association of law colleges and law professors, and a member of the public at large.\nThe Committee shall undertake a serious study as to the feasibility and desirability of setting up a Regional Circuit Courts of Appeals in lieu and in place of the present Courts of Appeals System.\nThe Supreme Court shall submit the findings and recommendation of this Committee to Congress one (1) year after the effectivity of this Act."}},{"id":"PH-H6724-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Separability Clause. – If any portion or provision of this Act is declared unconstitutional, the remainder of this Act or any provision not affected thereby shall remain in force and effect."}},{"id":"PH-H6724-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing Clause. – All laws, presidential decrees, letters of instruction executive orders, rules and regulations, or an part thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6724-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity. – This Act shall take effect after fifteen (15) days following its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Additional Divisions in the Court of Appeals, Increasing the Number of Court of Appeals Justices From Fifty-one (51) to Sixty-nine (69), Amending for the Purpose Batas Pambansa Bilang 129, as Amended, Otherwise Known as the Judiciary Reorganization Act of 1980, Appropriating Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6725"] = {"id":"PH-H6725","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1996/ra_8247_1996.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"外国人社会融合法 1995","en":"The Alien Social Integration Act of 1995.","orig":"An Act Exempting Aliens Who Have Acquired Permanent Residency Under Executive Order No. 324 From the Coverage of Republic Act No. 7919, Otherwise Known as \"The Alien Social Integration Act of 1995.\" Amending for the Purpose Certain Provisions of Said Act and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8247","issuingBody":"Congress of the Philippines","promulgatedDate":"1996-12-20","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1996/ra_8247_1996.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6725-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 3 of Republic Act No. 7919 is hereby amended to read as follows:\n\"Sec. 3 Coverage. – Upon effectivity of this Act, all aliens whose stay in the Philippines is otherwise illegal under existing laws, and who have entered the country prior to June 30, 1992 are hereby granted legal residence status upon compliance with the provisions of this Act, and shall not be prosecuted for crimes defined under Commonwealth Act No. 613, otherwise known as the Immigration Act of 1940, which are inherent to illegal residence such as the absence of valid travel documents or visa: Provided, That in no case shall alien refugees in the Philippines be qualified to apply under this Act.\n\"The legal residence granted to aliens who availed of the benefits of Executive Order No. 324 is hereby affirmed and given full faith and credit.\n\"The bar to prosecution shall apply only to such crimes or felonies committed due to acts necessary or essential to maintain a false or fraudulent or illegal residence, such as falsification of marriage, birth or baptismal certificates or travel documents, visas or alien certificates of registration.\""}},{"id":"PH-H6725-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subsection 4.3.1 of Section 4 of the same Act is hereby amended to read as follows:\n\"4.3.1. One hundred thousand pesos (P100,000.00) upon filing of the registration forms with the bank plus fifty thousand pesos (P50,000.00) per year over a three-year period from the payment of the first installment. The subsequent three (3) installment payments should be paid within twelve (12) months from the date of the first payment without any extensions. The integration fees paid by aliens granted legal residence under Executive Order No. 324 who registered anew under the provisions of this Act shall be refunded.\n\"In lieu of the above installment payments, the applicant may immediately pay Two hundred thousand pesos (P200,000.00).\""}},{"id":"PH-H6725-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 6 of the same Act is hereby amended to read as follows:\n\"Sec. 6. Duties of the Bureau of Immigration. – Upon presentation by the applicant of the official receipt from the bank together with a certification from the bank or agency concerned, as the case may be that the civil registrar, BIR and NBI received copies of the registration forms, and the submission to the Bureau of Immigration of the registration forms defined in Section 4.2 hereof, the Bureau of Immigration shall immediately issue an Alien Certificate of Registration (ACR) to the applicant. The legal residence granted under this Act shall commence from the date the Bureau of Immigration issues the ACR and ICR.\n\"The Bureau of Immigration shall publish, at the applicant's cost, the names, ages, municipality/city of residence, and a photograph of each of the applicants in a national newspaper of general circulation at the end of each calendar month during the effectivity of the application period, as hereinafter provided in Section 8. The banks authorized under this Act to collect the fees herein required shall collect a publication fee of Five thousand pesos (P5,000.00) from the applicant.\""}},{"id":"PH-H6725-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 8 of the same Act is hereby amended to read as follows:\n\"Sec. 8. Application Period. – The benefits extended by Section 3 can be availed of from June 1, 1995 to June 30, 1997.\""}},{"id":"PH-H6725-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"If any provision of this Act is declared invalid or unconstitutional, the provisions not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6725-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All laws, decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6725-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect immediately after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Alien Social Integration Act of 1995.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6726"] = {"id":"PH-H6726","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8248_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"1994年科学技术奖学金法","en":"The Science and Technology Scholarship Act of 1994.","orig":"The Science and Technology Scholarship Act of 1994. An Act Further Strengthening the Science and Technology Program of the Government, amending for the purpose Republic Act No. 7687, otherwise known as the Science and Technology Scholarship Act of 1994"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8248","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-01-29","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8248_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6726-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 4 of Republic Act No. 7687, otherwise known as the Science and Technology Scholarship Act of 1994, is hereby amended by adding sub-section 4-A to read as follows:\n\"Sec. 4-A. Science and Technology Human Resource Development Council. – A Science and Technology Human Resource Development Council is hereby created which shall be chaired by the Secretary of the Department of Science and Technology (DOST) and shall be composed of the following members:\n\"The Chairman of the Commission on Higher Education (CHED);\n\"The Secretary of the Department of Education, Culture and Sports (DECS);\n\"The Director-General of the Technical Education and Skills Development Authority (TESDA);\n\"The Secretary of the Department of Budget and Management Authority (DBM); and \"The President of the Philippine Association of State Universities and Colleges (PASUC).\n\"The Council shall perform the following functions:\n\"(1) Coordinate science and technology human resource development programs;\n\"(2) Formulate a medium-and long-term science and technology human resource development plan in accordance with the national medium-term plan;\n\"(3) Formulate broad policies for the allocations of science and technology scholarships;\n\"(4) Formulate policies on advanced degree programs for science and technology;\n\"(5) Formulate a career system for technologists and technicians to complement the scientific career system;\n\"(6) Formulate programs to train and retrain scientist, engineers, researchers and technologists and encourage them through various incentives, to return and practice their professions in the Philippines, to enhance and accelerate the technological development of the country; and \"(7) Perform other functions necessary to effectively implement the provisions of this Act.\n\"The science and technology human resource development plan shall be submitted to the President six (6) months after the effectivity of this Act. The Council shall have a term of four (4) years commencing from the effectivity of this Act, unless otherwise extended by Congress.\""}},{"id":"PH-H6726-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 5 of the same Act is hereby amended to read as follows:\n\"Sec. 5. Appropriations. – The amount necessary to carry out the initial implementation of this Act shall be charged against the current Fiscal Year Appropriations of the Department of Science and Technology.\n\"In order to provide funds necessary for the continuous implementation of the program for every year following its initial implementation, the budget of the DOST shall be increased in the amount of Sixty million pesos (P60,000,000.00) per year until it eventually reaches the amount of Three hundred million pesos (P30,000,000.00) to sustain the recipients of the scholarship during the duration of their study.\n\"For the first two (2) years of implementation of the program, an additional Six Million pesos (P6,000,000.00) per month, to be increased to Seven million pesos (P7,000,000.00) per month on the third and fourth year shall be provided, which sum shall be generated from the net income of the Philippine Amusement and Gaming Corporation (PAGCOR): Provided, That such amount shall be strictly used to subsidize the beneficiaries' expenses while studying under the scholarship program herein provided. Priority shall be accorded to scholars graduating from high schools located in the fifth (5th) and sixth (6th) class municipalities.\""}},{"id":"PH-H6726-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in two (2) newspapers of general circulation.\nApproved: January 29, 1997"}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Science and Technology Scholarship Act of 1994.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6727"] = {"id":"PH-H6727","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8249_1997.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"进一步界定反贪法院管辖权、为此修订经修正的第 1606 号总统法令、提供经费并为其他目的法案","en":"An Act Further Defining the Jurisdiction of the Sandiganbayan, Amending for the Purpose Presidential Decree No. 1606, as Amended, Providing Funds Therefor, and for Other Purposes","orig":"An Act Further Defining the Jurisdiction of the Sandiganbayan, Amending for the Purpose Presidential Decree No. 1606, as Amended, Providing Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 8249","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-05","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8249_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6727-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section 1 of Presidential Decree No. 1606, as amended, is hereby further amended to read as follows:\n\"SECTION 1. Sandiganbayan; Composition, Qualifications; Tenure; Removal and Compensation. - A special court, of the same level as the Court of Appeals and possessing all the inherent powers of a court ofjustice, to be known as the Sandiganbayan is hereby created composed of a presiding justice and fourteen associate justices who shall be appointed by the President.\""}},{"id":"PH-H6727-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2 of the same decree is hereby further amended to read as follows:\n\"SECTION 2. Official Station; Place of Holding Sessions. - The Sandiganbayan shall have its principal office in the Metro Manila area and shall hold sessions thereat for the trial and determination of cases filed with it: Provided, however, That cases originating from the principal geographical regions of the country, that is, from Luzon, Visayas or Mindanao, shall be heard in their respective regions of origin except only when the greater convenience of the accused and of the witnesses, or other compelling considerations require the contrary, in which instance a case originating from one geographical region may be heard in another geographical region: Provided, further, That for this purpose the presiding justice shall authorize any divisions of the court to hold sessions at any time and place outside Metro Manila and, where the interest of justice so requires, outside the territorial boundaries of the Philippines. The Sandiganbayan may require the services of the personnel and the use of facilities of the courts or other government offices where any of the divisions is holding sessions and the personnel of such courts or offices shall be subject to the orders of the Sandiganbayan.\""}},{"id":"PH-H6727-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The second paragraph of Section 3 of the same decree is hereby deleted."}},{"id":"PH-H6727-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 4 of the same decree is hereby further amended to read as follows:\n\"a. Violations of Republic Act No. 3019, as amended, otherwise known as the Anti-graft and Corrupt Practices Act, Republic Act No. 1379, and Chapter II, Section 2, Title VII, Book II of the Revised Penal Code, where one or more of the accused are officials occupying the following positions in the government whether in a permanent, acting or interim capacity, at the time of the commission of the offense:\n\"(1) Officials of the executive branch occupying the positions of regional director and higher, otherwise classified as Grade '27' and higher, of the Compensation and Position Classification Act of 1989 (Republic Act No. 6758), specifically including:\n\"(a) Provincial governors, vice-governors, members of the sangguniang panlalawigan and provincial treasurers, assessors, engineers and other provincial department heads;\n\"(b) City mayors, vice-mayors, members of the sangguniang panlungsod, city treasurers, assessors engineers and other city department heads;\n\"(c) Officials of the diplomatic service occupying the position of consul and higher;\n\"(d) Philippine army and air force colonels, naval captains, and all officers of higher rank;\n\"(e) Officers of the Philippine National Police while occupying the position of provincial director and those holding the rank of senior superintendent or higher;\n\"(f) City and provincial prosecutors and their assistants, and officials and prosecutors in the Office of the Ombudsman and special prosecutor;\n\"(g) Presidents, directors or trustees, or managers of government-owned or -controlled corporations, state universities or educational institutions or foundations;\n\"(2) Members of Congress and officials thereof classified as Grade'27'and up under the Compensation and Position Classification Act of 1989;\n\"(3) Members of the judiciary without prejudice to the provisions of the Constitution;\n\"(4) Chairmen and members of Constitutional Commissions, without prejudice to the provisions of the Constitution; and \"(5) All other national and local officials classified as Grade'27'and higher under the Compensation and Position Classification Act of 1989.\n\"b. Other offenses orfelonies whether simple or complexed with other crimes committed by the public officials and employees mentioned in subsection a of this section in relation to their office.\n\"c. Civil and criminal cases filed pursuant to and in connection with Executive Order Nos. 1, 2, 14 and 14-A, issued in 1986.\n\"In cases where none of the accused are occupying positions corresponding to salary grade '27' or higher, as prescribed in the said Republic Act No. 6758, or military or PNP officers mentioned above, exclusive original jurisdiction thereof shall be vested in the proper regional trial court, metropolitan trial court, municipal trial court and municipal circuit trial court ' as the case may be, pursuant to their respective jurisdiction as provided in Batas Pambansa Blg. 129, as amended.\n\"The Sandiganbayan shall exercise exclusive appellate jurisdiction over final judgments, resolutions or orders or regional trial courts whether in the exercise of their own original jurisdiction orof their appellate jurisdiction as herein provided.\n\"The Sandiganbayan shall have exclusive original jurisdiction over petitions for the issuance of the writs of mandamus, prohibition, certiorari, habeas corpus, injunctions, and other ancillary writs and processes in aid of its appellate jurisdiction and over petitions of similar nature, including quo warranto, arising or that may arise in cases filed or which may be filed under Executive Order Nos. 1,2,14 and 14-A, issued in 1986: Provided, That the jurisdiction over these petitions shall not be exclusive of the Supreme Court.\nThe procedure prescribed in Batas Pambansa Blg. 129, as well as the implementing rules that the Supreme Court has promulgated and may hereafter promulgate, relative to appeals/petitions for review to the Court of Appeals, shall apply to appeals and petitions for review filed with the Sandiganbayan. In all cases elevated to the Sandiganbayan and from the Sandiganbayan to the Supreme Court, the Office of the Ombudsman, through its special prosecutor, shall represent the People of the Philippines, except in cases filed pursuant to Executive Order Nos. 1, 2, 14 and 14-A, issued in 1986.\n\"In case private individuals are charged as co-principals, accomplices or accessories with the public officers or employees, including those employed in govemment-owned or controlled corporations, they shall be tried jointly with said public officers and employees in the proper courts which shall exercise exclusive jurisdiction over them.\n\"Any provisions of law or Rules of Court to the contrary notwithstanding, the criminal action and the corresponding civil action for the recovery of civil liability shall at all times be simultaneously instituted with, and jointly determined in, the same proceeding by the Sandiganbayan or the appropriate courts, the filing of the criminal action being deemed to necessarily carry with it the filing of the civil action, and no right to reserve the filing of such civil action separately from the criminal action shall be recognized: Provided, however, That where the civil action had therefore been filed separately but judgment therein has not yet been rendered, and the criminal case is hereafter filed with the Sandiganbayan or the appropriate court, said civil action shall be transferred to the Sandiganbayan or the appropriate court, as the case may be, for consolidation and joint determination with the criminal action, otherwise the separate civil action shall be deemed abandoned.\""}},{"id":"PH-H6727-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 7 of the same decree is hereby further amended to read as follows:\n'SECTION 7. Form, Finality and Enforcement of Decisions. - All decisions and final orders determining the merits of a case or finally disposing of the action or proceedings of the Sandijanbayan shall contain complete findings of the facts and the law on which they are based, on all issues properly raised before it and necessary in deciding the case.\n\"A petition for reconsideration of any final order or decision may be filed within fifteen (15) days from promulgation or notice of the final order on judgment, and such motion for reconsideration shall be decided within thirty (30) days from submission thereon.\n\"Decisions and final orders ofthe Sandiganbyan shall be appealable to the Supreme Court by petition for review on certiorari raising pure questions of law in accordance with Rule 45 of the Rules of Court. Whenever, in any case decided by the Sandiganbayan, the penalty of reclusion perpetua, life imprisonment or death is imposed, the decision shall be appealable to the Supreme Court in the manner prescribed in the Rules of Court.\n\"Judgments and orders of the Sandiganbayan shall be executed and enforced in the manner provided by law.\n\"Decisions and final orders of other courts in cases cognizable by said courts under this decree as well as those rendered by them in the exercise of their appellate jurisdiction shall be appealable to, or be reviewable by, the Sandiganbayan in the manner provided by Rule 122 of the Rules of the Court.\n\"In case, however, the imposed penalty by the Sandiganbayan or the regional trial court in the proper exercise of their respective jurisdictions, is death, review by the Supreme Court shall be automatic, whether or not accused files an appeal.\""}},{"id":"PH-H6727-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Appropriations. - The amount necessary to carry out the initial implementation of this Act shall be charged against the current fiscal year appropriations of the Sandiganbayan. Thereafter, such sums as may be needed for its continued implementation shall be included in the annual General Appropriations Act."}},{"id":"PH-H6727-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Transitory Provision. - This Act shall apply to all cases pending in any court over which trial has not begun as of the approval hereof"}},{"id":"PH-H6727-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Separability of Provisions. - If for any reason any provision of this Act is declared unconstitutional or invalid, such parts or portions not affected thereby shall remain in full force and effect."}},{"id":"PH-H6727-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing Clause. - All acts, decrees, general orders and circulars, or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6727-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its complete publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Defining the Jurisdiction of the Sandiganbayan, Amending for the Purpose Presidential Decree No. 1606, as Amended, Providing Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6728"] = {"id":"PH-H6728","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8251_1997.html","fetchedAt":"2026-10-06","articleCount":56,"structureMode":"ARTICLE","title":{"zh":"将 Las Piñas 市镇改设为高度城市化市，名称为 Las Piñas 市的法案","en":"An Act Converting the Municipality of Las Piñas Into A Highly-urbanized City To Be Known As the City of Las Piñas","orig":"An Act Converting the Municipality of Las Piñas Into A Highly-urbanized City To Be Known As the City of Las Piñas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8251","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-12","completenessNote":"全文，共 56 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8251_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6728-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Title. – This Act shall be known as the Charter of the City of Las Piñas."},"text":{"en":"Section 1. Title. – This Act shall be known as the Charter of the City of Las Piñas."}},{"id":"PH-H6728-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"The City of Las Piñas. – The Municipality of Las Piñas shall be converted into a highly urbanized city to be known as th"},"text":{"en":"Section 2. The City of Las Piñas. – The Municipality of Las Piñas shall be converted into a highly urbanized city to be known as the City of Las Piñas, hereinafter referred to as the City, which shall comprise the present territory of the Municipality of Las Piñas in the Metropolitan Manila Area, over which it has jurisdiction, bounded by the Municipality of Parañaque and the City of Muntinlupa, Metro Manila, and the municipalities of Bacoor, Imus, and Dasmariñas, Cavite. Its bounds are approximately described as follows:\nNortheast – Cad. 299-D Parañaque Cadastre along MBM 19 of Cad 299-D to MBM 18, 17, 16, 15, 14, 13, 12 following the Parañaque River or creek to MBM 12, 11, 10, 9 to intersection of Daang Hari Road, MBM 8, all of Cad. 299-D; thence\nSoutheast – MCadm - 593-D Muntinlupa Cadastre from intersection of Daang Hari Road to MBM 8 (intersection of Alabang-Zapote Road and Daang Hari Road) to MBM 7 following Daang Hari to MBM 6 to MBM 5 (=BBM 16 Muntinlupa) to MBM 4, all of Mcad 593-D; thence to\nSouth – Imus Estate (Dasmariñas, Cavite) going west along a road to points A, B, C, D, E, F along Zapote River and Imus Estate (Imus, Cavite); thence going\nSouthwest – Bacoor, Cavite following Zapote River to BBM 31 to PBM 1 (= BBM 27) to PBM 2 (= BBM 28) to Manila Bay at mouth of Zapote River;\nNorthwest – Manila Bay from BBM 32 to BBM 26 to MBM 19.\nMetes: Beginning from point MBM-19, CAD-299-D, 14 deg 29 min 16.2 sec N., 120 deg 58 min 53.7 sec E., in the Coastal Road;\nthence to MBM-18, Cad-299-D, 14 deg 29 min 12.5 sec N., 120 deg 59 min 01.4 sec E., on Quirino Ave;\nthence to MBM-17, Cad-299-D, 14 deg 29 min 08.9 sec N., 120 deg 59 min 06.3 sec E.;\nthence to MBM-16, Cad-299-D, 14 deg 29 min 07.4 sec N., 120 deg 59 min 12.7 sec E., following Parañaque River;\nthence to MBM-15, Cad-299-D, 14 deg 28 min 50.7 sec N., 120 deg 59 min 23.6 sec E., following Parañaque River;\nthence to MBM-14, Cad-299-D, 14 deg 28 min 39.8 sec. N., 120 deg 59 min 23.1 sec E, following Parañaque River;\nthence to MBM-13 Cad-299-D, 14 deg 28 min 35.6 sec N., 120 deg 59 min 37.9 sec E., following Parañaque River;\nthence to MBM-12, Cad-299-D, 14 deg 27 min 31.5 sec N., 121 deg 00 min 00.7 sec E., following Parañaque River;\nthence to MBM-11, Cad-299-D, 14 deg 27 min 16.7 sec N., 121 deg 00 min 29.7 sec E., following Parañaque River;\nthence to MBM-10, Cad-299-D, 14 deg 26 min 58.4 sec N., 121 deg 00 min 45.1 sec E.;\nthence to MBM-9, Cad-299-D, 14 deg 26 min 19.1 sec N., 121 deg 00 min 59.7 sec E.;\nthence to MBM-8, Cad-299-D, 14 deg 26 min 14.4 sec N., 121 deg 01 min 22.9 sec E.;\nthence to MBM-8, MCadm-393-D, 14 deg 25 min 45.3 sec N., 121 deg 01 min 15.3 sec E; intersecting Alabang-Zapote Road and Daang Hari Road;\nthence to MBM-7, MCadm-393-D, 14 deg 24 min 15.3 sec N., 121 deg 0.0 min 39.3 sec E., along Daang Hari Road;\nthence to MBM-6, MCadm-393-D, 14 deg 23 min 28.9 sec N., 121 deg 0.0 min 30.2 sec E., along Daang Hari Road;\nthence to MBM-5, MCadm-593-D, 14 deg 22 min 10.2 sec N., 121 deg 0.0 min 31.5 sec E.;\nthence to MBM-4, MCadm-593-D, 14 deg 21 min 02.5 sec N., 121 deg 0.0 min 23.6 sec E.;\nthence to A, 14 deg 21 min 07.5 sec N., 121 deg 0.0 min 13.4 sec E., intersection of road and Zapote River;\nthence to B, 14 deg 21 min 25.5 sec N., 121 deg 0.0 min 22.0 sec E., following Zapote River;\nthence to C, 14 deg 21 min 42.3 sec N., 121 deg 0.0 min 20.0 sec E., following Zapote River;\nthence to D, 14 deg 22 min 19.5 sec N., 121 deg 0.0 min 22.0 sec E., following Zapote River;\nthence to E, 14 deg 22 min 52.1 sec N., 121 deg 0.0 min 36.7 sec E., following Zapote River;\nthence to F, 14 deg 24 min 05.0 sec N, 121 deg 0.0 min 05.0 sec E., following Zapote River;\nthence to Mon. 50, Imus Estate, 14 deg 24 min 40.3 sec N., 120 deg 59 min 36.0 sec E., following Zapote River;\nthence to BBM 8, MCadm-592-D, 14 deg 25 min 34.0 sec N., 120 deg 59 min 08.5 sec E., following Zapote River;\nthence to BBM 31, MCadm-592-D, 14 deg 26 min 46.6 sec N., 120 deg 58 min 13.5 sec E., following Zapote River;\nthence to BBM 30, MCadm-592-D, 14 deg 27 min 02.2 sec N., 120 deg 58 min 08.2 sec E., following Zapote River;\nthence to PBM 1 = BBM 27, MCadm-592-D, 14 deg 27 min 52.0 sec N., 120 deg 57 min 58.0 sec E., following Zapote River;\nthence to PBM 2 = BBM 28, MCadm-592-D, 14 deg 27 min 56.0 sec N., 120 deg 57 min 54.8 sec E., following Zapote River;\nthence to PBM 3 = BBM 29, MCadm-592-D, 14 deg 28 min 11.0 sec N., 120 deg 58 min 06.7 sec E., following Zapote River;\nthence to BBM 32; MCadm-592-D, 14 deg 28 min 39.2 sec N., 120 deg 58 min 17.2 sec E., Coastal Road;\nthence to BBM 24, MCadm-592-D 14 deg 28 min 54.6 sec N., 120 deg 58 min 36.9 sec E., along Manila Bay;\nthence to BBM 22, MCadm-592-D, 14 deg 28 min 58.6 sec N., 120 deg 58 min 39.4 sec E., along Manila Bay;\nthence to BBM 26 MCadm-592-D, 14 deg 29 min 07.0 sec N., 120 deg 58 min 46.1 sec E., along Manila Bay;\nthence to the point of beginning, MBM 19, Cad-299, mouth of Parañaque River;\nContaining an area of approximately 3,268.6 hectares.\nArea bounded by Points MBM 7, 6, 5, 4, (all of MCadm 593- D), A, B, C, D, E, F (all along Zapote River is subject to future delimitation).\nThe foregoing provisions shall be without prejudice to the award or resolution by the appropriate agency or forum of whatever claim that may be due to the City, or a boundary dispute that may arise or a case involving questions of territorial jurisdiction between the City of Las Piñas and any of the adjoining local government units."}},{"id":"PH-H6728-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"Corporate Powers of the City of Las Piñas. – The City constitutes a political body corporate and as such is endowed with"},"text":{"en":"Section 3. Corporate Powers of the City of Las Piñas. – The City constitutes a political body corporate and as such is endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this charter. The City shall have the following corporate powers:\n1. To have a continuous succession in its corporate name;\n2. To sue and be sued;\n3. To have and use a corporate seal;\n4. To acquire and convey real or personal property;\n5. To enter into contracts; and\n6. To exercise such other powers as are granted to corporations, subject to the limitations provided in this Act and other laws."}},{"id":"PH-H6728-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE I GENERAL PROVISIONS"},"heading":{"en":"General Powers of the City. – The City shall have an independent, common seal, and may alter the same at pleasure. It sh"},"text":{"en":"Section 4. General Powers of the City. – The City shall have an independent, common seal, and may alter the same at pleasure. It shall exercise the powers to levy taxes, and subject to the pertinent provisions of the Constitution, open or close roads, streets, alleys, parks or squares, or any other open space, including those of subdivisions, villages or compounds, in order to serve a public purpose. It may take, purchase, receive, hold, lease, convey, and dispose of real and personal property for the general interest of the City, condemn private property for public use, contract and be contracted with, sue and be sued, prosecute and defend to final judgment and execution suits wherein said city is a party, and exercise all the powers as are granted to corporations or as hereinafter conferred."}},{"id":"PH-H6728-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II CITY OFFICIALS IN GENERAL"},"heading":{"en":"The Officials of the City of Las Piñas. –"},"text":{"en":"Section 5. The Officials of the City of Las Piñas. –\na. There shall be in the City of Las Piñas a city mayor, a city vice-mayor, a sangguniang panlungsod, a sangguniang panlungsod secretary, a city treasurer, an assistant city treasurer, a city assessor, an assistant city assessor, a city accountant, a city budget officer, a city planning and development coordinator, a city engineer, a city health officer, a city civil registrar, a city administrator, a city legal officer, a city social welfare and development officer, and a city general services officer.\nb. In addition thereto, the city mayor may appoint a city architect, a city information officer, a city tourism and cultural affairs officer, a city environment officer, a city cooperatives officer, a city registrar of deeds, a city land transportation officer, a city fire marshal, a city jail warden, a city prosecutor, and a city schools division superintendent.\nc. The City of Las Piñas, through the city mayor, may:\n1. Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n2. Create such other offices as may be necessary to carry out the purpose of the City; or\n3. Consolidate the functions of any office with those of another in the interest of efficiency and economy;\nd. Unless otherwise provided herein, all appointive city officials of the City shall be appointed by the city mayor with the concurrence of the majority of all the Sangguniang Panlungsod members, subject to the Civil Service Law, rules and regulations. The Sangguniang Panlungsod shall act on the appointment within fifteen (15) days from the date of its submission, otherwise the same shall be deemed confirmed."}},{"id":"PH-H6728-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE III THE CITY MAYOR AND VICE MAYOR"},"heading":{"en":"The City Mayor. –"},"text":{"en":"Section 6. The City Mayor. –\na. The city mayor shall be the chief executive of the City. He shall be elected at large by the qualified voters of the City. No person shall be eligible for the position of city mayor unless at the time of the election he is at least twenty-three (23) years of age, an actual resident of the City for at least one (1) year prior to his election, and a qualified voter therein. He shall hold office for three (3) years, unless sooner removed, and shall receive a minimum monthly compensation corresponding to salary grade thirty (30) as prescribed under Republic Act No. 6758 and the implementing guidelines issued pursuant thereto.\nb. The city mayor, as the chief executive of the city government, shall exercise such powers and perform such duties and functions as provided herein:\n1. Exercise those powers expressly granted to him by law, those necessarily implied therefrom, as well as powers necessary, appropriate, or incidental for the efficient and effective governance of the City, and those which are essential to the promotion of general welfare:\n(aa) Determine the guidelines of city policies and be responsible to the Sangguniang Panlungsod for the program of government;\n(bb) Direct the formulation of the city development plan, with the assistance of the city development council and, upon approval thereof by the Sangguniang Panlungsod, implement the same;\n(cc) Present the program of government and propose policies and projects for the consideration of the Sangguniang Panlungsod at the opening of the regular session of the Sangguniang Panlungsod every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the city government may require;\n(dd) Initiate and propose legislative measures to the Sangguniang Panlungsod and, as often as may be deemed necessary, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(ee) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of city funds and whose appointments are not otherwise provided for in this Act, as well as those he may be authorized by law to appoint;\n(ff) Represent the City in all its business transactions and sign in its behalf all bonds, contracts, and obligations, and such other documents upon authority of the Sangguniang Panlungsod or pursuant to law or ordinance;\n(gg) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(hh) Determine the time, manner and place of payment of salaries or wages of the officials and employees of the City, in accordance with law or ordinance;\n(ii) Allocate and assign office space to city and other officials and employees who, by law or ordinance, are entitled to such space in the city hall and other buildings owned or leased by the city government;\n(jj) Ensure that all executive officials and employees of the City faithfully discharge their duties and functions as provided by law and this Act, and cause to be instituted administrative or judicial proceedings against any official or employee of the City who may have committed an offense in the performance of his official duties;\n(kk) Examine the books, records and other documents of all offices, officials, agents or employees of the City and, in aid of his executive powers and authority, require all national officials and employees stationed in or assigned to the City to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(ll) Furnish copies of executive orders issued by him to the respective council chairmen within seventy-two (72) hours after their issuance;\n(mm) Visit component barangays of the City at least once every six (6) months to deepen his understanding of problems and conditions, listen and give appropriate counsel to local officials and inhabitants of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the City will improve the quality of life of the inhabitants;\n(nn) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of their leave credits in accordance with law;\n(oo) Authorize official trips of city officials and employees outside of the City for a period not exceeding thirty (30) days;\n(pp) Call upon any national official or employee stationed in or assigned to the City to advise him on matters affecting the City and to make recommendations thereon; coordinate with said official or employee in the formulation and implementation of plans, programs and projects; and when appropriate, initiate any administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the City;\n(qq) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of city officials and employees who are injured while in the performance of their official duties and functions, subject to availability of funds;\n(rr) Solemnize marriages, any provision of law to the contrary notwithstanding;\n(ss) Conduct an annual palarong panlungsod, which shall feature traditional sports and disciplines included in national and international games, in coordination with the Department of Education, Culture and Sports; and\n(tt) Submit to the respective metropolitan authority council chairmen and to the Office of the President the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the City and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situation arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the City.\n2. Enforce all laws and ordinances relative to the governance of the City and in the exercise of its appropriate corporate powers, as well as implement all approved policies, programs, projects, services and activities of the City:\n(aa) Ensure that the acts of the City's component barangays and of its officials and employees are within the scope of their prescribed powers, duties, and functions;\n(bb) Call conventions, conferences, seminars, or meetings of elective and appointive officials and employees of the City, including national officials and employees stationed in or assigned to the City, at such time and place and on such subject as he may deem important for the promotion of the general welfare of the local government unit and its inhabitants;\n(cc) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(dd) Be entitled to carry the necessary licensed firearm within his territorial jurisdiction;\n(ee) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the City and upon its approval, implement the same; and as such, exercise general and operational control and supervision over the local police forces in the City, in accordance with Republic Act. No. 6975; and\n(ff) Call upon the appropriate law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition, or to apprehend violators of the law when public interest so requires and the city police forces are inadequate to cope with the situation or the violators.\n3. Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities, particularly those resources and revenues programmed for industrial development and countryside growth and progress:\n(aa) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process in accordance with the provisions of the Local Government Code;\n(bb) Prepare and submit to the sanggunian for approval the executive and supplemental budgets of the City for the ensuing calendar year in the manner provided for under the Local Government Code;\n(cc) Ensure that all taxes and other revenues of the city are collected, and that city funds are applied to the payment of expenses and settlement of obligations of the City, in accordance with law or ordinance;\n(dd) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(ee) Issue permits, without need of approval therefor from any national agency, for the holding of activities for any charitable or welfare purpose, excluding prohibited games of chance or shows contrary to law, public policy and public morals;\n(ff) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permit, subject to such fines and penalties as may be imposed by law or ordinance, or to make necessary changes in the construction of the same when said construction violates any law or ordinance, or to order the demolition or removal of said house, building or structure within the period prescribed by law or ordinance;\n(gg) Adopt adequate measures to safeguard and conserve land, mineral, marine, and other resources of the City;\n(hh) Provide efficient and effective property and supply management in the City; and protect the funds, credits, rights and other properties of the City; and\n(ii) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property; and cause the City to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected.\n4. Ensure the delivery of basic services and the provision of adequate facilities and, in addition thereto:\n(aa) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the City; and\n(bb) Coordinate the implementation of technical services, including public works and infrastructure programs, rendered by national offices.\n5. Perform such other duties and functions and exercise such other powers, as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE III THE CITY MAYOR AND VICE MAYOR"},"heading":{"en":"The City Vice Mayor. –"},"text":{"en":"Section 7. The City Vice Mayor. –\na. There shall be a vice-mayor who shall be elected in the same manner as the city mayor and shall, at the time of his election, possess the same qualifications as the city mayor. He shall hold office for three (3) years, unless sooner removed, and shall receive a monthly compensation corresponding to salary grade twenty eight (28) as prescribed under Republic Act No. 6758, and the implementing guidelines issued pursuant thereto.\nb. The vice-mayor shall:\n1. Act as presiding officer of the Sangguniang Panlungsod and sign all warrants drawn on the city treasury for all expenditures appropriated for the operation of the Sangguniang Panlungsod;\n2. Subject to civil service law, rules and regulations, appoint all officials and employees of the Sangguniang Panlungsod, except those whose manner of appointment is specifically provided for under existing laws;\n3. Assume the office of the city mayor for the unexpired term of the latter in the event of permanent vacancy;\n4. Exercise the powers and perform the duties and functions of the city mayor in cases of temporary vacancy; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act. No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE IV THE SANGGUNIANG PANLUNGSOD"},"heading":{"en":"The Sangguniang Panlungsod. –"},"text":{"en":"Section 8. The Sangguniang Panlungsod. –\na. The Sangguniang Panlungsod, the legislative body of the City, shall be composed of the vice mayor as presiding officer, the regular sanggunian members, the president of the city chapter of the Liga ng mga Barangay, the president of the Panlungsod na Pederasyon ng mga Sangguniang Kabataan, and the sectoral representatives, as members.\nb. In addition thereto, there shall be three (3) sectoral representatives; one (1) from the women; and, as shall be determined by the Sangguniang Panlungsod within ninety (90) days prior to the holding of the local elections, one (1) from the commercial or industrial workers; and one (1) from the other sectors, including the urban poor, or disabled persons.\nc. The regular members of the Sangguniang Panlungsod and the sectoral representatives shall be elected in the same manner as may be provided for by law. The elective members of the Sangguniang Panlungsod shall possess the same qualifications as that of the city mayor and vice-mayor.\nd. They shall receive such compensation, emoluments and allowances as may be determined by law.\ne. The Sangguniang Panlungsod shall:\n1. Approve ordinances and pass resolutions necessary for an efficient and effective city government and, in this connection, shall:\n(aa) Review all ordinances approved by the Sangguniang Barangay and executive orders issued by the punong barangay to determine whether these are within the scope of the prescribed powers of the sanggunian and of the punong barangay;\n(bb) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(cc) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000.00) or an imprisonment for a period not exceeding one (1) year, or both, in the discretion of the court, for the violation of a city ordinance;\n(dd) Adopt measures to protect the inhabitants of the City from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters or calamities and in their return to productive livelihood following said events;\n(ee) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publications, and such other activities inimical to the welfare and morals of the inhabitants of the City;\n(ff) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, smuggling of natural resources products and of endangered species of flora and fauna, and such other activities which result in pollution, acceleration of euthrophication of creeks or rivers, or of ecological imbalance;\n(gg) Subject to the provisions of the Local Government Code and pertinent laws, determine the powers and duties of\nofficials and employees of the City;\n(hh) Determine the positions and the salaries, wages, allowances, and other emoluments and benefits of officials and employees paid wholly or mainly from city funds and provide for expenditure necessary for the proper conduct of programs, projects, services, and activities of the city government;\n(ii) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity at the rate authorized by law;\n(jj) Provide a mechanism and the appropriate funds therefor, to ensure the safety and protection of all city government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the city government;\n(kk) When the finances of the city government allow, provide for additional allowances and other benefits to judges, prosecutors, public attorneys, public elementary and high school teachers, and other national government officials stationed in or assigned in the City;\n(ll) Provide legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(mm) Provide for group insurance or additional insurance coverage for all barangay officials, including members of barangay tanod brigades and other service units, with public or private insurance companies, when the finances of the city government allow said coverage.\n2. Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the City, with particular attention to commercial and industrial development and city-wide growth and progress:\n(aa) Approve the annual and supplemental budgets of the City government and appropriate funds for specific programs, projects, services and activities of the City, or for other purposes not contrary to law, in order to promote the general welfare of the City and its inhabitants;\n(bb) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all members of the Sangguniang Panlungsod, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or relief;\n(cc) Subject to the provisions of Book II of the Local Government Code and upon the majority vote of all the members of the Sangguniang Panlungsod, authorize the city mayor to negotiate and contract loans and other forms of indebtedness;\n(dd) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all the members of the Sangguniang Panlungsod, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(ee) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the City; and upon the majority vote of all the members of the Sangguniang Panlungsod, authorize the city mayor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(ff) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the City;\n(gg) Adopt a comprehensive land use for the City;\n(hh) Reclassify land within the jurisdiction of the City, subject to the pertinent provisions of the Local Government Code;\n(ii) Enact integrated zoning ordinances in consonance with the approved comprehensive land use plan, subject to existing laws, rules and regulations; establish fire limits or zones, particularly in populous centers; and regulate the construction, repair or modification of buildings within said fire limits or zones in accordance with the provisions of the Fire Code;\n(jj) Subject to national law, process and approve subdivision plans for residential, commercial, or industrial purposes and other development purposes, and to collect processing fees and other charges, the proceeds of which shall accrue entirely to the City: Provided, however, That where approval of a national agency or office is required, said approval shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval thereof;\n(kk) Subject to the provisions of Book II of the Local Government Code, grant the exclusive privilege of constructing fish corrals or fish pens, or the taking or catching of bangus fry, prawn fry of kawag-kawag, or fry of any species of fish within the City waters;\n(ll) With the concurrence of at least two-thirds (2/3) of all the members of the Sangguniang Panlungsod, grant tax exemptions, incentives or relief to entities engaged in community growth-inducing industries, subject to the provisions of the Local Government Code;\n(mm) Grant loans or provide grants to other local government units or to national, provincial, and city charitable, benevolent or educational institutions: Provided, That, said institutions are operated and maintained within the City;\n(nn) Regulate the numbering of residential, commercial and other buildings; and\n(oo) Regulate the inspection, weighing and measuring of articles of commerce.\n3. Subject to the provisions of the Local Government Code of 1991, enact ordinances granting franchises and authorizing the issuance of permits or licenses, upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the City and pursuant to this legislative authority, shall:\n(aa) Fix and impose reasonable fees and charges for all services rendered by the city government to private persons or entities;\n(bb) Regulate or fix license fees for any business or practice of profession within the City and the conditions under which the license for said business or practice of profession may be revoked and enact ordinances levying taxes thereon;\n(cc) Provide for and set the terms and conditions under which public utilities owned by the City shall be operated by the city government, and prescribe the conditions under which the same may be leased to private persons or entities, preferably cooperatives;\n(dd) Regulate the display of and fix the license fees for signs, signboards, or billboards at the place or places where the profession or business advertised thereby is, in whole or in part, conducted;\n(ee) Any law to the contrary notwithstanding, authorize and license the establishment, operation, and maintenance of cockpits, and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights shall not be impaired;\n(ff) Subject to the guidelines prescribed by the Department of Transportation and Communications, regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the City; and\n(gg) Upon approval by a majority vote of all the members of the Sangguniang Panlungsod: grant a franchise to any person, partnership, corporation, or cooperative to do business within the City; establish, construct, operate and maintain ferries, wharves, markets or slaughterhouses; or undertake such other activities within the City as may be allowed by existing laws: Provided, That, cooperatives shall be given preference in the grant of such franchise.\n4. Regulate activities relative to the use of land, buildings and structures within the City in order to promote the general welfare and for said purpose shall:\n(aa) Declare, prevent or abate any nuisance;\n(bb) Require that buildings and the premises thereof and any land within the City be kept and maintained in a sanitary condition; impose penalties for any violation thereof; or, upon failure to comply with said requirement, have the work done at the expense of the owner, administrator or tenant concerned; or require the filling up of any land or premises to a grade necessary for proper sanitation;\n(cc) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(dd) Regulate the establishment, operation and maintenance of cafes, restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses, and other similar establishments, including tourist guides and transports;\n(ee) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(ff) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the City;\n(gg) Regulate the establishment, operation, maintenance of any entertainment or amusement facilities, including theatrical performances, circuses, billiard pools, public dancing schools, public dance halls, sauna baths, massage parlors, and other places for entertainment or amusement; regulate such other events or activities for amusement or entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community;\n(hh) Provide for the impounding of stray animals; regulate the keeping of animals in homes or as part of a business, and the slaughter, sale or disposition of the same; and adopt measures to prevent and penalize cruelty to animals; and\n(ii) Regulate the establishment, operation and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations.\n5. Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided for under the Local Government Code, and in addition to said services and facilities, shall:\n(aa) Provide for the establishment, maintenance, protection, conservation of tree parks, green belts, mangroves, and other similar forest development projects;\n(bb) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof by the city government; and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(cc) Authorize the establishment, maintenance and operation by the city government of ferries, wharves, and other structures intended to accelerate productivity related to marine and seashore or offshore activities;\n(dd) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products and other foodstuffs for public consumption;\n(ee) Regulate the use of streets, avenues, alleys, sidewalks, bridges, parks and other public places and approve the construction, improvement repair and maintenance of the same; declare the turnover, in favor of the City, of a road, street, avenue, alley, park, square, or any other open space within subdivisions, villages, or residential compounds subject to existing laws; establish bus and vehicle stops and terminals and regulate the use of the same by privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; and provide for the lighting, cleaning and sprinkling of streets and public places;\n(ff) Regulate traffic on all streets and bridges; prohibit encroachments or obstacles thereon and, when necessary in the interest of public welfare, authorize the removal of encroachments and illegal constructions in public places;\n(gg) Subject to existing laws, establish and provide for the maintenance, repair and operation of an efficient waterworks system to supply water for the inhabitants and to purify the source of water supply; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and quantity of the water supply of the City, and for this purpose, extend the coverage of appropriate ordinances over all territory within the drainage area of said water supply and within one hundred (100) meters of the reservoir, conduit, canal, aqueduct, pumping station, or watershed used in connection with the water service; and regulate the consumption, use or wastage of water and fix and collect charges therefore;\n(hh) Regulate the drilling and excavation of the ground for the laying of water, gas, sewer, and other pipes and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalks, curbs, and gutters; adopt measures to ensure public safety against open canals, manholes, live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(ii) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric, telegraph and telephone wires, conduits, meters and other apparatus; and provide for the correction, condemnation or removal of the same when found to be dangerous, defective or otherwise hazardous to the welfare of the inhabitants;\n(jj) Subject to the availability of funds and to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the Department of Education, Culture and Sports and subject to existing law on tuition fees, fix and collect reasonable tuition fees and other school charges in educational institutions supported by the city government;\n(kk) Establish a scholarship fund for poor but deserving students in schools located within its jurisdiction or for students residing within the City;\n(ll) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases;\n(mm) Provide for an efficient and effective system of solid waste and garbage collection and prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(nn) Provide for the care of disabled persons, paupers, the aged, the sick, persons of unsound mind, abandoned minors, juvenile delinquents, drug dependents, abused children and youth below eighteen (18) years of age; and, subject to availability of funds, establish and provide for the operation of centers and facilities for said needy and disadvantaged persons;\n(oo) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program, and appropriate funds for the subsistence of detainees and convicted prisoners in the City;\n(pp) Establish a city council whose purpose is the promotion of culture and the arts, coordinate with government agencies and nongovernmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(qq) Establish in the City a council for the elderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the community; provide incentives for nongovernmental agencies and entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly.\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991 and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Internal Rules of Procedure. –"},"text":{"en":"Section 9. Internal Rules of Procedure. –\na. On the first regular session following the election of its members and within ninety (90) days thereafter, the Sangguniang Panlungsod shall adopt or update its existing rules of procedure.\nb. The rules of procedure shall provide for the following:\n1. The organization of the sanggunian and the election of its officers as well as the creation of standing committees which shall include, but shall not be limited to, the committees on appropriations, women and family, human rights, youth and sports development, environmental protection, and cooperatives; the general jurisdiction of each committee; and the election of the chairman and members of each committee;\n2. The order and calendar of business for each session;\n3. The legislative process;\n4. The parliamentary procedures which include the conduct of members during sessions;\n5. The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions, for which they may be censured, reprimanded, or excluded from the session, suspended for not more than sixty (60) days, or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) vote of all the sanggunian members: Provided, further, That a member convicted by final judgment and sentenced to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the sanggunian; and\n6. Such other rules as the sanggunian may adopt."}},{"id":"PH-H6728-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Full Disclosure of Financial and Business Interest of Sangguniang Panlungsod Members. –"},"text":{"en":"Section 10. Full Disclosure of Financial and Business Interest of Sangguniang Panlungsod Members. –\na. Every Sangguniang Panlungsod member shall, upon assumption to office, make a full disclosure of his business and financial interest. He shall also disclose any business, financial, or professional relationship or any relation by affinity or consanguinity within the fourth civil degree, which he may have with any person, firm or entity affected by any ordinance or resolution under consideration by the sanggunian of which he is a member, which relationship may result in conflict of interest. Such relationship shall include:\n1. Ownership of stock or capital, or investment, in the entity or firm to which the ordinance or resolution may apply; and\n2. Contracts or agreements with any person or entity which the ordinance or resolution under consideration may affect.\nIn the absence of a specific constitutional or statutory provision applicable to this situation, \"conflict of interest\" refers in general to one where it may be reasonably deduced that a member of a sanggunian may not act in the public interest due to some private, pecuniary or other personal considerations that may tend to affect his judgment to the prejudice of the service or the public.\nb. The disclosure required under this Act shall be made in writing and submitted to the secretary of the sanggunian and of the secretary of the committee of which he is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n1. Disclosure shall be made before the member participates in the deliberations on the ordinance or resolution under consideration: Provided, That, if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n2. Disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection, or professional relationship described herein."}},{"id":"PH-H6728-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Sessions. –"},"text":{"en":"Section 11. Sessions. –\na. On the first day of the session immediately following the election of its members, the Sangguniang Panlungsod shall, by resolution, fix the day, time, and place of its regular sessions. The minimum number of regular sessions shall be once a week for the Sangguniang Panlungsod.\nb. When public interest so demands, special sessions may be called by the city mayor or by a majority of the members of the sanggunian.\nc. All sanggunian sessions shall be open to the public unless a closed-door session is ordered by an affirmative vote of a majority of the members present, there being a quorum, in the public interest or for reasons of security, decency, or morality. No two (2) sessions, regular or special, may be held in a single day.\nd. In the case of special sessions of the sanggunian, a written notice to the members shall be served personally at the member's usual place of residence at least twenty-four (24) hours before the special session is held.\nUnless otherwise concurred in by two-thirds (2/3) vote of the sanggunian members present, there being a quorum, no other matters may be considered at a special session except those stated in the notice.\ne. The sanggunian shall keep a journal and record of its proceedings which may be published upon resolution of the Sangguniang Panlungsod."}},{"id":"PH-H6728-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Quorum. –"},"text":{"en":"Section 12. Quorum. –\na. A majority of all the members of the sanggunian who have been elected and qualified shall constitute a quorum to transact official business. Should a question of quorum be raised during a session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the results.\nb. When there is no quorum, the presiding officer may declare a recess until such time as a quorum is constituted, or majority of the members present may adjourn from day to day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the sanggunian, to be assisted by a member or members of the police force assigned in the territorial jurisdiction of the City of Las Piñas, to arrest the absent member and present him at the session.\nc. If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H6728-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Approval of Ordinances. –"},"text":{"en":"Section 13. Approval of Ordinances. –\na. Every ordinance enacted by the Sangguniang Panlungsod shall be presented to the city mayor. If the city mayor approves the same, he shall affix his signature on each and every page thereof; otherwise, he shall veto it and return the same with his objections to the sanggunian, which may proceed to reconsider the same. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\nb. The veto shall be communicated by the city mayor to the sanggunian within ten (10) days; otherwise, the ordinance shall be deemed approved as if he had signed it."}},{"id":"PH-H6728-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Veto Power of the City Mayor. –"},"text":{"en":"Section 14. Veto Power of the City Mayor. –\na. The city mayor may veto any ordinance of the Sangguniang Panlungsod on the ground that it is ultra vires or prejudicial to the public welfare, stating his reasons therefore in writing.\nb. The city mayor shall have the power to veto any particular item or items of an appropriations ordinance, an ordinance or resolution adopting a local development plan and public investment program, or an ordinance directing the payment of money or creating liability. In such a case, the veto shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the Sangguniang Panlungsod overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\nc. The city mayor may veto an ordinance or resolution only once. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the city mayor."}},{"id":"PH-H6728-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Review of Barangay Ordinances by the Sangguniang Panlungsod. –"},"text":{"en":"Section 15. Review of Barangay Ordinances by the Sangguniang Panlungsod. –\na. Within ten (10) days after its enactment, the Sangguniang Barangay shall furnish copies of the barangay ordinance to the Sangguniang Panlungsod for review as to whether the ordinance is consistent with law and city ordinances.\nb. If the Sangguniang Panlungsod fails to take action on the barangay ordinance within thirty (30) days from receipt thereof, the same shall be deemed approved.\nc. If the Sangguniang Panlungsod finds the barangay ordinance inconsistent with law or city ordinances, the Sangguniang Panlungsod shall, within thirty (30) days from receipt thereof, return the same with its comments and recommendations to the Sangguniang Barangay concerned for adjustment, amendment, or modification; in which case, the effectivity of the barangay ordinance is suspended until such time as the revision called for is effected."}},{"id":"PH-H6728-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Enforcement of Disapproved Ordinances or Resolutions. – Any attempt to enforce any ordinance or any resolution approving"},"text":{"en":"Section 16. Enforcement of Disapproved Ordinances or Resolutions. – Any attempt to enforce any ordinance or any resolution approving the local development plan and public investment program, after the disapproval thereof, shall be sufficient ground for the suspension or dismissal of the official or employee concerned."}},{"id":"PH-H6728-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE V PROCESS OF LEGISLATION"},"heading":{"en":"Effectivity of Ordinance or Resolution. –"},"text":{"en":"Section 17. Effectivity of Ordinance or Resolution. –\na. Unless otherwise stated in the ordinance or the resolution approving the local development plan and public investment program, the same shall take effect after ten (10) days from the date a copy thereof is posted on a bulletin board at the entrance of the City Hall of Las Piñas, and in at least two (2) other conspicuous places in the City of Las Piñas.\nb. The secretary of the Sangguniang Panlungsod shall cause the posting of an ordinance or resolution on the bulletin board at the entrance of the City Hall of Las Piñas and in at least two (2) conspicuous places in the City of Las Piñas not later than five (5) days after approval thereof.\nThe text of the ordinance or resolution shall be disseminated and posted in Filipino or English, and in the language or dialect understood by the majority of the people in the City, and the secretary of the Sangguniang Panlungsod shall record such fact in a book kept for the purpose, stating the dates of approval and posting.\nc. The main features of the ordinance or resolution duly enacted or adopted shall, in addition to being posted, be published once in a local newspaper of general circulation within the City: Provided, That in the absence thereof, the ordinance or resolution shall be published in any newspaper of general circulation: Provided, further, That the gist of all ordinances with penal sanctions shall also be published in a newspaper of general circulation."}},{"id":"PH-H6728-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Disqualifications for Elective City Officials. – The following persons are disqualified from running for any elective po"},"text":{"en":"Section 18. Disqualifications for Elective City Officials. – The following persons are disqualified from running for any elective position in the City:\na. Those sentenced by final judgment for an offense involving moral turpitude or for an offense punishable by one (1) year or more of imprisonment, within two (2) years after serving sentence;\nb. Those removed from office as a result of an administrative case;\nc. Those convicted by final judgment for violating the oath of allegiance to the Republic of the Philippines;\nd. Those with dual citizenship;\ne. Fugitives from justice in criminal or nonpolitical cases here and abroad;\nf. Permanent residents in a foreign country or those who have acquired the right to reside abroad and continue to avail of the same right after the effectivity of the Local Government Code; and\ng. The insane or feeble-minded"}},{"id":"PH-H6728-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Permanent Vacancy in the Office of the City Mayor and City Vice Mayor. –"},"text":{"en":"Section 19. Permanent Vacancy in the Office of the City Mayor and City Vice Mayor. –\na. If a permanent vacancy occurs in the office of the city mayor, the city vice mayor concerned shall become the city mayor. If a permanent vacancy occurs in the office of the vice-mayor, the highest ranking Sangguniang Panlungsod member or, in case of his permanent incapacity, the second highest Sangguniang Panlungsod member, shall become the city mayor or city vice-mayor, as the case may be. Subsequent vacancies in the said offices shall be filled automatically by the other sanggunian members according to their ranking as defined herein.\nb. A tie between or among the highest ranking Sangguniang Panlungsod members shall be resolved by the drawing of lots.\nc. The successors as defined herein shall serve only the unexpired terms of their predecessors.\nFor purposes of this Act, a permanent vacancy arises when an elective local official fills a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions of his office.\nFor purposes of succession as provided in this Act, ranking in the sanggunian shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in the City in the immediately preceding local election."}},{"id":"PH-H6728-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Permanent Vacancies in the Sanggunian. – Permanent vacancies in the Sangguniang Panlungsod where automatic succession as"},"text":{"en":"Section 20. Permanent Vacancies in the Sanggunian. – Permanent vacancies in the Sangguniang Panlungsod where automatic succession as provided above does not apply shall be filled by appointment in the following manner:\n1. The President, through the Executive Secretary, shall make the aforesaid appointment;\n2. Only the nominee of the political party under which the sanggunian member concerned had been elected and whose elevation to the position next higher in rank created the last vacancy in the sanggunian shall be appointed in the manner herein provided. The appointee shall come from the same political party as that of the sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office.\nIn the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be a ground for administrative action against the official responsible therefore;\n3. In case the permanent vacancy is caused by a sanggunian member who does not belong to any political party, the city mayor shall, upon recommendation of the Sangguniang Panlungsod, appoint a qualified person to fill the vacancy; and\n4. In case of vacancy in the representation of the youth and the barangay in the Sangguniang Panlungsod, said vacancy shall be filled automatically by the official next in rank of the organization concerned.1aшphi1"}},{"id":"PH-H6728-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE VI DISQUALIFICATIONS AND SUCCESSION OF ELECTIVE CITY OFFICIALS"},"heading":{"en":"Temporary Vacancy in the Office of the City Mayor. –"},"text":{"en":"Section 21. Temporary Vacancy in the Office of the City Mayor. –\na. When the city mayor is temporarily incapacitated to perform his duties for physical or legal reasons such as, but not limited to, leave of absence, travel abroad, and suspension from office, the city vice-mayor, or the highest ranking Sangguniang Panlungsod member shall automatically exercise the powers and perform the duties and functions of the city mayor, except the power to appoint, suspend, or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\nb. Said temporary incapacity shall terminate upon submission to the Sangguniang Panlungsod of a written declaration by the city mayor that he has reported back to office. In cases where the temporary incapacity is due to legal causes, the city mayor shall also submit necessary documents showing that said legal causes no longer exist.\nc. When the city mayor is traveling within the country but outside his territorial jurisdiction for a period not exceeding three (3) consecutive days, he may designate in writing the officer-in-charge of his office. Such authorization shall specify the powers and functions that the local official concerned shall exercise in the absence of the city mayor except the power to appoint, suspend, or dismiss employees.\nd. In the event, however, that the city mayor fails or refuses to issue such authorization, the city vice-mayor, or the highest ranking Sangguniang Panlungsod member, as the case may be, shall have the right to assume the powers, duties and functions of the said office on the fourth day of absence of the city mayor, subject to the limitations provided in subsection (c) hereof.\ne. Except as provided above, the city mayor shall in no case authorize any legal official to assume the powers, duties and functions of the office, other than the city vice-mayor, or the highest ranking member of the Sangguniang Panlungsod, as the case may be."}},{"id":"PH-H6728-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Secretary to the Sangguniang Panlungsod. –"},"text":{"en":"Section 22. The Secretary to the Sangguniang Panlungsod. –\na. There shall be a secretary to the Sangguniang Panlungsod with the rank and salary equal to a head of a department or office.\nb. No person shall be appointed secretary to the Sangguniang Panlungsod unless he is a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in law, commerce or public administration from a recognized college or university, and a first grade civil service eligible or its equivalent.\nThe secretary to the Sangguniang Panlungsod shall take charge of the office of the Sangguniang Panlungsod, and shall:\n1. Attend meetings of the Sangguniang Panlungsod and keep a journal of its proceedings;\n2. Keep the Seal of the City and affix the same with his signature to all ordinances, resolutions, and other official acts of the Sangguniang Panlungsod and present the same to the presiding officer for his signature;\n3. Forward to the city mayor, for approval, copies of ordinances enacted by the Sangguniang Panlungsod, as duly certified by the presiding officer;\n4. Furnish, upon request of any interested party, certified copies of records of public character in his custody, upon payment to the city treasurer of such fees as may be prescribed by ordinance;\n5. Record in a book kept for the purpose, all ordinances and resolutions enacted or adopted by the Sangguniang Panlungsod, with the dates of passage and publication thereof;\n6. Keep his office and all non-confidential records therein open to the public during the usual business hours;\n7. Translate into the dialect used by the majority of inhabitants all ordinances and resolutions immediately after their approval, and cause the publication of the same together with the original version in the manner provided under the Local Government Code;\n8. Take custody of the local archives and where applicable, the local library and annually account for the same; and\n9. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Treasurer. –"},"text":{"en":"Section 23. The City Treasurer. –\na. The city treasurer shall be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the city mayor, subject to civil service law, rules and regulations.\nb. The city treasurer shall be under the administrative supervision of the city mayor, to whom he shall report regularly on the tax collection efforts of the City.\nc. No person shall be appointed city treasurer unless he is a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in treasury or accounting service for at least five (5) years.\nd. The city treasurer shall receive such compensation, emoluments and allowances as may be determined by law.\ne. The city treasurer shall take charge of the treasury office, and shall:\n1. Advise the city mayor, the Sangguniang Panlungsod, and other local government and national officials concerned regarding disposition of local government funds and on such other matters relative to public finance;\n2. Take custody and exercise proper management of the funds of the City;\n3. Take charge of the disbursement of all funds of the City and such other funds the custody of which may be entrusted to him by law or other competent authority;\n4. Inspect private commercial and industrial establishments within the jurisdiction of the City in relation to the implementation of tax ordinances, pursuant to the provisions of the Local Government Code;\n5. Maintain and update the tax information system of the City; and\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Assistant City Treasurer. –"},"text":{"en":"Section 24. The Assistant City Treasurer. –\na. The assistant city treasurer may be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the city mayor, subject to Civil Service Law, rules and regulations.\nb. No person shall be appointed assistant city treasurer unless he is a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired at least five (5) years experience in treasury or accounting immediately preceding the day of his appointment.\nc. The assistant city treasurer shall receive such compensation, emoluments and allowances as may be determined by law.\nd. The assistant city treasurer shall assist the city treasurer and perform such other duties as the latter may assign to him. He shall have authority to administer oaths concerning notices and notifications to those delinquent in the payment of the real property tax and concerning official matters relating to the accounts of the city treasurer or otherwise arising from the offices of the city treasurer and the city assessor."}},{"id":"PH-H6728-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Assessor. – (a) The city assessor must be a citizen of the Philippines, a resident of the City of Las Piñas, of"},"text":{"en":"Section 25. The City Assessor. – (a) The city assessor must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in real property assessment work or in any related field for at least five (5) years immediately preceding the day of his appointment.\na. The city assessor shall receive such compensation, emoluments and allowances as may be determined by law.\nb. The city assessor shall take charge of the City Assessor's Office and shall:\n1. Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purpose are properly executed;\n2. Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purpose;\n3. Establish a systematic method of real property assessment;\n4. Install and maintain a real property identification and accounting system;\n5. Prepare, install and maintain a system of tax mapping, showing graphically all property subject to assessment and gather all data concerning the same;\n6. Conduct frequent physical surveys to verify and determine whether all real properties within the City are properly listed in the assessment rolls;\n7. Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the City;\n8. Prepare a schedule of the fair market values of the different classes of real properties in accordance with the provisions of the Local Government Code;\n9. Issue, upon request of any interested party, certified copies of assessment records of real property and all other records relative to its assessment, upon payment of a service charge or fee to the city treasurer;\n10. Submit every semester a report of all assessments as well as cancellations and modifications of assessments, to the city mayor and Sangguniang Panlungsod; and\n11. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The Assistant City Assessor. –"},"text":{"en":"Section 26. The Assistant City Assessor. –\na. The assistant city assessor must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in assessment or in any related field for at least three (3) years immediately preceding the day of his appointment.\nb. The assistant city assessor shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The assistant city assessor shall assist the city assessor and perform such other duties as the latter may assign to him. He shall have the authority to administer oaths on all declarations of real property for purposes of assessment."}},{"id":"PH-H6728-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Accountant. –"},"text":{"en":"Section 27. The City Accountant. –\na. The city accountant must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a certified public accountant. He must have acquired experience in the treasury or accounting service for at least (5) years immediately preceding the day of his appointment.\nb. The city accountant shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city accountant shall take charge of both the Office on Accounting and Internal Audit Services and shall:\n1. Install and maintain an internal audit system in the City;\n2. Prepare and submit financial statements to the city mayor, and to the Sangguniang Panlungsod;\n3. Apprise the Sangguniang Panlungsod and other officials on the financial condition and operations of the City;\n4. Certify to the availability of budgetary allotment to which expenditures and obligations may be properly charged;\n5. Review supporting documents before preparation of vouchers to determine completeness of requirements;\n6. Prepare statements of cash advances, liquidation, salaries, allowances, reimbursements and remittances pertaining to the City;\n7. Prepare statements of journal vouchers and liquidation of the same, and other adjustments related thereto;\n8. Post individual disbursements to the subsidiary ledger and index cards;\n9. Maintain individual ledgers for officials and employees of the City pertaining to payrolls and deductions;\n10. Record and post in index cards details of purchased furniture, fixtures, and equipment, including disposal thereof, if any;\n11. Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n12. Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n13. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Budget Officer. –"},"text":{"en":"Section 28. The City Budget Officer. –\na. The city budget officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in accounting, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in government budgeting or in any related field for at least five (5) years immediately preceding the date of his appointment.\nb. The city budget officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city budget officer shall take charge of the City Budget Office and shall:\n1. Prepare forms, orders, and circulars embodying instructions on budgetary and appropriations matters for the signature of the city mayor;\n2. Review and consolidate the budget proposals of different departments and offices of the City;\n3. Assist the City Mayor, in the preparation of the budget and during hearings;\n4. Study and evaluate budgetary implications of proposed legislation and submit comments and recommendations thereon;\n5. Submit periodic budgetary reports to the Department of Budget and Management;\n6. Coordinate with the city treasurer, the city accountant and the city planning and development coordinator for the purpose of budgeting;\n7. Assist the Sangguniang Panlungsod in reviewing the approved budgets of component barangays of the City;\n8. Coordinate with the city planning and development coordinator in the formulation of the development plan of the City; and\n9. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Planning and Development Coordinator. –"},"text":{"en":"Section 29. The City Planning and Development Coordinator. –\na. The city planning and development coordinator must be a citizen of the Philippines, a resident of City of Las Piñas, of good moral character, a holder of a college degree preferably in urban planning, development studies, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in development planning or in any related field for at least five (5) years immediately preceding the date of his appointment.\nb. The city planning and development coordinator shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city planning and development coordinator shall take charge of the City Planning and Development Office and shall:\n1. Formulate integrated economic, social, physical, and other development plans and policies for consideration of the City;\n2. Conduct continuing studies, researches, and training programs necessary to evolve plans and programs for implementation;\n3. Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or agencies;\n4. Monitor and evaluate the implementation of the different development programs, projects, and activities in the City in accordance with the approved development plan;\n5. Prepare comprehensive plans and other development planning documents for the consideration of the local development council;\n6. Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for consideration of the finance committee of the Sangguniang Panlungsod;\n7. Promote people participation in development planning within the City; and\n8. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Engineer. –"},"text":{"en":"Section 30. The City Engineer. –\na. The city engineer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a licensed civil engineer. He must have acquired experience in the practice of his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city engineer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city engineer shall take charge of the City Engineering Office and shall:\n1. Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in infrastructure development and public works projects of the City;\n2. Advise the city mayor on infrastructure, public works, and other engineering matters;\n3. Administer, coordinate, supervise, and control the construction, maintenance, improvement, and the repair of roads, bridges, and other engineering and public works projects of the City;\n4. Provide engineering services to the City, including investigation and survey, engineering designs, feasibility studies, and project management; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Health Officer. –"},"text":{"en":"Section 31. The City Health Officer. –\na. The city health officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral and character, a licensed medical practitioner. He must have acquired experience in the practice of his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city health officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city health officer shall take charge of the Office of the City Health Services and shall:\n1. Supervise the personnel and staff of said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the city mayor, in order to assist him in the efficient, effective and economical implementation of a health services program geared towards the implementation of health-related projects and activities;\n2. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out activities to ensure the delivery of basic services and provision of adequate facilities relative to health services;\n3. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning health programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n4. Be in the front line of the delivery of health services, particularly during and in the aftermath of man-made and natural disasters and calamities; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Civil Registrar. –"},"text":{"en":"Section 32. The City Civil Registrar. –\na. The city civil registrar must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in civil registry work for at least five (5) years immediately preceding the date of his appointment.\nb. The city civil registrar shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city civil registrar shall be responsible for the civil registration program in the City of Las Piñas, pursuant to the Civil Registry Law, the Civil Code, and other pertinent laws, rules and regulations issued to implement them.\nd. The city civil registrar shall take charge of the office of the City Civil Registry and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning civil registry programs and projects which the Sangguniang Panlungsod is empowered to provide; and\n2. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Administrator. –"},"text":{"en":"Section 33. The City Administrator. –\na. The city administrator must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, holding a college degree preferably in public administration, law, or any related course from a recognized college, university, and a first grade civil service eligible or its equivalent. He must have acquired experience in management and administration work for at least five (5) years immediately preceding the date of his appointment.\nb. The city administrator shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city administrator shall take charge of the Office of the City Administrator and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the management and administration-related programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Be in the front line of the delivery of administrative support services, particularly those related to the situation during and in the aftermath of man-made and natural disasters and calamities;\n3. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters relative to the management and administration of the City; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Legal Officer. –"},"text":{"en":"Section 34. The City Legal Officer. –\na. The city legal officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a member of the Philippine Bar. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city legal officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city legal officer, the chief legal counsel of the City, shall take charge of the Office for Legal Services and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide legal assistance and support to the city mayor in carrying out the delivery of basic services and the provision of adequate facilities;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning programs and projects related to legal services which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Recommend measures to the Sangguniang Panlungsod and advise the city mayor on all matters related to upholding the rule of law;\n4. Be in the front line of protecting human rights and prosecuting any violation thereof, particularly those which occur during and in the aftermath of man-made or natural disasters and calamities; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Social Welfare and Development Officer. –"},"text":{"en":"Section 35. The City Social Welfare and Development Officer. –\na. The city social welfare and development officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a duly licensed social worker or a college degree holder preferably in sociology, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the practice of social work for at least five (5) years immediately preceding the date of his appointment.\nb. The city social welfare and development officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city social welfare and development officer shall take charge of the Office on Social Welfare and Development and shall:\n1. Formulate measures for the approval of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to social welfare and development services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning social welfare programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Be in the front line of service delivery, particularly those concerning immediate relief and assistance during and in the aftermath of man-made and natural disasters and natural calamities;\n4. Recommend to the Sangguniang Panlungsod and advise the city mayor on all other matters relative to social welfare and development services which will improve the livelihood and living conditions of the inhabitants; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Architect. –"},"text":{"en":"Section 36. The City Architect. –\na. The city architect must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a duly licensed architect. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\nb. The city architect shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city architect shall take charge of the Office of Architectural Planning and Design and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to architectural planning and design;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning architectural planning and design of programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Be in the front line of delivery of services involving architectural planning and design, particularly those related to the redesigning of spatial distribution of basic facilities and physical structures during and in the aftermath of man-made and natural disasters and calamities;\n4. Recommend to the Sangguniang Panlungsod and advise the city mayor on all other matters relative to this architectural planning and design as its relates to the total socioeconomic development of the City; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Information Officer. –"},"text":{"en":"Section 37. The City Information Officer. –\na. The city information officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in journalism, mass communication or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in writing articles and research papers, or in writing for print, television or broadcast media for at least three (3) years immediately preceding the date of his appointment.\nb. The city information officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city information officer shall take charge of the Media Affairs and Public Information Office and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in providing the information and research data required for the delivery of basic services and provision of adequate facilities so that the public becomes aware of said services and may fully avail of the same;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning public information and research data to support programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Be in the front line in providing information during and in the aftermath of man-made and natural disasters and calamities, with special attention to the victims thereof, to help minimize injuries and casualties during and after the emergency, and to accelerate relief and rehabilitation;\n4. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters relative to public information and research data as they relate to the total socioeconomic development of the City; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Environment Officer. –"},"text":{"en":"Section 38. The City Environment Officer. –\na. The city environment officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in environmental management, conservation, and utilization work for at least five (5) years immediately preceding the date of his appointment.\nb. The city environment officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city environment officer shall take charge of the Office on the Environment and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to environment services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning environment programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Be in the front line of the delivery of services concerning the environment, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made natural disasters and calamities;\n4. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters relative to the protection, conservation, maximum utilization, application of appropriate technology and other matters related to the environment; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Cooperatives Officer. –"},"text":{"en":"Section 39. The City Cooperatives Officer. –\na. The city cooperatives officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree preferably in business administration with special training in cooperatives or any course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in cooperatives organization and management for at least five (5) years immediately preceding the date of his appointment.\nb. The city cooperatives officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city cooperatives officer shall take charge of the Office for the Development of Cooperatives and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of facilities through the development of cooperatives, and in providing access to such services and facilities;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning the integration of cooperative principles and methods in programs and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Be in the front line of cooperatives organization, rehabilitation or viability-enhancement, particularly during and in the aftermath of man-made and natural calamities and disasters, to aid in their survival and, if necessary, subsequent rehabilitation;\n4. Recommend to the Sangguniang Panlungsod and advise the city mayor on all other matters relative to cooperatives development and viability-enhancement which will improve the livelihood and quality of life of the inhabitants; and\n5. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City General Services Officer. –"},"text":{"en":"Section 40. The City General Services Officer. –\na. The city general services officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree in public administration, business administration and management from a recognized college or university and a first grade civil service eligible or its equivalent. He must have acquired experience in general services, including management of supply, property, solid waste disposal, and general sanitation for at least five (5) years immediately preceding the date of his appointment.\nb. The city general services officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city general services officer shall take charge of the Office of General Services and shall:\n1. Formulate measures for the consideration of the Sangguniang Panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities which require general services expertise and technical support services;\n2. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those concerning general services supportive of the welfare of the inhabitants of the City which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n3. Take custody of and be accountable for all properties, real or personal, owned by the City, and those granted to it in the form of donation, reparation, assistance and counterpart of joint projects;\n4. Be in the front line of general services-related activities, such as the possible or imminent destruction or damage to records, supplies, properties, and structure materials or debris, particularly during and in the aftermath of man-made and natural disasters and calamities;\n5. Recommend to the Sangguniang Panlungsod and advise the city mayor on all other matters relative to general services; and\n6. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Tourism and Cultural Affairs Officer. –"},"text":{"en":"Section 41. The City Tourism and Cultural Affairs Officer. –\na. The city tourism and cultural affairs officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree and a first grade civil service eligible or its equivalent. He must have acquired experience in tourism and cultural affairs work for at least three (3) years immediately preceding the date of his appointment.\nb. The city tourism and cultural affairs officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city tourism and cultural affairs officer shall take charge of the Office of Tourism and Cultural Affairs and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the tourism and cultural affairs development and management and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Be in the front line in the determination of repair and reconstruction work related to tourism and cultural affairs, particularly during and in the aftermath of man-made and natural disasters and calamities;\n3. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters relative to the tourism and cultural affairs in the City; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6728-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Land Transportation Officer. –"},"text":{"en":"Section 42. The City Land Transportation Officer. –\na. The city land transportation officer must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree and a first grade civil service eligible or its equivalent. He must have acquired experience in land transportation work for at least three (3) years immediately preceding the date of his appointment.\nb. The city land transportation officer shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city land transportation officer shall be under the direct supervision of the Land Transportation Office of the Department of Transportation and Communications, shall take charge of the City Land Transportation Office and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the land transportation regulation, development and management, and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters related to land transportation in the City; and\n3. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law, ordinance, or Department of Transportation and Communications and Land Transportation Office rules and regulations."}},{"id":"PH-H6728-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Prosecutor. –"},"text":{"en":"Section 43. The City Prosecutor. –\na. The city prosecutor must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a member of the Philippine Bar. He must have acquired experience in handling criminal cases in court for at least three (3) years immediately preceding the date of his appointment.\nb. The city prosecutor shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city prosecutor shall be under the direct supervision of the Department of Justice, shall take charge of the Office of the City Prosecutor and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the prosecution of criminals and crime syndicates, and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters related to the prosecution of criminals and crime syndicates in the City; and\n3. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law, ordinance or relevant Department of Justice rules and regulations."}},{"id":"PH-H6728-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Schools Division Superintendent. –"},"text":{"en":"Section 44. The City Schools Division Superintendent. –\na. The city schools division superintendent must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience practicing his profession in an educational institution for at least three (3) years immediately preceding the date of his appointment.\nb. The city schools division superintendent shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city schools division superintendent shall be under the direct supervision of the Department of Education, Culture and Sports, shall take charge of the Office of the City Schools Division Superintendent and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with education development and management programs, and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters related to education in the City;\n3. Be in the front line in the supervision of principals and teachers assigned in the City, as well as sit as additional member of the local school board of the City; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law, ordinance or relevant Department of Education, Culture and Sports rules and regulations."}},{"id":"PH-H6728-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Fire Marshal. –"},"text":{"en":"Section 45. The City Fire Marshal. –\na. The city fire marshal must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, and a qualified fire marshal under Republic Act No. 6975, otherwise known as the PNP Law.\nb. The city fire marshal shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city fire marshal shall be under the direct supervision of the Department of the Interior and Local Government, shall take charge of the City Fire Station and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with fire prevention, control and management, and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters related to fire services in the City;\n3. Be in the front line in the development of measures for fire protection, prevention and suppression, rescue and evacuation, and other services intended for the safety and security of life and property in the City; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 6975, otherwise known as the PNP Law, Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law, ordinance or relevant Department of the Interior and Local Government's rules and regulations."}},{"id":"PH-H6728-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE VII THE APPOINTIVE OFFICIALS OF THE CITY, THEIR QUALIFICATIONS, POWERS AND DUTIES"},"heading":{"en":"The City Jail Warden. –"},"text":{"en":"Section 46. The City Jail Warden. –\na. The city jail warden must be a citizen of the Philippines, a resident of the City of Las Piñas, of good moral character, a holder of a college degree in psychology, psychiatry, sociology, social work or criminology from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience practicing his profession for at least three (3) years immediately preceding the date of his appointment.\nb. The city jail warden shall receive such compensation, emoluments and allowances as may be determined by law.\nc. The city jail warden shall be under the direct supervision of the Department of the Interior and Local Government, shall take charge of the City Jail and shall:\n1. Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with custody and safekeeping of inmates, jail administration and management, and other programs that are helpful in the reformation of inmates, and projects which the city mayor is empowered to implement and which the Sangguniang Panlungsod is empowered to provide;\n2. Recommend to the Sangguniang Panlungsod and advise the city mayor on all matters related to jail services in the City;\n3. Be in the front line in the development of measures for a more efficient and effective city jail system; and\n4. Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 6975, otherwise known as the PNP Law, Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law, ordinance or relevant Department of the Interior and Local Government's rules and regulations."}},{"id":"PH-H6728-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Municipal Ordinances. – All municipal ordinances of the Municipality of Las Piñas existing at the time of the approval o"},"text":{"en":"Section 47. Municipal Ordinances. – All municipal ordinances of the Municipality of Las Piñas existing at the time of the approval of this Act shall continue to be in force within the City of Las Piñas until the Sangguniang Panlungsod shall, by ordinance, provide otherwise."}},{"id":"PH-H6728-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Plebiscite. – The City of Las Piñas shall acquire corporate existence upon the ratification of its creation by a majorit"},"text":{"en":"Section 48. Plebiscite. – The City of Las Piñas shall acquire corporate existence upon the ratification of its creation by a majority of the votes cast by the qualified voters in a plebiscite to be conducted in the present Municipality of Las Piñas within sixty (60) days from the approval of this Act. The expenses for such plebiscite shall be borne by the Municipality of Las Piñas. The Commission on Elections shall conduct and supervise such plebiscite."}},{"id":"PH-H6728-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Officials of the City of Las Piñas. – The present elective officials of the City shall continue to exercise their powers"},"text":{"en":"Section 49. Officials of the City of Las Piñas. – The present elective officials of the City shall continue to exercise their powers and functions until such time that a new election is held and the duly-elected officials shall have already qualified and assumed their offices. The appointive officials and employees of the City shall likewise continue exercising their functions and duties and they shall automatically be absorbed by the city government of the City of Las Piñas."}},{"id":"PH-H6728-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Jurisdiction of Metropolitan Manila. – The City of Las Piñas shall, unless otherwise provided by law, continue to be und"},"text":{"en":"Section 50. Jurisdiction of Metropolitan Manila. – The City of Las Piñas shall, unless otherwise provided by law, continue to be under the jurisdiction of Metropolitan Manila."}},{"id":"PH-H6728-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Legislative District. – As a highly-urbanized city, the City of Las Piñas shall have its own legislative district with t"},"text":{"en":"Section 51. Legislative District. – As a highly-urbanized city, the City of Las Piñas shall have its own legislative district with the first representative to be elected in the next national election after the passage of this Act."}},{"id":"PH-H6728-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Tax Moratorium. – Upon the effectivity of this Act, the City of Las Piñas shall maintain a tax moratorium for five (5) y"},"text":{"en":"Section 52. Tax Moratorium. – Upon the effectivity of this Act, the City of Las Piñas shall maintain a tax moratorium for five (5) years, wherein no increase in the rates of taxes shall be imposed. Furthermore, it shall abide by the provisions of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1991, which limit the authority of local government units in adjusting tax rates which shall not be oftener than once every five (5) years, but in no case shall such adjustment exceed ten percent (10%) of the rates fixed under the said Code."}},{"id":"PH-H6728-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Moratorium on Gambling Sites. – Upon the effectivity of this Act, the City of Las Piñas shall also maintain a moratorium"},"text":{"en":"Section 53. Moratorium on Gambling Sites. – Upon the effectivity of this Act, the City of Las Piñas shall also maintain a moratorium on the establishment of gambling sites for five (5) years, wherein no new gambling site, place or venue for cockfighting, lotto, or any other form of gambling or games of chance, shall be allowed to be built or established within the City."}},{"id":"PH-H6728-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Applicability of Laws. – The provisions of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1"},"text":{"en":"Section 54. Applicability of Laws. – The provisions of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1991, Presidential Decree Numbered Eight hundred and twenty-four, and other laws pertaining to Metropolitan Manila and such laws as are applicable to highly-urbanized cities shall govern the City of Las Piñas in so far as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H6728-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Separability Clause. – If any part or section of this Act is declared unconstitutional for any reason whatsoever, such d"},"text":{"en":"Section 55. Separability Clause. – If any part or section of this Act is declared unconstitutional for any reason whatsoever, such declaration shall not in any way affect the other parts or sections of this Act."}},{"id":"PH-H6728-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"ARTICLE VIII TRANSITORY AND FINAL PROVISIONS"},"heading":{"en":"Effectivity. – This Act shall take effect fifteen (15) days from its publication in the Official Gazette or in at least"},"text":{"en":"Section 56. Effectivity. – This Act shall take effect fifteen (15) days from its publication in the Official Gazette or in at least two (2) newspapers of national circulation.\nApproved, February 12, 1997."}}],"pack":"ph-p95","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Municipality of Las Piñas Into A Highly-urbanized City To Be Known As the City of Las Piñas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"},"recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra1997/ra_8251_1997.html 重抓，56 → 56 条"};
  FT["PH-H6729"] = {"id":"PH-H6729","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8252_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Mambajao市","en":"Mambajao Charter Day","orig":"An Act Declaring July Six of Every Year A Special Nonworking Public Holiday in the Municipality of Mambajao, Province of Camiguin, To Be Known As \"Mambajao Charter Day\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8252","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8252_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6729-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July six is the charter day anniversary of the Municipality of Mambajao, Province of Camiguin, and its celebration is highlighted with colorful parade, stage drama, and beauty pageant."}},{"id":"PH-H6729-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"July six of every year is hereby declared a special nonworking public holiday in the Municipality of Mambajao."}},{"id":"PH-H6729-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, February 11, 1997."}}],"pack":"ph-p95"};
  FT["PH-H6730"] = {"id":"PH-H6730","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8253_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Mahinog市","en":"Mahinog Charter Day","orig":"An Act Declaring July One of Every Year A Special Nonworking Public Holiday in the Municipality of Mahinog, Province of Camiguin, To Be Known As \"Mahinog Charter Day\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8253","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8253_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6730-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July one is the charter day anniversary of the Municipality of Mahinog, Province of Camiguin, and its celebration is highlighted with colorful parade and beauty pageant."}},{"id":"PH-H6730-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"July one of every year is hereby declared a special nonworking public holiday in the Municipality of Mahinog."}},{"id":"PH-H6730-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, February 11, 1997."}}],"pack":"ph-p95"};
