  FT["PH-H6734"] = {"id":"PH-H6734","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8257_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Mahatao市","en":"An Act Converting the Batanes National High School - Mahatao Branch Located in the Municipality of Mahatao, Province of Batanes, Into An Independent National High School To Be Known As the Mahatao National High School and Appropriating Funds Therefor","orig":"An Act Converting the Batanes National High School - Mahatao Branch Located in the Municipality of Mahatao, Province of Batanes, Into An Independent National High School To Be Known As the Mahatao National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8257","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8257_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6734-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Batanes National High School – Mahatao Branch located in the Municipality of Mahatao, Province of Batanes, is hereby converted into an independent national high school to be known as the Mahatao National High School under the Department of Education, Culture and Sports."}},{"id":"PH-H6734-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, personnel and properties such as buildings, sites and improvements thereof, including fund allocations for the Batanes National High School - Mahatao Branch are hereby transferred to the Mahatao National High School."}},{"id":"PH-H6734-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6734-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Batanes National High School - Mahatao Branch. Thereafter, such sums as may be necessary for the operation and maintenance of the Mahatao National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6734-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
  FT["PH-H6735"] = {"id":"PH-H6735","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8258_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Casiguran市","en":"An Act Establishing A National High School in the Municipality of Casiguran, Province of Aurora, To Be Known As the Lual National High School, and Appropriating Funds Therefor","orig":"An Act Establishing A National High School in the Municipality of Casiguran, Province of Aurora, To Be Known As the Lual National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8258","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8258_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6735-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in the Municipality of Casiguran, Province of Aurora, to be known as the Lual National High School."}},{"id":"PH-H6735-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6735-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p95"};
